with nuevas(numero,viejo,sec) as (values
(225,'3c40a8bfb38efcf1402ad490dd3b5b6f',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ọ̀ṣẹ́ defiende de la brujería, los maleficios y toda energía negativa. El consultante puede enfrentar un conflicto con el gobierno o una disputa en su asociación, familia o casa. Pide ofrendar antes de un viaje para que quien queda cuidando la casa no enferme, y cuidar con quién se une uno."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme un pleito con una autoridad.", "Quiere actuar por su cuenta.", "Se siente rodeado de hostilidad o de rumores."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Protección contra toda brujería.", "Una pareja que acompañe el alma.", "Volver de viaje y encontrar la casa en pie.", "Atrapar al animal más fiero con astucia."]}, {"titulo": "Ibi y advertencias", "puntos": ["Hechicería y maleficios.", "Una mujer que trae el mal disfrazado de amor.", "Ir desarmado a lo desconocido.", "Que los aprendices actúen sin el maestro."]}, {"titulo": "Enseñanza principal", "texto": "El que choca con las espinas del ọ̀gàn se pincha; el que choca con Èṣù sale perjudicado. El hijo de la tortuga no sigue a la tortuga madre: el Ifá del muerto no afecta al hijo ajeno."}, {"titulo": "Relatos reunidos", "puntos": ["El cazador y sus tres perros. La oscuridad se traga a las gallinas enteras: así adivinaron para un cazador que iba a la finca, y le dijeron que allí encontraría esposa, pero que ofrendara para que ella no le trajera mal. Ofreció tres perros y dinero. El cazador tenía tres perros con los que cazaba. En la finca se le acercó una comerciante que le compraba toda la carne, y él no sabía que era un espíritu malo de los árboles. Un día ella lo invitó a conocer su casa, porque él le había dicho que quería casarse con ella. Al llamar a sus perros, ella dijo: ¿vas a casa de tu esposa y llamas a tus perros? Enciérralos. Tomó su escopeta, y ella le dijo: ¿vas a hacer la guerra? Tomó su machete, y ella: ¿vas a cortar cabezas? Lo dejó todo y se puso una túnica fina. Pero su esposa mayor le dijo: ¿no eres cazador? ¿cómo vas a ir donde gente que no conoces sin un cuchillo? Él escondió el cuchillo bajo la túnica. Al entrar en el monte, todos los árboles saludaban a la mujer y se acercaban; él quiso huir, pero los árboles le cerraron el camino para matarlo. Corrió, trepó a un árbol y cantó llamando a sus perros por sus nombres. Al instante sus tres perros llegaron corriendo desde la casa, atacaron a los espíritus de los árboles y los vencieron, y el cazador volvió a casa con ellos.", "Ọ̀rúnmìlà, el leopardo y la red. Ọ̀rúnmìlà salió de viaje a la orilla del océano y les dijo a sus aprendices que no tocaran su tablero ni echaran sus semillas hasta que volviera. Al tercer mes, ellos tocaron el tablero, cantaron sus cantos y echaron las semillas. Apareció una señal en el santuario que protege al rey de la muerte, y el rey mandó buscar a Ọ̀rúnmìlà; como no estaba, consultaron los tres aprendices, salió Ìrẹtẹ̀ Ọ̀ṣẹ́, y pidieron al rey dinero, tres ovejas, un leopardo y una tela. Todo Ifẹ̀ rodeó a un leopardo en el monte y llamaron a los aprendices para atraparlo, pero no pudieron, y el leopardo mató a uno. Ese día Ọ̀rúnmìlà tuvo un mal sueño, consultó, y le dijeron que volviera de inmediato. Al llegar compró una red, metió dentro una chiva pequeña y la lanzó al monte; la chiva baló, el leopardo corrió hacia ella y quedó atrapado en la red. Mientras lo cargaba, el leopardo le arañó la mano: esas marcas son los cuatro ojos que tienen hasta hoy las semillas de Ifá. Así hicieron la ofrenda del rey. Quien viaja y deja a alguien a cargo de la casa debe ofrendar para que Ṣànpọ̀nná no lo enferme antes de su regreso.", "Las espinas de Èṣù. El que choca con las espinas del ọ̀gàn, las espinas del ọ̀gàn lo pinchan; el que choca con las espinas de Èṣù, las espinas de Èṣù lo pinchan; el que choca con Èṣù, Èṣù lo perjudica. Este es el rezo de protección de este Odù.", "Las dos cosas enormes. Cuando bajaron, bajaron sobre dos cosas descomunales, y Olódùmarè dictó la ley: dos cosas enormes no pueden caer una sobre otra. El hijo de la tortuga no sigue a la tortuga madre, el hijo del caracol no sigue al caracol madre, el hijo de la serpiente no sigue a la serpiente madre: el Ifá de un muerto no afecta al hijo de otro. Que toda brujería dirigida contra mí sea inútil."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la pareja: tres perros y dinero, y comprar papilla de maíz con parte del dinero.", "Para el viaje: dinero, tres ovejas y una tela; poner manteca de karité sobre el Ifá y matar un caracol encima antes de ofrecerle una chiva.", "Medicina contra el maleficio: una piedra yangi de Èṣù, tres cuchillos nuevos de herrero, corteza espinosa de ipara y de otras plantas espinosas y rastreras en una cazuela con agua; el polvo de ipara se marca con el Odù, se reza y se añade; se sella siete días y se usa para bañarse, no para beber.", "Medicina contra la brujería: tortuga, caracol, serpiente y corteza de dos árboles de ìrókò quemados hasta hacer polvo, guardado en un àdó; se marca el Odù, se reza, se mezcla con aceite de palma y se lame o se unta."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù castiga al que choca con él. Olódùmarè dicta la ley de las dos cosas enormes. Ṣànpọ̀nná. Ọ̀rúnmìlà y sus aprendices."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ọ̀gàn (Combretum), ipara, corteza de ìrókò, piedra yangi, tortuga, caracol, serpiente, manteca de karité, red."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 225.1 (yorùbá): Forilakú, F'orilakú, F'orilakú. / Agbogboniwonran, / Agbogboniwonran, / Agbogboniwonran. / Ekùn Amomonibuu, / Ekùn Amomonibuu, / Ẹkùn Amomonibuu. / Ẹniti o ba dugbolu egun ogan, / egun gán a gún un. / Eniti o ba dugbo lu egun èṣú, / egun èṣú, a gún un. / Eniti o ba dubolu Eṣú, / Eṣú a ṣee ati bẹẹbẹẹ.", "Verso 225.2 (yorùbá): ljala, ljala, ljala. / Alagere-idẹ, / Alagere-idẹ, / Alagere-idẹ. / Qworonikoko, / Qworonikoko, / Qworonikoko. / Ondèse ni yeye wọn. / Nigbi wọn maa rọ̀; / wọn rọ sori gbakongbakon Méjì. / Olódùmarè wa paṣẹ I: / gbakongbakon Méjì kiijà lu ara wọn. / Ọmo awun / kiito awun lehin ati bẹẹbẹẹ, / Ọmọ igbin / ki i tọ igbín lẹhin ati bẹẹbẹẹ. / Ọmọ ejò / kiitọ ejò lẹhin ati bẹẹbẹẹ. / Ifá okú / kiiro omo elomiran. / Ki Isasi àwọn Olisasi / ma le mu mi ati bẹẹbẹẹ.", "REZO: IRETE UNFA EKOKO OSHO ERO BIRIWO DOGODO AY KOSHEKA BI AYE ADIFAFUN OUN BABALAWO SHELE ERE LEBO. MAFEREFUN ESHU ATI YALORDE.", "REZO: IRETE OTUN MOWO SHESHE BONI SAYE MOWO GRI GRI BINI NILONA EÑI, AWADO, ATITAN ERI MERIN, ERURU ELEBO. OÑI TUTO ETUTU ILE AWO IRETE UNFA.", "REZO: IRETE UNFA OTUN MOGUN SHESHE BONI SALE MOBO GRI GRI BONI NIJONA OÑI, AWADO ERITA META ERURU, OMI TUTO, ETUTU ILE AWO IRETE UNFA KOKO OSHE ERO MAFEREFUN ESHU ATI YALORDE.", "SUYERE: ERAN TITI ORORO OMO MAYO. ERAN TITI ORORO AGUEMA KOSHIYE ORORO. WINI WINI OLELE OYA NKALA KALA OLELE.", "OKOKO OSHE ERO BIRIWO DOGODO AYA KOSHEKA AYA KOSHEKA BI AYE ADIFAFUN AUN BABALAWO SHELE ERE LEBO. MAFEREFUN ESHU ATI OSHUN."]}]$q$::jsonb),
(226,'1e0e05f82d7f3b473824c21826d442df',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Òfún trae fama y éxito por medio de Ifá: el negocio o trabajo del consultante mejorará. Pide cuidar mucho a la madre, porque es su guía, y ofrendar para que la esposa no sea atormentada de noche. Quien quiere construir encontrará quién le ayude."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["El trabajo o el negocio empieza a mejorar.", "Su buena fama atrae a más gente que le pide ayuda (relato de Ọ̀rúnmìlà y los clientes).", "Debe decidir cuánto compartir sin descuidar sus obligaciones (relato de Animo-Ọla).", "Tiene que atender a su madre (relato de Òténgélè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Muchos clientes y crecimiento del trabajo.", "La protección del espíritu de la madre.", "Ayuda para construir la casa.", "Generosidad que nunca deja en necesidad."]}, {"titulo": "Ibi y advertencias", "puntos": ["Descuidar a la madre.", "Pesadillas y dolores del cuerpo en la esposa.", "Presumir de lo que no se puede hacer."]}, {"titulo": "Enseñanza principal", "texto": "Las personas generosas nunca pasan necesidad. La madre es el Orí que acompaña al hijo: lo que se le da a ella vuelve en protección."}, {"titulo": "Relatos reunidos", "puntos": ["Òténgẹ́lẹ̀ y la tela roja. Òténgẹ́lẹ̀ preguntó si escaparía del mal que lo rodeaba. Le dijeron que el espíritu de su madre no lo abandonaría y le pidieron una rata èmó, una tela blanca que la madre pudiera atarse a la cabeza y dinero; debía cocinar la rata para que su madre comiera, porque la boca que come acepta la ofrenda para la cabeza. Òténgẹ́lẹ̀ había presumido ante sus compañeros que podía convertir una tela roja en blanca. Después de ofrendar vinieron a retarlo y dejaron caer una tela roja; sin que nadie supiera cómo, la tela roja fue cambiada por una blanca. Fue la madre de Òténgẹ́lẹ̀ quien lo hizo. Si la madre vive, se le compra una tela para la cabeza y una rata para ofrecer a su Orí; si murió, se prepara la rata y se cuelga con la tela blanca en su tumba.", "Kì, el que asusta de noche. Kì causaba terror a la gente en medio de la noche. Les pidieron ofrendar: él una cabra y la esposa un gallo. Lo hicieron, y cantaban: Kì, por favor no nos persigas; Kì, te lo rogamos. Ifá dice que hay quien intenta iniciar a la esposa en una sociedad mala a través de los sueños, y que ella se quejará de dolores del cuerpo; también, que quien quiere construir debe levantar cuatro postes y un techo de paja, y encontrará gente que le ayude.", "Ọ̀rúnmìlà y los muchos clientes. A Ọ̀rúnmìlà le dijeron que tendría muchos clientes y que todos vendrían a iniciarse. Ofreció una paloma, una gallina y dinero.", "Animọ̀ọ̀la y lo que la boca come. A Animọ̀ọ̀la Animaṣahun le dijeron que la ofrenda era todo lo que la boca puede comer: una calabaza de ñame machacado, un recipiente de sopa, nueces de kola y dinero. Obedeció, y el adivino dijo: las personas generosas nunca tendrán necesidades."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la madre: una rata èmó, una tela blanca y dinero.", "Contra las pesadillas: una cabra (él) y un gallo (la esposa); un rollo de tela.", "Para los clientes: una paloma, una gallina y dinero.", "Para no pasar necesidad: ñame machacado, sopa, nueces de kola y dinero para compartir."]}, {"titulo": "Relaciones espirituales", "texto": "El espíritu y el Orí de la madre. Ọ̀rúnmìlà recibe a quienes vienen a iniciarse."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Rata èmó, tela blanca, ñame machacado, obì (kola), paja de techo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 226.1 (yorùbá): Ìrẹtẹ̀-Òfún: / a difá fún Ọ̀rúnmìlà, / Wọ̀n ni Ọ̀rúnmìlà ma a r'awo ṣe. / Awọn èniyàn yoo maa wa gba Ifá, / wọ̀n yoo maa wa tẹ Ifá. / Wọ̀n niki Ọ̀rúnmìlà wa rúbọ: / Eyẹlé, adiye / ati egbàáwa owó. / Ó gbọ̀ ó rú.", "Verso 226.2 (yorùbá): Ìrẹtẹ̀-Òfún: / a daa fún Animo-ğla Animaṣahun. / Wọ̀n niki o wa rúbọ, / wọn ni: / Ohun gbogbo ti ẹnú i jẹ niki o wa rú, / Igbá iyán ati awo obẹ, obi / ati egbaáwa owó. / Ô gbọ̀ ó rú. / Wọ̀n nì: / \"Oloore kiigbainilayé\".", "REZO: IRETE FILE MAFEREFUN SHANGO, ORUNMILA MALU YAMODE YAMUREO SHANGO KABIOSILE ORI ONLE BILELONA YAMODE OBINI LODE OGOGO MEYI LA IFA ASHEGUN OTA KOLEÑODIO OYALE ORUNMILA UNSHINSHE EBBO. MALU SHANGO ODOBALE.", "REZO: IRETE OFUNDI OYE KORUPALE ADIFAFUN ETA RINLA INAYA KAFEREFUN EYA ESHU Y ORUNMILA.", "REZO: IRETE FUN DIOYE KORUPALE ADIFAFUN ETA TINLA IBAYA KAFEREFUN IYA, ESHU ATI ORUNMILA.", "REZO: ADIFAFUN AWO MALU MUYRE SOKIN IMBOWA NI OLOFIN INLO NI ILE AWO BELEGUN OYU MINIOSI ORUNMILA UN SORO KOWA DUDU IGBO ESHU EHUBI INI FILA FORIBALE AWO OBARA DELELE OBA AWO MAYURE ODDUN AWO MALU ADE OBA ORISHA ASO OBA ILU LODAFUN ORUNMILA KAFEREFUN ESHU.", "REZO: IRETE FILE KAJE LELI EWE NI KASU LELI OMO, KAFILIEKE ASHO FUN FUN ARA ADIFAFUN ORUNMILA GBOGBO UNLO AYONILE, OBA OLBESHI OMO ODUDUWA A OKO LAKUON.", "REZO: IGUI ADAWA MOYE LODAFUN IGUI, ODUDUWA ASHIWERE IBORU ORUNMILA AFEFE, LODAFUN LERI NI ODUDUWA.KAFEREFUN ORUNMILA.", "+++"]}]$q$::jsonb),
(227,'61af37cf37565c989c22eaa09b0b8aa9',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ogbè advierte contra juntarse con gente mala. Si se ofrenda, los sufrimientos pasados se cambian por prosperidad: es sabio sufrir al principio y prosperar al final. Las tentaciones emocionales causan trastornos pasajeros. Hay quien le paga el bien con mal y una mujer cercana que le impide enderezar sus asuntos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["No le han pagado un trabajo (relato de Ọlojà-ẹrú en el mercado).", "Una sociedad aprovecha su esfuerzo sin darle lo justo.", "Necesita cobrar una deuda sin caer en la avaricia.", "La familia prepara una celebración o un nombramiento y pide bendiciones para un hijo (relato de Olórùbu Ẹ̀gúsí)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Prosperidad al final de los sufrimientos.", "Dinero, pareja, hijos, título y vida larga.", "Un hijo que vuelve a hablar.", "Que no se arruine el destino en vida."]}, {"titulo": "Ibi y advertencias", "puntos": ["Comer sin dar su parte a Èṣù.", "Que le paguen el bien con mal.", "Una mujer con poderes que lo frena.", "Pedir consejo a un enemigo que luego cuenta todo.", "Mala suerte que parece maldición."]}, {"titulo": "Enseñanza principal", "texto": "Es sabio sufrir al comienzo y prosperar al final. Al que come y bebe sin dar a Èṣù, Èṣù lo deja ciego."}, {"titulo": "Relatos reunidos", "puntos": ["Igaliyerẹ los dejó ciegos. Ọ̀rúnmìlà dijo que es sabio sufrir al principio y prosperar al final, y que se ofrece una chiva a Èdú. Hubo quienes comieron y no le dieron de comer a Igaliyerẹ, bebieron y no le dieron de beber; Igaliyerẹ los dejó ciegos. Igaliyerẹ es un nombre de Èṣù.", "Ọlọ́jà Ẹrú y el mal pago. A Ọlọ́jà Ẹrú, que es el nombre del àtíro, le pidieron un chivo y dinero para que no le pagaran con maldad. Se negó. Llevó sus cargas al mercado y su bondad le fue pagada con mal.", "El rey de Ara. Ọ̀ṣẹ́ que levanta polvo adivinó para el rey de Ara, que lloraba porque no tenía dinero. Ofreció cuatro palomas y frijoles blancos cocidos, y le dijeron que nadie tendría tanto dinero como él. Tuvo dinero, pero le faltaban esposas: ofreció dos gallinas y una calabaza, y las tuvo. Le pidieron un gallinero lleno de gallos para tener hijos, y los tuvo. Le dijeron que tomaría un título y ofreció un carnero, una tela blanca y una calabaza de tiza; le dijeron que duraría mucho en el cargo y ofreció cuatro palomas blancas y una tela blanca. Llegó a ser tan viejo que tenían que sacarlo a calentarse al sol. Cantaba: escogeré dinero, escogeré hijos, y no podré irme.", "El rey y la mujer pájaro. Hierba de pie, hierba èruwà de pie, levántate y baila a casa delante de ellos: así adivinaron para el rey y para su esposa Ameri. Un hombre consentía en todo a una mujer, pero ella era bruja y no dejaba que sus asuntos se enderezaran; ofrendaba y no servía, hacía medicina y no funcionaba. Le pidieron seis pollitos, seis palitos con liga de cazar pájaros y ñame machacado sazonado, llevados a su finca. Ató los pollitos a una bandeja de cestería y puso los palitos con liga en el borde. La esposa mayor se convirtió en pájaro y voló a la finca; oyó a los pollitos, bajó, empezó a comer el ñame, quedó pegada a la liga y murió. Ifá advierte que hay una mujer pájaro junto a esta persona, y que el que da consejo puede ser un enemigo que luego lo contará todo.", "El camaleón y la mala cabeza. Lagartija tonta adivinó para el camaleón hace mucho tiempo. Hay un hombre del que todo el mundo piensa mal: ofrenda y no le sirve, hace medicina y no le funciona, porque vino del cielo con mala cabeza. Debe ofrecer dos palomas y dinero para que su suerte no sea del todo mala, y lavarse la cabeza en el río.", "El hijo que no hablaba. Al rey del trono de los blancos le pidieron un chivo grande, una tinaja de agua, dinero y la tela de la cintura de una mujer embarazada de su casa. No ofreció. Nació un varón al que llamaron La Corona Anda con Honor, pero no hablaba. Lo llevaron con los cazadores de búfalos y los búfalos le bramaron, y no habló; lo llevaron con los cazadores de elefantes y los elefantes le barritaron, y tampoco. La tortuga dijo que ella lo haría hablar, y el rey prometió darle la mitad de su casa. La tortuga pidió dos cargas de varas y mucha miel, y puso la miel en un camino. Todos los que pasaban la probaban; cuando el muchacho metió el dedo y la lamió, la tortuga salió del monte, lo acusó de robarle la miel y empezó a azotarlo. Cuando le pegó en el cuello, el muchacho gritó y cantó: La Corona Anda con Honor, hijo de Ọ̀ṣin; fui con los elefantes a su monte, fui con los búfalos a su finca, robé la miel del animalito; ¿de quién es la miel? De mi padre. Así empezó a hablar, y el rey, feliz, le dio a la tortuga la mitad de todo lo que tenía. Ifá pide ofrendar por la mujer embarazada para que el niño no nazca mudo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para prosperar al final: una chiva a Èdú (Ọ̀rúnmìlà) y dar a Èṣù su parte.", "Contra el mal pago: un chivo y dinero.", "Para el dinero, la pareja, los hijos y el título: cuatro palomas y frijoles blancos; dos gallinas y una calabaza; un gallinero de gallos; un carnero, tela blanca y una calabaza de tiza; cuatro palomas blancas y tela blanca.", "Contra la mujer pájaro: seis pollitos, seis palitos con liga y ñame machacado sazonado, llevados a la finca.", "Contra la mala suerte: dos palomas y dinero; lavar la cabeza con hierba gbẹ̀gìdínà pisoteada, jabón y una paloma machacada en una calabaza con tapa, y echar el resto en un río que corre.", "Por la embarazada: un chivo grande, una tinaja de agua, dinero y la tela de la cintura de la mujer."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù como Igaliyerẹ. Èdú (Ọ̀rúnmìlà). El Rey del Cielo crea un mercado de gente para el anciano. Ọ̀ṣin, el rey."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Gbẹ̀gìdínà (hierba), jabón, liga de pájaros, ñame machacado, frijoles blancos, tiza, tela blanca, miel, varas de àtòrì."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 227.1 (yorùbá): Arinnaperanjẹ-Ese, / Ologbof'oṣis'orun-o-njarege, / Ọ̀rúnmìlà I wọ̀n iba f'oṣisiwájú kiwon / foros'ẹ̀hin kiwọn / m'ewúrẹ k'Ẹ̀dú. / 1 wọn je, / wọn ko fun Igaliyẹrẹ jẹ / wọn mu wọn ko fún Igaliyerẹ mu. / Igaliyẹrẹ nfi oṣuṣu ṣu wọn loju / Igaliyerẹ oruko a p'Eṣú.", "Verso 227.2 (yorùbá): Itẹ-yuẹ: / li o dífá f'Ọlojà-ẹrú. / Wọ̀n niki ó rúbọ: / öbúko ati egbètaelọ̀gbọ̀n owó, / ki wọ̀n ma baa fi ibi suu. / Ko rú bọ. / Ọlojà-ẹrú oruko a pe Atiro, / o ba wọn r'ẹrú d'ọjà, / wọn fi ibi ṣuu.", "/ OSHE OGBE", "REZO: AWO OCHINA ADIFAFUN ORUNMILA NIBATI OLOSORDO OLOKUN. ACUELOBABADA AGUOCALLE OWO CHINA ADIFAFUN ORUMILA UMBATI LOSORDO OLOKUN.", "REZO: OSHE LOGBE ABA ABAREGUIN WORI ORBEBORU AYA ORBE AECHE OBAN BURUKU KOPADERENO APA ETU AYEGUN TOSO AYE BABA KUNLE KOKUNLE LOMO ADIFAFUN ALUGONDO ARBATOLO ILU OYO LERBO FIRU LLENE HOPELO PARABA AWO COLLE AWO ACHINA ADIFAFUN ORUNLA NIBATI UNLOSODO OLOKUN EBBO ABEBOADIE MEYI EYELE MEYI AWADO OWO LA MEYI.", "FUN YERE OWO CONE GUANI OBA COGUI GUAMI GUICUAMI (SE REPITE).", "REZO: OSHE NILOGBE OTOROMU OTOLAYE ADIFAFUN OLUWO BUERE, IKU KOMPANI KOMPANI. ARUN KOMPANI KOMPANI, OFO KOMPANI KOMPANI, EYO KOMPANI KOMPANI, OGU KOMPANI KOMPANI.", "SUYERE: BABA AWO OSHE OSHE MOWA OSHE OSHE.", "REZO: OLOFIN OKO OSHE OJAJUMO ONJE EKRUAYEFOYU OLOFIN FESFOWU KAYOSHE AWO, ADIFAFUN OLOFIN, LODAFUN OSHE NILOGBE OYU OLOFIN ERE, KAFEREFUN ELEGWA Y ORUNMILA.", "SUYERE: AYEFOYU OLOFIN FISHOWA KAYOSHE OU OLOFIN, LODAFUN ORUNMILA.", "REZO: OTOROMU OTURO AYE ADIFAFUN OMO OLUGUERE OLOKUN OSA NILOGBE OSHE NILOGBE OTUROMU OTURO AYE OMO ASUNKOM- PANI ENI OLOKUN OSHANLA GUENIBEOLOKUN IYA AYE BONI-", "GUA AYEBA GUENI AYE TIRUNO NIGBO OSHE LOGBE BABA OSI OTOROMU OTURO AYE OMO OLUGUERE IYA BENIÑUA AYE AYALUGA."]}]$q$::jsonb),
(228,'7e8526cc453314febffd5471c611886d',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ọ̀yẹ̀kú enseña a prosperar por medio de la popularidad: como el vendedor de aceite y manteca, a quien todos buscan. La vida diaria del consultante fluye. Pide ofrendar para no caer en la pobreza ni tener que mendigar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su vida diaria va bien, pero quiere estabilidad económica y que su trabajo se conozca.", "Busca clientes o reconocimiento (relato de Ọ̀ṣẹ́ y los vendedores de aceite).", "Piensa empezar una disciplina espiritual y debe sostenerla en vez de aplazarla."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Popularidad y clientela.", "No caer en la pobreza."]}, {"titulo": "Ibi y advertencias", "puntos": ["Mendicidad y pobreza."]}, {"titulo": "Enseñanza principal", "texto": "La gente busca a quien tiene lo que todos necesitan: el que vende aceite y manteca nunca está solo."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀ṣẹ́ y las calabazas de los vendedores. Àjíṣẹ̀gírí y Aníkansekosunwọ̀n adivinaron para Ọ̀ṣẹ́ y le pidieron ofrendar para volverse popular y no ser un pordiosero. Le marcaron la calabaza grande donde el vendedor guarda el aceite de palma, la calabaza donde guarda la manteca de karité, dinero y medicina de Ifá. Escuchó y ofreció. Los que venden aceite y manteca son buscados por todos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["La calabaza del vendedor de aceite de palma, la del vendedor de manteca de karité, dinero y medicina de Ifá.", "Medicina: corteza de raíz de ìfọ̀n machacada con la pulpa del fruto de àrìdan y jabón negro, con un pedacito de cada calabaza incrustado; se guarda en una calabaza con tapa y se usa para bañarse."]}, {"titulo": "Relaciones espirituales", "texto": "Los vendedores del mercado."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ìfọ̀n (Olax longipetala), àrìdan (Tetrapleura tetraptera), jabón negro, aceite de palma, manteca de karité."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 228.1 (yorùbá): Ajiṣegiri, / Anikansekosunwòn: / a difá fỌ̀ṣẹ. / Wọ̀n niki Ọ̀ṣẹ́ wa rúbọ / ki o baa le di Ọloni, / kio ma baa di aṣiṣẹ. / A niki ó rú: / Igbá elepo, Igbá Olòri, egberindilógún owó ati ewé Ifá / Ó gbó ó rú.", "REZO: OSHE YEKU BORO BOSHE YEKU BORORO OFO IBAI BORO ONA OBAYE BE IFA OSHE BE IFA OSHE YEKU NAWAYEBE OFA YONYO ODARA MOLONI MOLERUN INLE ELEGBARA OSHE BORORO OSHE BARI BARI BOSHE YEKU BOROBORO AWA YONI IFA WAWA YENI. ELEGBARA WAWA YENI IFA OSHE OBATALA WAWA RE OSHE YEKU BORI BOSHE ORUNMILA BEYEKUN MAWA YONI IFA BOROBORO ENI BOYE SHANGO ENI BOYE IKU.", "SUYERES: BORO BOSHE YEBI OLONA BORO BOSHE BOSHE YEBI, OLONA AWA BOROBORO AWAIKU.", "AGONGO NILE WAWAO AGOGO ELEGBARA ” ” ” ” IKU ” ” ” ” ORISHA ” ” ” ” GBOGBO EGUN ” ” ” ” OLOFIN, ORUNMILA.", "REZO: OSHE YEKU BORO BORO YEKU BORORO OFE, IBAI BORO REONA OBAYE BE IFA OSHE YEKU, BAWYE BE IFA YOYO ODARA MELONI MOLORU ELEGBA OSHE BORORO OSHE, BARI BARI BOSHE YEKU, BORO BORO AWAYONI IFA WAWAYONI ELEGBA, WAWAYONI IFA OSHE OBATALA, WEWERE OSHE YEKU BARI BOSHE, ORUNMILA BEYEKU MAWAYONI IFA, BORO BORO ENI BOYE IKU."]}]$q$::jsonb),
(229,'6341e29ea86861da50f124ec68f7245a',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ìwòrì promete poder y grandeza, y avisa que, mal usados, pueden destruir el hogar. Dedicar demasiado tiempo al trabajo amenaza las relaciones familiares y sociales. Promete dominio de las dificultades y victoria sobre los enemigos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Trabaja tanto que descuida a su familia y a sus amigos.", "Un ascenso o más influencia le trae problemas nuevos.", "Las palabras duras, el orgullo o las discusiones pueden dividir su casa (relato de quien construyó su casa y la destruyó con la boca).", "Le conviene escuchar el consejo de los mayores."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Volverse un gran hombre.", "Dominio de las dificultades.", "Victoria sobre los enemigos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Destruir con la propia boca la casa que uno construyó.", "Descuidar a la familia por el trabajo."]}, {"titulo": "Enseñanza principal", "texto": "Tuletule Ẹgá construyó su propia casa y la derribó con su boca. Quien reta al apá muere por el apá; quien reta al ìrókò se enfrenta al ìrókò."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀ṣẹ́ e Ìwòrì contra los que retan. Lo mío hace lo de ellos: así adivinaron para Ọ̀ṣẹ́ y para Ìwòrì. Quien reta al apá muere por el apá; quien reta al ìrókò se enfrenta al ìrókò. Le dijeron que sería un gran hombre, con dominio sobre las dificultades y victoria sobre sus enemigos. Le pidieron un carnero, doscientas piedras de tirar, dinero y medicina de Ifá. Escuchó y ofreció.", "El que deshizo su casa con la boca. Tuletule Ẹgá construyó su casa y con su boca la derribó: así adivinaron para Olúfijàbí, el que deshace la casa con su enojo. Le pidieron un caracol, manteca de karité, aceite de palma, plátanos maduros pequeños, dinero y medicina de Ifá para que su hogar no se dispersara. Oyó y se negó."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la victoria: un carnero, doscientas piedras de tirar, dinero y medicina de Ifá.", "Medicina: granito y pimienta de caimán molidos con iyẹ̀ ìròsùn del Odù, mezclados en comidas de maíz para el consultante.", "Para el hogar: un caracol, manteca de karité, aceite de palma, plátanos maduros, dinero y medicina de Ifá; comer plátanos maduros a menudo, echar aceite de palma a Elégbára y manteca de karité a Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Elégbára recibe aceite de palma. Ifá recibe manteca de karité."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pimienta de caimán, granito, plátanos maduros, manteca de karité, aceite de palma, apá, ìrókò."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 229.1 (yorùbá): Temi-a-sé-tiwọn: / a difá fOṣé, / a bufun Ìwòrì. / Eniti o ba dariso Apá, / Apa-a-paa / Eniti o ba dariso lroko, / Irókò a koo lọna. / Wọ̀n ni: / \"Ọ̀ṣẹ́'wòri a di eni-nlá, / a ṣégun òdi a rehin ọ̀tá\". / Ki wọ̀n rú: Agbo, igba oko, / ogbonkànlá owó ati ewé Ifa. / Ó gbọ̀ ó rú.", "Verso 229.2 (yorùbá): Tuletule-Ẹgá kole tan / fi ẹnú ara rẹ tuu, / a dífá f'Olúfijabi / Abinútan-fi-ogbungbun-tú-ilé-ka. / Wọ̀n niki o wa ṣebọ / ki ilé rẹ ma le tuka: / Igbin, òrí, epo, gèdè wẹerẹ ti ó pón, / ẹgbàájo owó ati ewe lfa. / Ó gbọ̀ ko ru.", "REZO: OSHE PAURE SHILEKONPEGBO OLORUN, SHILEKONPEGBO INLE MOKUE AYE ASHE NIFA MORI YEYEO WAN WAN LAYE IFA, ADIFAFUN OLOWO IFANYOKO TELENIFA SHILEKONPEGBO ORUMALE WAMALE ASHE EBO ASHE TO.", "REZO: OSHE PAURE OWARA AWO BABA AFEFE AWEYE IFA BABA SHERE KODEFUN YEYE, BABA SHIRE KODEFUN EBO. BABA SHIRE KODEFUN ORUNMILA. BABA SHIRE KODEFUN OLOFIN, GBOGBO TENUNYEN ELEBO.", "SUYERES: EWA YENI CLORUN AYAWAO. SHANGO OÑI AGBEO. OSUN ENI ADDE. OSHUN AYAWAO SHANGO.", "OSHE PAURE YEYERE YEWARA ONI ABANSHELU OFITO MOYA LODAFUN OSHE PAURE.", "REZO: OSHE MODEJO IWORI MOGUN YEWE LODAFUN ORUN LA OJUPON OLOBIAYAMAFE AWO OGUNGUN OMO ELESE OLORUN AYAGUDI EGUNGUN AYAN SILE NIYERE YEYE EGGUN ORUN SALE MI OBANILOSHE AWO EGGUN OSHE MODEJO LOPAURE BOGBO OBA- LUN, GBOGBO EGGUN KOBELOPE, OTUNRUNWA GBENI LORDAFUN ORUNMILA, ADIFAFUN ORISHAOKO.", "SUYERE: ” OSHE PAURE AWO MOLE ESE OLORUN OMOLE ESE OLORUN ” .", "REZO: OKOI ILE ISUN EKUE ABAKUA IGBO INLEKAGA IREME AKUA- RAMINA ATARE NGONGO IYA OTOBUMI OFO INLE BOLELE", "IBAMODE OSHE PAURE IGBA IKU AGUEDENO UAN AGUEDE ILU ESHU OBINA OMODE KOBELE FO NASAKO MASMORI NATAWO KUNDIMAYE ABITI INLE IREME ASOTERETAN ORUNMILA ADIFANFUN OLONA ISUNEKUE EBO ADA ABAKUA NILE.", "SUYERE: AKUAN AKUAREMINA TAN BANSERE ABINA BABANILE.", "REZO: OSHE PAURE AWO ORUN INLE BORI BOSHE OMO SHABI AWO ORUN OMO SARAON INTORI OBINI OZUE EYO OGU, NI SARAON ELEGWA OYU UN SORO AWO ORUN IFA OMO DISHE OLOFIN ADA AWO ORUN OSHE PAURE EYA TUTO PELEKEKE IFA ORI AWO OLOFIN SHEKUE OMO SARAON OBINI OFO EYO AWO OSHE PAURE AWO ORUN KAFEREFUN OLOFIN KAFEREFUN ELEGWA.", "REZO: ADIFAFUN ERIMI AWO OSHE PAURE AWATE NIFA AJANA IFA IFE LEDE OBETUA LELE NI AWO OSHE PAURE AYEGBE YERUME OSUN OLOKUA KERE NI ADUARA NI IFA OSHE PAURE OMO DE MASHE AWO OSUN IFA OWOSI KAFEREFUN SHANGO LODAFUN ORUNMILA.", "REZO: ADIFAFUN OSHE PAURE AWO SOKUN LAYE ILE LOYA UMBOWA SHONSHON IYALODE OGORISHA OLOPOLO OWO AKAKU OSINI AIE OGU, OPOLOPO ELEGUEDA FUNNI IKE OSHUN, OBOWO FUNI OSHE PAURE AWO OLOWO, OSHUN UMBOWA ORUN INLE OLOFIN ASHE OLODUMARE AWO OMO ODDUN OSHE PAURE IWA ODARA, LODAFUN OSHUN OLORINI."]}]$q$::jsonb),
(230,'c619500721542871c917977856fa2300',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ìdí advierte contra ser demasiado indulgente con quien ya se sabe que hace daño: el enemigo derrotado y suelto vuelve a atacar. El consultante enfrenta un conflicto en el que debe ser más firme."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un problema que se repite o teme que vuelva un daño que ya conoce.", "Duda entre perdonar o poner consecuencias claras (relato de Ṣaanu-otẹ, demasiado indulgente con el fraude).", "Necesita prepararse para un conflicto sin actuar con violencia."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Retener lo que se ha ganado.", "Vencer en el conflicto con firmeza."]}, {"titulo": "Ibi y advertencias", "puntos": ["Compasión excesiva con el fraude y el delito.", "Soltar al que hace daño y que luego cante victoria."]}, {"titulo": "Enseñanza principal", "texto": "No se atrapa al ladrón para dejarlo ir libre: si no se le pone límite, después de descansar cantará victoria sobre nosotros. Olórun ama todas las cosas, pero no el exceso."}, {"titulo": "Relatos reunidos", "puntos": ["Ṣàánú Ọ̀tẹ̀, el compasivo con el fraude. No atrapamos al ladrón para dejarlo marchar; si lo agarramos, atamos al insolente; si no lo atamos, después de descansar cantará victoria sobre nosotros. Así adivinaron para Ṣàánú Ọ̀tẹ̀, a quien le dijeron que ofrendara para no ser demasiado compasivo con el delito y la deshonestidad. Le pidieron cuatro sacos grandes de carga, dinero y medicina de Ifá, porque el saco de carga retiene bien lo que lleva."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Cuatro sacos grandes de carga, dinero y medicina de Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Olórun, que ama todo menos el exceso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Sacos de carga."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 230.1 (yorùbá): A kiim'ólè / kiama yan an. / Bi a ba ségun / ki a m'ólọ̀tẹ̀ de, / Bi a ko m’ọ́lọ̀tẹ̀ de, / Eniti a ṣé, bi o ba simi tán, / A ni òun li ó ṣ'ẹ̀ni: / a daa fún Ṣaanu-otẹ, / a niki ó wa rúbọ / ki aṣeju aanu ma baa sọg di abosi. / Ohun-gbogbo li Ọlọ̀run fẹ, / Ọlorun ko fẹ aṣeju. / Ẹbọ: Qkẹ-id'erù mérin, / egbàá merindilogún owó / ati ewé Ifá. / Qkẹ kiigb'ẹrù ki o ma di i.", "REZO: OSHE DI OKO MODES ADIGAFUN ORUNMILA ONIBARABANIREGUN IFA NIRE. IFA MAFEREFUN YALORDE ATI OBINI.", "AWA AYE EBO OTOLORUN EBO AYE."]}]$q$::jsonb),
(231,'8c22b97e72f685f25c7147aa607210db',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ìrosùn pide quitar el dolor, la tristeza y la miseria hasta que solo quede la alegría. Situaciones confusas que se repiten traen infelicidad al consultante. Promete fecundidad a quien ofrenda."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pasa por confusiones repetidas y siente que le quitan la tranquilidad.", "Su familia o su comunidad está en conflicto y triste (relato de Ọ̀ṣẹ́ y la ciudad triste).", "Pregunta por descendencia (relato del gallo y la gallina)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una vida agradable.", "Hijos en abundancia."]}, {"titulo": "Ibi y advertencias", "puntos": ["Guerra y tristeza en la ciudad.", "Desorden que se repite y trae infelicidad."]}, {"titulo": "Enseñanza principal", "texto": "La guerra no es agradable y la ciudad está triste: la alegría se busca con ofrenda y comida compartida."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀ṣẹ́ y la vida placentera. La guerra no es agradable y la ciudad está afligida: así adivinaron para Ọ̀ṣẹ́, y le pidieron una campana, muchas nueces de kola, un recipiente grande de ñame machacado, un tazón de sopa, dinero y medicina de Ifá para que la vida le fuera agradable. Se negó.", "El gallo y la gallina. Obíyẹnmẹyẹnmẹ adivinó para el gallo y la gallina y les dijo que seguirían teniendo muchos hijos si ofrecían una chiva y dinero. Oyeron y ofrecieron."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la alegría: una campana, muchas nueces de kola, ñame machacado, sopa, dinero y medicina de Ifá.", "Para la fecundidad: una chiva y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá devuelve la dulzura a la casa."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Obì (kola), ñame machacado, campana."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 231.1 (yorùbá): Ògún ko dùn, / llu ko dùn: / a difá f' Ọ̀ṣẹ́. / Wọ̀n niki Ọ̀ṣẹ́ wa rúbọ / kiole maari ohun idunnú / igbá-iyán, awo obẹ, / egbàwá owó ati ewé Ifá. / Ko rú bọ.", "Verso 231.2 (yorùbá): Obiyenmẹyenme: / a dífá fún takotabo adiyẹ / Wọ̀n ni: / Adiyẹ a maa ṣe abiyamo. / Ki wọ̀n rúbọ: / Ewúré ati egbàáwa owó. / Wọ̀n gbọ̀ wọ̀n rú.", "SUYERE : ENIWA ENIWA OSHUN ENIWA.", "REZO: OSHE LEZO SHAKO RIAKO ADOBORA EYO OROKATE ADIFAFUN KOSHE UN BO OMO TIDOSO AGBONI KODE AIKORDIE, EYELE, ABEBOADIE, OMI LA OMI, OWO LA MENI ELEBO.", "REZO: OSHE LEZO OLALU FIRI ADIFAFUN BA ALE ILE KORUGBO IRA OBO EYELE LEBO. MAFEREFUN ESHU ATI YALORDE.", "REZO: OSHE LEZO ITA META OBE AYAKATA ADIFAFUN ORUNMILA NIGBATI OLORUN MAYIYI OLOSHAWO OBA IGI NIYA.", "REZO: OSHE LEZO ADIFANFUN ORUNMILA, OBA LORILE OMOFO IYOBA, FUN IGBARO INO PUOPO NI ORIYE KAFEREFUN YALORDE ESHU OGGUN.", "SUYERE: “OGUNDE ARERE IRE BONBO LEKUA LOKUA OGUN WANILE OGUN WALONA. IRE BONBO LOKUA AEE”.", "SUYERE: ONI LEGUE NITA OSHUO, ONI LEGUE, LA OSHUN, MO FI SHAKOKO, ONI LEGUE DALE KOYU EBU YI ODO BAGUAO, ONI LEGUE NITA OSHUO."]}]$q$::jsonb),
(232,'c5b6ff38aeeb08dd87147e3c0ddef4ae',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ọ̀wọ́nrín pide ofrendar para recuperar las fuerzas y protegerse de hechizos y encantamientos. La inquietud del consultante por sus negocios o proyectos se equilibra con trabajo espiritual. Advierte del riesgo de ayudar a quien puede caer encima."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está agotado por su trabajo.", "Un trabajo de reparación tiene riesgos (relato de Pokolaka y el muro que podía caerle encima).", "Debe cumplir una obligación antes de que un cambio lo sorprenda."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que ningún hechizo lo afecte.", "Recibir sus deseos y bendiciones.", "Recuperar la fuerza."]}, {"titulo": "Ibi y advertencias", "puntos": ["Cansancio y agobio.", "Que lo que uno sostiene se le derrumbe encima."]}, {"titulo": "Enseñanza principal", "texto": "El que sostiene un muro enfermo debe ofrendar antes, o el muro le cae encima."}, {"titulo": "Relatos reunidos", "puntos": ["Pokolaka y el muro. Estoy agobiado, el adivino de la tierra, y estoy cansado, el adivino del cielo, adivinaron para Pokolaka cuando iba a curar a Ògiri, el muro, de una dolencia. Le pidieron tres gallos y dinero para que el muro no se le cayera encima. Oyó y se negó. Pokolaka es el nombre del puntal con horqueta que sostiene los muros."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para sostener sin peligro: tres gallos y dinero.", "Medicina contra hechizos: marcar el Odù en iyẹ̀ ìròsùn y echarlo en una tinaja grande con tapa, con abundantes raíces de itọ y abundante ẹ̀ẹ̀rù, llenarla de agua y sellar la tapa con ceniza mojada siete días; atar nueve ẹ̀ẹ̀rù con hilo blanco y negro al cuello de la tinaja; al séptimo día usarla para bañarse."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá protege contra los encantamientos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Itọ (Napoleonaea vogelii y otras), ẹ̀ẹ̀rù (Xylopia aethiopica), iyẹ̀ ìròsùn, hilo blanco y negro, ceniza."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 232.1 (yorùbá): O su mi awo ayé, / O rẹ mi awo òde prun: / a difá fún Pokolaka / nlọ wo Ogiri (ipalẹro) l'àrùn. / Wọ̀n niki o wa rúbọ / ki Ogiri ma le kú siil'orun. / Ebọ: Akuko mẹta ati egbetalélọ̀gbon owó. / Ó gbọ̀ kó rú. / Pokolaka oruko / ti aipe igi abukala.", "REZO: OSHE BORONIWO BORO OJUANI NIWO KOKOROSHE AWO OJUANI KOKORO BIAYE EYELE LEBO. OSHE MOWEYO OJUANI AKAKALA- YE OBA YOBI INU ENI OMO LALA AWO OKUTA AWO LORI OKUTA.", "REZO: OSHE MORARE OJUANI MOWAYE NI OSHE IFA MAFEREFUN ELEGBARA, IFA MAFEREFUN ORUNMÑA, IFA MAFEREFUN OSHUN, ORUNMILA ATI OGUN.", "REZO: MAFEREFUN SHANGO MONTAÑA ABERE KULAYE. OSHE NIWO IFA MAFEREFUN OGUN INU EÑI OYU EKUN OYU OSHE NIWO.", "REZO: OSHE BORO JUANI OBE OTONU EWE, SHEPE OLORI AYE AWO OLOBI, AYA MAFE OSHE MAKE AWO ORIMOSHE TORUN ENU EWE OLOWO OBE YALE, EWE KOSINI, OSHE EWE EWE KEWE OZAIN LARANIYE, OSHE BORO JUANI ENIWE AYO EWE OLUWO SEKUN MADE EYI ORI OYO OPARALDO ELEGWA UMBO OMOFA LOBA ADIFAFUN ORUNMILA.", "REZO: OSHE BORO NIWO BORO JUANI NIWO KOKOROSE AWO OJUANI KOKOROSE BIAYE EYELE OSE MOWEIJO OJUANI AKAKALABE IKU EÑI OMO LALA AWO OKUTA AWO LERI OKUTA OSE MORARE OJUANI MOWAYE NI OSE IFA KAFEREFUN ELEGWARA, IFA KAFEREFUN ORUNLA, IFA KAFEREFUN OSHUN, KAFEREFUN EGGUN, KAFEREFUN SHANGO MONTANLA ABERE ESHU LAYE OSE ONIWO IFA KAFEREFUN OGGUN INU EÑI OYU EKUN OYE OSHE NIWO.", "REZO: IFA NIRE YEMAYA OFIKALE TRUPON, OGGUN NIBE, OSHUN FE ENIA OÑI, AFAIYA OGGUN ONA OBATALA BE IBU LOSA UN LONI LOWO OGGUN."]}]$q$::jsonb),
(233,'2b1a876fc12e69aecd5778f0171fce1d',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ọ̀bàrà enseña lo que hay que hacer para que los hijos tengan éxito y no pasen necesidad al crecer. Advierte al adulto de dificultades en un viaje próximo. Hay mucho desorden en sus actividades: debe dar un paso atrás y reconsiderar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La familia quiere darle mejores condiciones a un niño (relato de los padres del recién nacido).", "Piensa irse a vivir o trabajar fuera de su lugar de origen (relato del señor de tierras y su viaje).", "El desorden diario le pide detenerse y revisar el plan."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un hijo próspero y con comodidades.", "Evitar un viaje desafortunado."]}, {"titulo": "Ibi y advertencias", "puntos": ["Un viaje a tierra extraña que no saldrá bien.", "Desorden y confusión diarios."]}, {"titulo": "Enseñanza principal", "texto": "Lo que los padres trabajan y ofrecen hoy es lo que el hijo tendrá mañana. No todo viaje conviene: a veces la mejor ofrenda es quedarse."}, {"titulo": "Relatos reunidos", "puntos": ["El recién nacido. Ọ̀ṣẹ́ Ọ̀bàrà adivinó para un recién nacido y les dijo a los padres que debían trabajar y ofrendar para que el niño, al crecer, no careciera de comodidades y tuviera éxito en la vida. Les pidió pescado aro, dinero y medicina de Ifá.", "El señor de las tierras y el viaje. Al señor de las tierras, que iba a alojarse en casa de un propietario de otra ciudad, le dijeron que el viaje no le saldría bien y que no debía ir. Le pidieron dos gallinas, dinero y medicina de Ifá."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para el hijo: pescado aro, dinero y medicina de Ifá.", "Para el viaje: dos gallinas, dinero y medicina de Ifá; mejor no ir."]}, {"titulo": "Relaciones espirituales", "texto": "Los padres y los antepasados del niño."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pescado aro."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 233.1 (yorùbá): Ọ̀ṣéBàrà! / a dífá fún Ọmotitun àlejò ayé. / Wọn ni: / iṣẹ ibugbe a ṣe / omotitun yi bioba dagba / nitorinaa ki wọ̀n rúbọ / kiobaa le rọọ lorun li ayé. / Ebọ: Eja-aro, egbà á méjilá owó ati ewé Ifá.", "Verso 233.2 (yorùbá): OṣéBàrà: / a dífá fún Baale ilé / ti o nloṣ'ero wọ sile onilé nilu onilú. / Wọ̀n ni: / Ona-ajo Baale / ko le sunwọ̀n kiomamalo o. / Ó ni òun a rúbọ. / Wọ̀n niki o rú: / Adiyẹ Méjì, ẹgbàárin owó ati ewé Ifá.", "REZO: OSHE BARA AWO SHESHERE ADIFAFUN LOBA FIFEREKU TOLUMA KU OGUEDE ALAFIA.", "EL REZO ARARA ES: ” O IFA NA LO BO OSHE BARA AWONO MAKUO BOTO DE KU WE B OTONO YI DOJUZO POLI AÑAÑI LO TUKU MUVI SODEQE OSHE BARA BOKONO MAJUDO VIZIME”.", "REZO: OSHE BARA OLENUDODO ALUGBABA OMO IBELLITHESO, KAINDE OLENU NI OSHUN OLEMIRA OSENUMI LODO OYA IDEU ALISHO- LO FINKUE, SIMANU OGUEDE DODO ENU OFIFO IDOU ÑOMU FISI ORISHA ENEDURO EFOLENU ISHENU WA ORO LENU GBOGBO OMODE ARAYE, LODAFUN SHANGO LODAFUN OLOFIN."]}]$q$::jsonb),
(234,'8314ed5174126198721fe34b34d6d285',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ọ̀kànràn habla de la necesidad de buena compañía en la vida. Los negocios y la vida se estabilizan cuando el consultante encuentra equilibrio emocional, apoyo y paz. Promete éxito sobre los enemigos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente solo mientras enfrenta problemas que se repiten (relato de la persona que busca quién camine a su lado).", "Sus negocios no son estables y le falta apoyo, paz o una relación de confianza.", "Busca una disciplina espiritual constante para ordenar sus decisiones.", "Puede salir adelante frente a quienes se le oponen (relato de Ṣaṣamura)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Alguien que camine a su lado.", "Éxito sobre los enemigos.", "Equilibrio emocional y estabilidad."]}, {"titulo": "Ibi y advertencias", "puntos": ["Soledad y desamparo.", "Inestabilidad por falta de apoyo."]}, {"titulo": "Enseñanza principal", "texto": "A ti no te gusta, a mí no me gusta: el sufrimiento camina solo. La compañía se busca y se ofrenda."}, {"titulo": "Relatos reunidos", "puntos": ["El desafortunado que caminaba solo. A ti no te gusta, a mí no me gusta, el sufrimiento camina solo: así adivinaron para el desafortunado. Le pidieron dos gallinas, dos gorros o pañuelos para la cabeza, dinero y medicina de Ifá para tener a alguien que caminara a su lado. Escuchó y no ofreció.", "Ọ̀ṣẹ́ Ọ̀kànràn y sus enemigos. Ṣaṣamura adivinó para Ọ̀ṣẹ́ Ọ̀kànràn y le dijo que triunfaría sobre sus enemigos si ofrecía una tortuga, ẹfun, osùn, dinero y medicina de Ifá. Oyó y ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la compañía: dos gallinas, dos gorros o pañuelos de cabeza, dinero y medicina de Ifá.", "Contra los enemigos: una tortuga, ẹfun, osùn, dinero y medicina de Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "La pareja y los amigos como sostén."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹfun, osùn (madera roja), tortuga."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 234.1 (yorùbá): Iwọ ko feẹ, / Emi ko fẹẹ. / Iṣé nikan rin: / a daa fún Oloriburukú. / Wọ̀n niki Oloriburukú wa rúbo / kiobaaler'ẹni ba rin. / Ebọ: Adiyẹ Méjì, fila (tabi gele Méjì), / egbẹwá owó ati ewé Ifá. / Ó gbọ̀ ko rúbọ.", "Verso 234.2 (yorùbá): Ṣaṣamura: / a difá fún Ọ̀ṣéKọ̀nràn. / Wọ̀n ni: \"OṣéKọ̀nràn a ṣẹ'ta\" / Ebọ: İjapá, ẹfun, osùn, / egbaá méjilá owó ati ewé Ifa. / Ó gbọ̀ ó rú. / 400 Oloriburukú: desafortunado, desgraciado, necesitado, desdichado.", "REZO: OSHE KANA OSHE IPILIKE AFILLE AKOLONA ADIFAFUN SAKUN BATINSHE MAIYESHA EYA ORO LEBO.", "REZO: OSHE KANA LODAFUN ESHU, YALORDE ATI ORUNMILA, CURE EBO OWO MEDILOGGUN ELEBO. MONI TALA IFA LOLA ORISHA LOSHIN OGUDA, AGUIRE, GUIREUN GUABAI YOKALA DEFAFA ODAFUN TINSHELE OLUDDUMARE EBO OBA NEWA OKAN SEGU, OBI OKOKAN LORA OWO LA MARUN ELEBO.", "REZO: OSHE KARAN LODAFUN ESHU YELEDE ORUNMILA LOBE EWE MEDILOGUN OMONI TELA OFA LOLA ORISHA OMO META OBATALA OSHALUFON, OSHAGRIÑAN, OSHANLA AWIRE AYALGU- NA OUN GUIBAKAN ADAFUN TINSHELE OLODDUMARE WEWE EURE MAMURAYE.", "REZO: OBATALA LORUBO IDA ABADO IKODE EKU, EYA, EPO, OWO LA MESAN TONTI MESAN.", "REZO: OSHEKARAN ORDAFUN ESHU YALORDE, ORUNMILA, LEBO OWO MERILOGGUN MONI TELA IFA LOLO ORSIHA LOSHIN OGGUNDA AGUIRE UN GUIBAIKON, LODAFUN ORDAFUN TINSHELA OLODU- MARE ABBO OBA MIWA OKAN MAGUN BOGBO ODDUN OBI KOKAN LORA AWO LA MAMU TOTUARO OSHÑ OPARIKO OFI BO AKOFARA MOFUN FUN SOKUMBA TINSHE MAIYI SHUORO EJA EÑEBO.", "SUYERE: MAMURAYE IKU MAKU SEDA EURE, MAMURA AYE ALAIBORU AYE, ALAIBORU EURE, ALAIBORU EURE IKU BARALAYE KETU, MAMURA AYE IKU MAKU SENDA EURE.", "IFA NI KAFEREFUN OBATALA, LODAFUN OGGUN."]}]$q$::jsonb),
(235,'753654f0cb3a7c3f0c366b051b238895',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ògúndá anuncia que la buena fortuna está por llegar: terminan la angustia, la pobreza y la desgracia, y empieza la abundancia para siempre si se ofrenda. Los cambios rápidos en sus actividades le traen beneficios."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera que terminen sus problemas de dinero (relato de Toto).", "Necesita cambiar pronto una actividad que ya no funciona.", "La angustia por el dinero le impide pedir orientación.", "La familia teme por la vida de un hijo después de pérdidas anteriores; conviene acompañamiento médico (relato de Ôlömú Jùwàlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Fin de la pobreza y del sufrimiento.", "Abundancia duradera.", "Que todas las buenas fortunas lleguen a sus manos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Seguir en la angustia por no ofrendar."]}, {"titulo": "Enseñanza principal", "texto": "Lo bueno vive en las aguas de Olókun, la mayor, y en las de Olóṣà, que le sigue. Lo que se usa para atraer la suerte debe estar limpio y en buen estado."}, {"titulo": "Relatos reunidos", "puntos": ["Tótó y la abundancia. Las angustias terminan, los sufrimientos terminan: así adivinaron para Tótó, y le pidieron una paloma, una carnera, una gallina y dinero para estar siempre en la abundancia. Escuchó y ofreció.", "El buen vestido de las aves. Ọ̀ṣẹ́ Ògúndá: un buen vestido cubre el cuerpo del àgbẹ̀, un buen vestido cubre el del àlùkò, un buen vestido cubre el del odíderẹ. Lo bueno vive en las aguas de Olókun, jefa de todas ellas, y en las de Olóṣà, que le sigue. Tótó dice: que todas las buenas fortunas vengan a mí."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la abundancia: una paloma, una carnera, una gallina y dinero.", "Medicina de buena suerte: plumas de la cola de àgbẹ̀, de àlùkò y de ìkóóde molidas con hojas de tótó, puestas sobre un jabón y marcadas con el Odù, para bañarse."]}, {"titulo": "Relaciones espirituales", "texto": "Olókun y Olóṣà, dueñas de las aguas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tótó (Marantochloa leucantha), plumas de àgbẹ̀, àlùkò e ìkóóde, jabón."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 235.1 (yorùbá): Ìsé tán, / iyà tán: / a dita fún Toto, / wọ̀n niki Toto wa rúbọ / Ọrọ titi ayé. / Ebọ: eyelé, àgutàn, adiyẹ / ati ẹgbàá mẹrindilógún owó. / Ó gbọ̀ ó rú.", "Verso 235.2 (yorùbá): İṣẹ-Egúntán, / aṣo ire li aiba lara Agbe, / Iṣé-Egúntan, / aṣo ire li aiba lara Alùkò, / İṣé-Egúntán, / aṣo ire li aiba lara Odiderẹ. / Gbogbo ire niit'owọ̀ Olókun, / Olókun olórí omi, / Gbogbo ire niit'owọ Ọlọ̀sà, / Ọ̀sá ibikeji odò. / Iṣé-Egúntán: / Toto niki gbogbo ire maa to mi lqwọ̀.", "REZO: OSHE OMOLU OSHEWELE BIAWO WELE OSHE BALAYA BIAWO AKUKO BODAWESE AYA BASHEWERE SENU OROIÑA OGUESE OMI AKOKO WINI OKOKO ISUGUESE KILAMA OSHE OMOLU. OSHE OMOLU AGADA MAMELERUN.", "REZO: AUNCALLI RIQUI DIEGUE ADIFAFUN APO AUN BITINLA BOBO AWO NIDEN ADIEMER ACO EWE ATORRI ERACHE AGUE EGUEGUE EWE EFIE.", "REZO: OSHE OMOLU ILLA OMA BA ARGADA COMONITOCHUN ORDAFA MERE TINTLO SINLO OLOGGUN CHABORO.", "REZO: IÑO COMO AGUE AGADA COMO NITORUN ODAFOGU OBABODUN. (IÑO ES EL CORAL.)", "REZO: OSHE OMOLU UN LODAFUN OBA OMIBINI CORUBO INTORI EGGUN AIVO OGGUN CAMABO LLADORBE OBA OMIBINI AWO OTUN AWO ORE ENI EMU UN BABALAWO LA METETA EFUN LOGUO CAMBODE OCA OGUO MULAPELLE.", "REZO: MAFEREFUN ORISHAOKO, MAFEREFUN OZAIN, MAFEREFUN OYA, MAFEREFUN YEMAYA."]}]$q$::jsonb),
(236,'69e264d0f33010dbe34249c6e6e5bfa0',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ọ̀sá dice que la conciliación y el acuerdo son mejores que el pleito y la pelea. El consultante está en una disputa, a menudo con el gobierno, y el arreglo es lo indicado. Promete no morir por causa judicial y ser respetado."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está en una disputa, a veces con una autoridad o una institución (relato de Elégbárá y el asunto judicial).", "Hay una forma de arreglo que conviene revisar con claridad.", "Las groserías o las reacciones impulsivas pueden empeorar la negociación (relato de la tortuga Olobakun Ìjapá).", "Necesita valor para defenderse y criterio para saber cuándo retirarse."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Salir bien de un pleito.", "Ser respetado en todas partes.", "Palabras que no ofenden a nadie."]}, {"titulo": "Ibi y advertencias", "puntos": ["Pleitos que pueden costar la vida.", "Enfrentar cuando conviene esquivar."]}, {"titulo": "Enseñanza principal", "texto": "El valiente sabe cuándo pelear y cuándo esquivar. Cuando vemos a la tortuga, no hace falta el garrote."}, {"titulo": "Relatos reunidos", "puntos": ["Elégbára y el pleito. A Elégbára le pidieron tela, una nuez de kola de tres gajos, aceite de palma, dinero y medicina de Ifá para no morir por un problema judicial. Ofreció, le prepararon la medicina, y el adivino dijo: la kola de Ọ̀ṣẹ́ Ọ̀sá nunca muere por un pleito; Elégbára no morirá por un pleito.", "La tortuga y la pelea. Combatir y esquivar es cosa del valiente: así adivinaron para la tortuga, y le pidieron kola amarga, sal, semillas de ayò, un gallo y dinero para que una pelea no la matara y para ser respetada en todas partes. Oyó y ofreció, y le dijeron: las palabras de tu boca nunca molestarán a nadie; la gente siempre buscará dinero y sal."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra el pleito: tela, una kola de tres gajos, aceite de palma, dinero y medicina de Ifá.", "Para ser respetado: orógbó (kola amarga), sal, semillas de ayò, un gallo y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Elégbára (Èṣù), que no muere por pleitos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Obì de tres gajos, orógbó (kola amarga), sal, semillas de ayò, aceite de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 236.1 (yorùbá): Ọ̀ṣẹ́-Sá: / a difá fún Flégbárá / Wọ̀n niki Ẹlégbárá wa rúbọ. / Elẹgbárá komaa ku ikú ẹjọ. / Ẹbọ: Aṣọ, / Obi alawẹmẹta, epo, / egbẹtalélọ̀gbọ̀n owó / ati ewé Ifá. / Ó gbọ̀ ó rú. / Wọ̀n ni: / Oṣésá Obi kiikú ikú ejó, / Ṣlegbárá koniikü ikú ejó.", "Verso 236.2 (yorùbá): Majamasa li aimo Akin; / a dífá fún Ọlobakun ljapá, / wọ̀n niki o wa rúbo / ki ijà ma baa paa, / kiole maa niyi nibigbogbo. / Ẹbọ: Orógbó, iyo, / ọmo-ayo, akuko-adıyẹ / ati egbèrindilógún owó. / Ô gbọ̀ ó rú. / Wọ̀n se ewé Ifá fün un, / wọ̀n nỉ: / Ohun tirẹ koniibi ayé ninu. / Ariwowo niti owó, / ariyoyo niti iyo. / A kiiri Awun i yo'gbo.", "REZO: OSHE SA AWO OBINI KOPU KAPU ADIFAFUN AKO, AKUKO LEBO, AKOFA ATITAN ERITA MERIN ELEBO.", "REZO: OSHE SA ADIFAFUN EDUN LONGO KOMA OUNYEN KO AGBADO ALABGONA AYAPA KOMÑO AWO ERANKO AUN SODDE NI OSUN IGI, AYAPA KAUFE ANO ABINU UNSORO EDUN MAYA ONIWA MAYOINI ORUNMILA ODARA BONIREGUN EKUN LOBA EBO WIRI WIRI ATE OPA EDUN OMO ODARA LODAFUN ORUNMILA.", "REZO: OGUE OBINI KOPAPAEKU ADIFAFUN OKO AKUKO LEBO AKO FE BABA EKO MENI AKOKAN KARITA META, ETU, ERA, EKO, AGBAN MEYI DUN DUN LERI ESUHIMA.", "REZO: OSHERE ADIFAFUN TIKOY OMAPUO MIYA OBA TORALO EGGUN AWO OKUNI KOPU ADIFAFUN AKOFA AKUKO LEBO AKOBA BABAMONI AKOKAN KORITA META ETU ORO EPODA PUA SI MEYI DUDU LERI ESPOSHIMA .", "REZO: ADIFAFUN ADUNLONGO KUMA UYEN KO AGBADO OKO ALAMOMA AFETILE AYAPA KONKO AWO WBAKO UNSODENT OSUN IGUI AYAPA KONBO AWO ABINU UNSORO EDUN MAYA ONI WAY MAY ONI ORUNMILA ODARA BONIREGUN EKUN LOBA LOWO EBBO WIRI ATE OPA EDUN OMO ODARA LODAFUN ORUNMILA.", "REZO PARA PONER ADDIMU: OYU ILE LASHEDA LADIMU OTA LASHERU BOWA LADIMU NI EBBO MAMASHE ADDIMU KELEYERI", "REZO PARA PONER EL EBBO SHIRE Y EL EBBO KEUN ODDUN KEUN: EBBO KEUN ODDUN KEUN EBBO SHIRE, BOGBO OSHA ALAWE", "REZO: ADIFAFUN SHAKUANA UMBO ORUN ODUDUA ARONU AGUASI ABI AYAMO IBERI ORUKONI DASOYI ATI AYONWO MAMU AZON ONIKONI AWAKO LAWA BABA NIYO AWO, AWA KEFE ENIKI OMOKUA ENIYO AZON, OZUN IRAWO EYU EMIWELE NISHE WELE NERUKAKELEYEWE UTE LAWA IKUN ORUN AWO TEBU OKO LONA, OKOWARE DEBOLI, EYIGAN LOBU AWABANI SHANGO OKANANI ERO AGUENI OSOKO OBI SHEKUANA ALAGUEMA ORISHA, LODAFUN EKUBI JEGAB ADAFUN AZOJUANO."]}]$q$::jsonb),
(237,'9124fc72ba061dbb3ef4d408af12b4e3',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ìká habla de dominio sobre las dificultades y victoria sobre los enemigos. Puede haber una amenaza legal por una sociedad o un trato antiguo. Pide no asociarse con malhechores para no ser contado entre ellos el día en que caigan."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Un trato o una sociedad anterior podría traerle un reclamo legal.", "Teme que lo que hicieron sus socios lo comprometa aunque él no participó (relato de Deyunlenu Abowoṣerin).", "Quiere responder a una acusación falsa con buen carácter, hechos y acuerdos claros.", "Puede prevalecer frente a quienes se le oponen (relato de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Conquistar a sus enemigos en todas partes.", "Salir limpio de asociaciones peligrosas."]}, {"titulo": "Ibi y advertencias", "puntos": ["Ser contado entre los malhechores.", "Problemas legales por tratos pasados."]}, {"titulo": "Enseñanza principal", "texto": "Quien anda con malhechores cae con ellos el día del castigo."}, {"titulo": "Relatos reunidos", "puntos": ["Dẹ́yùnlẹ́nu y los malhechores. A Dẹ́yùnlẹ́nu Abọ́wọ́ṣerin le pidieron ocho huevos, el palito de mascar que estaba usando y dinero para que los malhechores no lo contaran entre ellos el día en que el mal cayera en problemas. Oyó, pero no ofreció.", "Ọ̀ṣẹ́ vence en el mundo. Ọ̀ṣẹ́ fue venciendo en el mundo: así adivinaron para Ọ̀rúnmìlà, y le dijeron que conquistaría a todos sus enemigos en todas partes. Le pidieron un carnero, una piedra de rayo y dinero. Ofreció, y Ọ̀ṣẹ́ los venció a todos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra las malas compañías: ocho huevos, el palito de mascar que se usa y dinero.", "Para la victoria: un carnero, una piedra de rayo y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà conquista a sus enemigos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Huevos, palito de mascar (pàkò), piedra de rayo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 237.1 (yorùbá): Ọ̀ṣẹ́-Kaa: / a difá fún Deyunlenu Abowoṣerin / (Abelẹṣerin) / Wọn niki o wa rúbo / ki àwọn owoṣẹ ma baa kaa / nijọ ràn ba burú tan. / Ebọ: Ṣyin adiyẹ mẹjo, / orin (ti o nrun) / ati egbàá-méjo owó. / Ó gbọ̀ ko rúbọ.", "Verso 237.2 (yorùbá): Ọ̀ṣẹ́-nṣégun-k'ayé: / a difá fún Ọ̀rúnmìlà, / wọ̀n ni: / Ọ̀rúnmìlà a maa ṣégun ọ̀tá / kaakiri ninu ayé. / Wọ̀n niki o wa rúbọ: / Agbo, ẹdùn-ààrá / pẹlu ẹgbàá mọ̀kànlá owó. / Ó gbọ̀ ó rú. / Ọ̀ṣẹ́ sẹ wọn ka.", "REZO: OSHE KARAKA ADIFAFUN ERU. ORUNMILA UNBATILOPE ES IBU LOSA OMO ERU, OSHUN KOYODE OMA UNFO OLUWO-OZAIN INLE AKARABANIYE ORO KODADE TINLOMU KOLA KEYU IBI ARARA AWO IMPON OROGUYE OSHE KA AYE INLE ADIFAFUN AYE UNBATINSHE OUN GBOGBO EYA-ORO ARA APONTIPONTIKA EYA TUTU OBA YEGUETA GIRI GIRI LODAFUN INLE ABATA.", "SUYERE: “EYA EYA INLE EYA ERUMALE EYA EYA INLE ERUMALE. EYA AGBA ORISHA GBOGBO NI YERO INLE ERUMALE”."]}]$q$::jsonb),
(238,'9390bb338321117295087891c013d911',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Òtúrúpọ̀n muestra una relación de pareja complicada, aunque pueda dar hijos. El consultante está en una relación que no le conviene. Promete que los hijos vencerán a los conspiradores."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Sigue en una relación que le hace daño.", "El deseo de tener hijos pesa en una decisión de pareja (relato de la mujer advertida antes de casarse).", "La familia se pregunta cómo educar y proteger a los niños (relato de Olú-ńlá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos que vencen a los enemigos.", "Armonía en la pareja con ofrenda."]}, {"titulo": "Ibi y advertencias", "puntos": ["Una pareja que empobrece y hace sufrir.", "Conformarse con tener hijos y descuidar lo demás."]}, {"titulo": "Enseñanza principal", "texto": "Dos caracoles nunca riñen. Tener hijos no basta si la relación hace sufrir."}, {"titulo": "Relatos reunidos", "puntos": ["Olú ńlá y sus hijos. A Olú ńlá le dijeron que sus hijos vencerían a los conspiradores y superarían a sus enemigos, y le pidieron un garrote, un carnero, un gallo y dinero. Oyó y ofreció.", "La mujer que se conformó con los hijos. A una mujer le dijeron que el hombre con el que se iba a casar la haría pobre y la haría sufrir, aunque le daría hijos. Le pidieron dos caracoles, una tela jaspeada, un recipiente de aceite de palma y dinero, porque dos caracoles nunca riñen. Ella no ofreció y dijo: ya dijiste que tendré hijos, con eso me basta."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para los hijos: un garrote, un carnero, un gallo y dinero.", "Para la pareja: dos caracoles, una tela jaspeada, aceite de palma y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "La pareja y los hijos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Caracoles, tela jaspeada, aceite de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 238.1 (yorùbá): Ọ̀ṣẹ́-Òtúrúpọ̀n: / a dífá fún Olú-ńlá. / Wọ̀n ni: / \"àwọn ọmọ rẹ̀ a ṣégun odi / wọ̀n a rẹ̀hin ọ̀tá\". / Wọ̀n niki o wa rubọ: / Olúgboro, éran agbo, akuko-adiyẹ / ati egbàá mọ̀kànlá owó. / Ó gbọ̀ ó rú.", "Verso 238.2 (yorùbá): Ọ̀ṣẹ́-Òtúrúpọ̀n: / a difá fObirin kan, / Wọ̀n ni: / \"okọ rẹ̀ tiomaa fẹ yi, / a fi iṣe ṣeẹ, / a maa fi iyà jẹẹ\". / \"Bẹẹni iwọ (wa) a bimo fün un\". / Ó ni: Kinni ebọ? / Wọ̀n niki o rú: / Igbin Méjì, aṣo-ẹtu, ata-epo / ati egbàá mẹsàn owó. / Wọ̀n nì: / İgbín Méjì kiiba ara wọn jà. / Ó gbọ̀ e (ko) rú. / Ó ni: / ẹ ti sọ pe maa bimo ó to.", "REZO: OSHE TRUPON IKABAGUN MAYA LALAYA OUN OYAGUNLE ILOWO TULE ADIFAFUN PITI ARENTINLO LAYA TINSHE AREMA BOGA AWUNKO LEBO. OLOGUN KANTE EYELE, AKUKO LEBO. MAFERE- FUN SHANGO, ESHU ATI ORUNMILA.", "REZO: OSHE TRUPON IRE NI IFA IGI LODAFUN ESHU.", "REZO: OSHE TRUPON TALAKE NIYOBITI DARA YEYE NI OGU NI GBOGBO IBU OMO ORISHA LA EWE.", "REZO: BAGUN MAYA LAYAYA AUN YAGULO YAWO TULA, ADIFAFUN TITI AFINUSHE OBA AGONI ABEDE ABANIYEUN AFOTUBA.", "REZO: OSHE TRUPON TALAKE NIYEBITI DARA YEYE, MI OGA NI BOGBO IBU LAYE NIBU BOGBO OMO ORISHA LO EWE.", "REZO: EGGUN MAYA LAYAYA AUN YAGULO YAWOTULA, ADIFAFUN TITI, ARANTILO, LOYO TINSHE AREMA BABA ABO LEBO, ELOGUN KANTO AYAKUA LEBO, AKUKO LEBO."]}]$q$::jsonb),
(239,'2da59408224bdb863cf0f4cafceb78a5',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Òtúrá es el Odù en que encarna Èṣù Ọ̀dàrà: nada sucede sin la ayuda de Èṣù. Èṣù fundó la ciudad y libra del hambre a los sacerdotes, médicos y herbolarios. Da honor, autoridad y cosas buenas a quien lo atiende, y alivia los males del mundo cuando se hace lo que él dice."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere que una oportunidad llegue a buen término.", "Está replanteando cómo usa el dinero y el reconocimiento.", "Una decepción podría llevarlo a actuar contra sus propios intereses."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["No pasar hambre en el oficio.", "Honor, autoridad y respeto todo el año.", "Que el mundo mejore cuando se cumple lo que dice Èṣù."]}, {"titulo": "Ibi y advertencias", "puntos": ["Hambre en el oficio.", "Enfermedades que quitan el gusto de comer."]}, {"titulo": "Enseñanza principal", "texto": "El dinero es bueno para tener honor y autoridad, para llevar cuentas de coral al cuello. Ọ̀ṣẹ́ Òtúrá supo dar: dio a reyes coronas, trajes y bastones."}, {"titulo": "Relatos reunidos", "puntos": ["Èṣù y la ciudad. Akakanika es el nombre de Ifá, Alakakanika el de los Odù, Alapaṣapa Ijakalu el de Èṣù Ọ̀dàrà, y el pájaro que entró volando con fuerza en la casa es Ajé, hija de Olókun Ṣẹ̀ndé, rey de las aguas abundantes. Èṣù Ọ̀dàrà, tú fundaste esta ciudad, tú libraste del hambre a los sacerdotes de Ifá, a los médicos y a los herbolarios de la ciudad. Yo soy el sacerdote, el médico y el herbolario de esta ciudad: Èṣù Ọ̀dàrà, no me dejes morir de hambre.", "Ọ̀ṣẹ́ Òtúrá supo dar. El dinero es bueno para tener honor y autoridad; con él llevamos cuentas de coral al cuello. Ọ̀ṣẹ́ Òtúrá, tú supiste dar: diste a Alárá y se puso corona; diste a Ajerò y vistió un traje de abalorios; diste a Ọ̀rangún y fue a la finca con bastón de hierro; diste al rey de Àdó, al anciano de Iléṣà, al rey de Ìjẹ̀bú, a Ẹlẹ́yọ̀, a Ọlọ́mù, al rey de Tápà, a Ọlọ́wọ̀, a Olówu y a Ọlọ̀fà. Èṣù Ọ̀dàrà, Bara Pètu, dame cosas buenas a mí.", "La boca que se pone negra. Dolor de garganta quita lo bueno del plato: así adivinaron para toda la gente de la tierra cuando estaba afligida por la enfermedad. Èṣù dijo que la ofrenda serviría si hacían lo que él decía. La gente ofreció una canasta de caracoles, un carnero y dinero, y desde entonces el mundo empezó a ir bien. Ante llagas en la boca o dolor de garganta que impide comer, conviene ir al médico."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para no pasar hambre: una hoja de abámọdá marcada con el Odù usando ẹfun y osùn mezclados con barredura de herrería; rezar el verso cada día con un gajo de kola y siete granos de pimienta de Guinea, y colgar la hoja en la casa con hilo blanco y negro.", "Para honor y autoridad: marcar el Odù en iyẹ̀ ìròsùn, rezar, mezclar con aceite de palma y lamer.", "Contra la enfermedad: una canasta de caracoles, un carnero y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù Ọ̀dàrà, que encarna en este Odù. Ajé, hija de Olókun. Los reyes yorùbá que recibieron de Ọ̀ṣẹ́ Òtúrá."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Abámọdá (Bryophyllum), ẹfun, osùn, barredura de herrería, obì, pimienta de Guinea, caracoles, hilo blanco y negro."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 239.1 (yorùbá): Akakanika, / Akakanika, / Alakakanika, / Alapaṣapa ijaka'lu, / Eyẹ kan fo feerẹfẹ o wole. / Akakanika li aape Ifá, / Alakakanika li aape Odù, / Alapaṣapa-ijaka'lu li aape Èṣú-Ọ̀dàrà, / Eyẹ kan fo fẹerẹfẹ o wole li aape Ajé / ọmọ Olókun-Sande Ọba Olubu-omi, / gọ̀ Qwọni. / Eṣú-Ọ̀dàrà, iwọ liotẹ ilú yi do. / Iwọ nikiijẹki ebi kiopa Aláwo ilú, / Iwọ nikiijẹki ebi kiopa Oniṣègün Ilú; / Iwą nikiijẹki ebi kiopa Adáhunṣe ilú. / Emi Aláwo ilü yi ree, / Emi Oniṣègùn ilú yi ree, / Emi Adáhunse ilú yi ree, / Eṣú-Ọ̀dàrà majẹk'ebi pa mi ati bẹẹbẹẹ.", "Verso 239.2 (yorùbá): Öṣétúrá Amukere (lkere), / Itẹkun Oriṣà Daji, Apojojomatẹ, / Owó liaari ṣe iyi, / owó li aari ṣe ola, / owó li aari ṣe odigba lorùn / Ọlọ̀mọ kẹririkẹriri. / Oṣétúrá! mimọ liomọo pin; / o pin fún Alárá, o fi d'adé, / o pin fún Ajerò, o w'ẹwu ilẹkẹ, / o pin fún Ọba Ọràngún / o tẹ pa oṣo ro ja'ko. / o pin fún Olúpopo Amuyun-bọ'lẹ, / O pin fún Erinmagaji ehin eku jamo, / O pin fún Ọba Ado, / Agbà llẹṣi ad'akẹtẹ pempe pari akun. / O pin fún Olú-Oyinbo Am'okun sure. / O pin fün Ọba ljẹbu Ogborogan-nida, / Akoyebẹyẹbẹya'gun. / O pin fún Elẹyo-Ajori, Ajegi-emi-san'ra, / O pin fún Olomu Aperan, / Ọlórọ̀-agogo, / O pin fún Olú Tapa / lempe ododo ina jo barausa. / Ojo patapata mulẹ d'Ẹkùn, / O pin fún Ọlọ̀wọ Aringinjin / adubulẹ f'agada / idẹ ju'ra O pin f'olówu Oduru, / o pin fún Ọlọ̀fa Arinnolu Ayinkinni / bọ ọmọ lẹ nu ati bẹebẹẹ. / Jala o pin ni o, / Eṣú-Ọ̀dàrà pin in mi o, / Bara Petu pin rere fún mi.", "REZO: OSHE TURA ALAGUEMA OMI TOWE IRELE LOSHAWO ILE YEBYU. OSHE TURA OYIYI ORUN OWO EKAN EMU WAKAMALE OBON OBAN TETE, EYA TUTU OMO OLUWO LERI LODAFUN BABA AGBONIRE- GUN IBO ERU NI ORUNMILA OÑO OTUNI OWO ORI AKO AIKOR- DIE LEBO ABEREMOKAN LORUBO. EYELE LEBO, OSI MIO MIO.", "REZO: OSHE TURA INA FARAYE IROKO INA FARAYE IROKO IROKO SOBAN. INAFARAYE YEYE YERE OLI LAYA ADIFAFUN OSHE TURA INA FARAYE AKUKO LEBO. (LA CANDELA ES BRAVA PERO NO ACABA).", "REZO: OSHE TURA LODAFUN UNBATINLO LEAYA BENIFO TETE NI NISHO INBAOYINI AFERE WEWE. AYABA DIDE AFERE WEWE. OSHE TURA EMI UNSORO ATIE ASHE OLODDUMARE EBO OMO IRE ODARA.", "REZO: OSHE TURA LODAFUN UMBA FUNLELEAYA BENFO TETE NINIS HE INIBA NI AFERE NEME AYABA DIDE AFERE MENE, OSHE TURA EMI UNSORO ETIE ASHE OLODUMARE EBBO OMO IRE ODAÑA."]}]$q$::jsonb),
(240,'1c2a73b9250d40f6822abc61940e7c3c',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ìrẹtẹ̀, llamado Ọ̀ṣẹ́ que parió a Ìrẹtẹ̀ y fundó la riqueza, trae buena fortuna para el dinero, el respeto y la influencia. Pide hacer las obras para que la fortuna no llegue tarde. El consultante debe avanzar con seguridad en los proyectos y relaciones nuevos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Empieza un proyecto o una relación nueva.", "Le llegan recursos inesperados y debe decidir cómo compartirlos.", "Quiere que su gente escuche lo que propone (relato del gallo y sus compañeros)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Dinero y clientes.", "Que la buena suerte llegue a tiempo.", "Palabra que es aceptada por la comunidad.", "Àṣẹ para fundar."]}, {"titulo": "Ibi y advertencias", "puntos": ["Fortuna que se retrasa o se distrae en el camino."]}, {"titulo": "Enseñanza principal", "texto": "Cuando se barre la casa y el camino, la basura se junta en el basurero: así se junta la fortuna en un solo lugar."}, {"titulo": "Relatos reunidos", "puntos": ["Ajé y los seres humanos. Ifá dijo: se ha convertido en Alájúbàràkà. Engendró a Olotooro, a Ọlotẹẹrẹ y a Ọ̀nàwòfunmirin; Ọ̀nàwòfunmirin engendró a Ajé, la riqueza, y Ajé engendró a los seres humanos. Ajé cruzó el mar y los seres humanos también viajaron lejos. Ọ̀ṣẹ́, corre al dios del océano y tráeme dinero; Ìrẹtẹ̀, corre lejos y tráeme clientes; àpẹ, no permitas que mi suerte llegue tarde; ejìnrìn, no dejes que mi suerte se pierda antes de llegar. Si barremos la casa y el camino, la basura se junta en el basurero.", "El gallo y su comunidad. El àṣẹ de Àrá, y la cuerda de trepar que la palma deja amarrar, adivinaron para el gallo, y le pidieron una paloma y dinero para que sus compañeros siempre aceptaran lo que él dijera. Ofreció, y desde entonces su gente acepta lo que el gallo dice.", "Ọlọ́fin y el àṣẹ para fundar. Ọ̀ṣẹ́ parió a Ìrẹtẹ̀: así adivinaron para Ọlọ́fin Ajàláyé, y le pidieron un carnero y dinero. Ofreció, y le dijeron: desde ahora tu palabra será capaz de crear una ciudad."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Medicina de la fortuna: hojas de àpẹ y ejìnrìn trituradas con tierra de basurero y jabón negro; marcar el Odù en la pared de la habitación con ẹfun (Ọ̀ṣẹ́) y osùn (Ìrẹtẹ̀); ofrecer dos palomas bonitas, una para cada lado, mezclar la sangre con el jabón y las hojas, restregarlo sobre las marcas y usarlo para bañarse.", "Para ser escuchado: una paloma y dinero.", "Para el àṣẹ: un carnero y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ajé, la riqueza. Olókun, el océano. Àrá, el trueno. Ọlọ́fin Ajàláyé."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Àpẹ (Celtis integrifolia), ejìnrìn (Momordica), tierra de basurero, jabón negro, ẹfun, osùn."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 240.1 (yorùbá): lfa I: o di Alajubaraka, / Emi l: o di Alájubaraka. / Bi a ba lo Jubaraka ki o Jubaraka, / O bi Olotooro, / O bi Ọlotẹerẹ. / 0 bi Onàwofunmirin. / Önàwofunmirin liobi Ajé, / Ajé liobi Èniyàn. / Ajé di o r'okun, / Èniyàn di o re Irada. / Ọ̀ṣẹ́! kiosaregege re i mu Ajé / wa fun mi nile Olókun... / Ìrẹtẹ̀! kiosaregege re Irada / kiolomu Èniyàn fun mi wa... / Apẹ! / kiomajẹki Ire mi pẹ kiotoo de. / Ejirin! / kiomajẹki Ire mi rin jinna kiotoode. / Biagba'le-gba'na odo / atitan li aiko ori rẹ si.", "Verso 240.2 (yorùbá): 240.2a / Àṣewaa niti Àirá, / Biabamu gbaf Ọ̀pẹ̀, / Ọpè a gbaa: / a difá fún Akuko-adiyẹ, / wọ̀n niki o rúbọ / ki àwọn egbẹ re / le maa gba orọ rẹ̀. / Ẹbọ: Ẹyelé ati egbèwá owó. / Ó rúbọ. / Wọ̀n nì: / \"Eyiti Akuką ba wi li àwọn ẹgbẹ re / yoo maa gba\". / 240.2b / Ọ̀ṣẹ́-Bi-Ìrẹtẹ̀: / a dífá fún Ọlọ̀fin. / Wọ̀n niki Ọlọ̀fin Ajàláyé wa rúbą: / Agbo ati egbàáwa owó. / Ó gbọ̀ ó rú. / Wọ̀n ni: \"Aṣẹ rẹ̀ a tẹ ilú\".", "REZO: OSHE BILE BOROBORO MOFA IRETE MOKURE IRETE YAMA YAMASA ADIFA FUN BEMI LOLA TINSHOMO OKUNI ARA ODA.", "REZO: OSHE BILE BI AWE ADAWE ADI ATOTO BABADONA OCUN BABALAWO LODAFUN ALAKENTA. OSHE BILE BI AWE ADAWE ADI ATOTO BABADONA ORUN BABALAWO LODAFUN ALAKENTU. OSHE BILE BI AWE ADAWE ADI ATOTO BABADONA ORUN BABALAWO LODAFUN ALAKENSI.", "OMO SISIROKO MAYE ALAKENTA. OMO SISIROKO MAYE ALAKENTU. OMO SISIROKO MAYE ALAKENSI. ADADA OMO OBI ALABI IFA AWO.", "REZO: BABA DOMA OBA NI ILU OMA BOGBO ALEYO LETI UNSO, BABA DOMA, BABA DOGUN ATI BABA DOTA INTORI EYO NI BABA DOMA UNLONI ILU OSHUN ATI BOGBO OMODE LOWA BABA DOMA, UMBO WA LODO ELEGBA.", "REZO: OSHE BIE ARA ONU ROYI ADIFAFUN TINSHE OMO OKUN ADIO ADGUE BIWEGBON ORUN ADIATOTO ALAKENTU OTITO."]}]$q$::jsonb),
(241,'0828e02c46e717bb314c513c304d634b',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Òfún habla de la capacidad de Ifá para resolver todos los problemas: cualquiera que sea la dificultad, hay solución. Los que se sienten castigados por el Creador encuentran su suerte cuando aprenden Ifá. Protege a los niños para que lleguen y se queden en el mundo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que un problema es más grande que su preparación.", "La familia está preocupada por la salud de un bebé; conviene llevarlo al médico (relato de los niños que llegan al mundo).", "Busca aprender antes de tomar una decisión."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Solución para toda dificultad.", "Suerte al final para el que aprende.", "Hijos que llegan y se quedan."]}, {"titulo": "Ibi y advertencias", "puntos": ["Creerse castigado por el Creador.", "Niños que se vuelven en la puerta del cielo."]}, {"titulo": "Enseñanza principal", "texto": "Si uno es desafortunado, es que todavía no es lo bastante sabio. La sabiduría está en Ọ̀rúnmìlà, el que repara el infortunio y levanta a los caídos."}, {"titulo": "Relatos reunidos", "puntos": ["Los inexpertos que aprendieron Ifá. Miren cuánta agua tiene la casa de Olókun, la mayor de las aguas, y la de Ọ̀sá, la segunda. La sabiduría está en Akódá, que enseñó Ifá al mundo; en Aṣèdá, que enseñó a los ancianos el buen consejo; y en Ọ̀rúnmìlà, que repara el infortunio y levanta a los que cayeron en la mala suerte. Así adivinaron para los inexpertos que lloraban cada día por su mala suerte y decían que el Creador los castigaba. Les pidieron jabón negro, una sábana blanca y dinero. Pocos ofrecieron; esos se bañaron con el jabón cada tres o cinco días, se cubrieron con la sábana, fueron a la casa de Ifá, se iniciaron y aprendieron. Al final, la suerte llega a los torpes que se ponen a aprender Ifá.", "Los niños y el portero del cielo. Ọ̀rúnmìlà dijo Àrodẹ̀, y adivinaron para los niños que venían al mundo y a quienes el portero del cielo no dejaba pasar: tenían que regresar y morían siendo bebés. Era porque no esperaban a Ọ̀rúnmìlà. Él les preguntó a dos, una niña y un niño, a quién esperaban, y respondieron: a Ọ̀rúnmìlà. Les dijo que lo siguieran, y en la puerta del cielo, cuando el portero quiso devolverlos, Ọ̀rúnmìlà pagó por cada uno. Esa misma cantidad se paga todavía por el nacimiento de un hijo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la suerte: jabón negro, una sábana blanca y dinero; bañarse cada tres o cinco días e iniciarse en Ifá.", "Por los niños: la cantidad que se paga por el nacimiento de un hijo."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà, el que repara el infortunio. Akódá y Aṣèdá, primeros maestros. Olókun y Ọ̀sá. El portero del cielo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Jabón negro, sábana blanca."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 241.1 (yorùbá): B'orí ko sunwọ̀n, / Ọgbọ̀n inú ni koito. / Omi nbẹ ni'le Olokun, / Okun olórí omi, / Omi mbẹ ni'le Ọlọ̀sà, / Ọ̀sá-ibikeji, / Ọgbọ̀n mbẹ ninu Akódá, / Akódá ti nkọ̀ gbogbo ayé n'Ifá. / Ọrọ nbẹ nikun Aṣèdá, / Aṣèdá tinkọ gbogbo agbà ni lmọ̀ràn. / Ọgbọ̀n mbẹ ninu Ọ̀rúnmìlà Amayégún, / Odudu ti ndú ori emère / Atúnritikòsunwon-se: / a daa fún àwọn Komooṣekomoowa / ti nfi ojoojumo kegbe / orí emère àisunwòn, / pe Ọba Flédá ti ṣe àwọn ni ibi. / A niki wọn rúbọ: Ọ̀ṣẹ́ (awẹfin), / ibora aṣofunfun ati ẹgbewá owo. / Apakon wọ̀n to rúbọ, / wọ̀n niki wọ̀n lọfi (9se) / awẹfin wọ̀n lo wẹ, / kiwọ̀n ma gbaiwẹ ni ojó mẹta / tabi márùn, / kiwọ̀n maa fi aṣo funfun bo'ra, / kiwón re ilé lọtẹ Ifá; / biwón ba tẹ lá tán, / kiwọ̀n kọ Ifá. / Wọ̀n gbọ̀ wọ̀n rú. / Wọ̀n ni: / “Komọọṣekọmọowa tiokọ Ifá, / orí rẹ̀ a sunwọ̀n nigbẹ̀hin\".", "Verso 241.2 (yorùbá): Ọ̀rúnmìlà I: Arode, / mo ni: Arode: / a daa fún àwọn omowẹwẹ nlọ sinu ayé / ti Onibóde nda wọn dẹhin lọna. / Wọ̀n nkú li ọmọ kekeke. / Wọ̀n ni: eetiri? / A ni: wọn ko duro de Ọ̀rúnmìlà ni. / Méjì, t'okunrin-t'obirin ninu wọ̀n / li Ọ̀rúnmìlà biileere pe: / Tani ẹ Ifa nduro de? / Wọ̀n ni: Iwọ Ọ̀rúnmìlà ni. / O ni njẹ o dára e maa kalo. / Wọ̀n ba Ọ̀rúnmìlà la de ibóde, / onibóde fẹ da wọn dẹhin. / Ọ̀rúnmìlà bẹbẹ fún wọn. / O san Ojojulugba owó lori wọn. / Ayanii oori Ojojulugba owó naa / li a nsan fi gbọ Orí omotitun titi di òni.", "REZO: OSHE KOSHEFERU ADIFAFUN EKO LOKORO OMA ALABA EYELE MEYI KAFEREFUN ORUNMILA, OSUN, OSHUN ATI ALEYO.", "IFA OFEFE OBAÑU. OSHE FUN IRE TURUKU KOROWO.", "SUYERE: BONOBLI BABA LOKUA SHEFUN MINABLI BABA LOKUA SHEFUN NAWABONU BOKUA SHEFUN.", "REZO: SHEFUN SHEFUN BABA ARERU ORUNMILA NI AYASHE RIA RIA AWO AWO IGBRIN KILU PEWO ONI KAKO ORUGBO ADAFUN LOEDE IKOKOLEYE WOFIN AWO ONI KAKO ADIFAFUN ONIKAKO PEWO ONI KAKO ORUGBO IGUI NI ASHO ERU ENI PEYU TONPOKOLERO.", "REZO: OLUO BOSHE ORIBAGUA ONI MOBE.", "+++"]}]$q$::jsonb),
(242,'af3b9afaaaa32f62a6323eaf7d34d258',$q$[{"titulo": "Idea central", "texto": "Òfún Ogbè habla de un enemigo poderoso y de una pelea o disputa inminente; el consultante se mete en problemas, a menudo legales o con el gobierno. Pide ofrendar para que el golpe no sea mortal y para volver a salvo de lugares peligrosos. No permitirá que la enfermedad lo sorprenda en lo que emprenda."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está en una disputa legal o con una autoridad (relato de Òfún y Ogbè).", "Su adversario parece más fuerte.", "Debe evaluar un viaje o un negocio con riesgos (relato de la tortuga y el mercado).", "Le llega dinero gracias al trabajo de la casa en conjunto, pero alguien siente que no le reconocen su parte (relato de Míèéyè y su esposa)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Sobrevivir a la pelea.", "Volver a salvo de un lugar peligroso.", "No cansarse ni enfermar en lo que emprenda.", "Que el doble espiritual del cielo ayude."]}, {"titulo": "Ibi y advertencias", "puntos": ["Una pelea o pleito inminente.", "Tres hermanos de los que solo quede el menor.", "Que los hijos pequeños mueran por accidente, en agua o fuego.", "Que el doble del cielo estropee un negocio."]}, {"titulo": "Enseñanza principal", "texto": "Quien ofrenda aunque crea que no lo necesita protege a los suyos. El creador de libres y esclavos también debe ofrecer por sus hijos."}, {"titulo": "Relatos reunidos", "puntos": ["Òfún azota a Ogbè. Òfún buscó a Ogbè por todo el oráculo y lo alcanzó en este Odù, decidido a azotarlo hasta la muerte. Pèrègún, el adivino, le pidió ofrecer un carnero para que Ogbè pudiera levantarse y sobrevivir. Ofreció. Por eso este Odù anuncia una pelea inminente y es más suave llamarlo Òfún Ogbè que Òfún Na Ogbè, el que azota.", "La tortuga en el mercado de los monstruos. La tortuga iba al mercado con los monstruos indomables. Le pidieron tres gallos, dinero y camarones para volver a salvo. Ofreció y volvió.", "El buitre que vuela bajo. Vuela bajo adivinó para el buitre cuando iba a la ciudad de los Ìgbò. Le dijeron que no se cansaría ni enfermaría, y que cuando tuviera hambre el dios del cielo le traería comida. Ofreció la faja de su cintura, una ollita de aceite de palma y un chivo. Por eso, cuando el buitre tiene hambre, en el pueblo ocurre alguna desgracia y él come de lo que se ofrece para acabarla.", "La orina, la saliva y el semen. Las espigas del maíz parecen un Egúngún pero no hacen lo que hace un Egúngún: así adivinaron para la Orina, la Saliva y el Semen, que era el menor, y les pidieron diez pollos y dinero a cada uno para volverse personas completas. La Orina no ofreció y la Saliva no atendió a Èṣù; solo el Semen ofreció. Por eso, cuando la Saliva toca el suelo desaparece, cuando la Orina toca el suelo se mete en la tierra, y cuando el Semen llega a su lugar se vuelve un niño sano. Tres hermanos de una misma madre deben ofrecer para no desaparecer y dejar solo al último.", "El dios blanco y sus dos hijos. Hierro viejo, los ganchos de hierro no se quiebran: así adivinaron para el dios de la blancura, y le pidieron ofrecer por sus dos hijos pequeños. Dijo que no podía, que él era el que creaba a libres y esclavos. Poco después los mandó a la finca: en el camino el río se llevó a uno, y al otro, mientras la gente venía a darle el pésame, se le quemó la casa con él dentro. El padre de dos hijos pequeños debe ofrecer dos gallos, dinero y una canasta de papilla de maíz, y cuidarlos del agua y del fuego.", "La calabaza de manteca. Vendido una vez en el mercado adivinó para la calabaza de manteca de karité, que iba al mercado de Èjìgbòmẹ̀kùn, y le pidió ofrecer por sus tres compañeros del cielo: El que agarra fuego con fuerza, El relámpago que destella y El que vive en casa y corta tutores de ñame. No ofreció tres palomas y dinero. Por eso la calabaza de manteca se usa una sola vez: el calor la derrite y la estropea, y el que compra la manteca se lleva la calabaza. En un negocio hay que cuidarse de que el doble del cielo no lo arruine."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para sobrevivir a la pelea: un carnero.", "Para volver a salvo: tres gallos, dinero y camarones.", "Para no enfermar en lo que se emprende: la faja de la cintura, una ollita de aceite de palma y un chivo.", "Para tres hermanos: diez pollos y dinero cada uno.", "Por dos hijos pequeños: dos gallos, dinero y una canasta de papilla de maíz.", "Para el negocio: tres palomas y dinero; echar parte del dinero en el camino."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù. El dios de la blancura (Òrìṣàálá). El doble espiritual en el cielo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Camarones, aceite de palma, manteca de karité, papilla de maíz, espigas de maíz."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 242.1 (yorùbá): Igi-rerẹ, Igi-igbó, / Igi-rerẹ, lgi-òdàn, / Pèrègún nwanini awo Eṣúmeri / li o difá f'Òfún, / Òfún nlọ na Ogbè pa. / Wọ̀n niki Òfún rúbọ ki Ogbè le nde. / Agbo kan li ebọ. / Ó gbọ̀ ó rú. / Ifá yi fihan'ni pe: / \"lja kan ati bẹẹbẹẹ mbọ\"", "Verso 242.2 (yorùbá): Òfún ng'ra, Aja nợ'ra / li o dífá f'Ọlobahun ljapá / nlọ bawon n'ọjá Ewele. / A niki ó wa rúbọ / kioma baa gbe s'ghun. / Akuko adiyẹ meta, / egbẹ̀taelógbọ̀n owó ati ede. / Ó gbọ̀ ó rú.", "REZO: OFUN NALBE AYERE YIREO AYERI GUI OFA PEREGUIKI OBA. OSHUN LODAFUN OFUN ODAFO OBA NUBA OGBE DONLARA OFUN AIKORDIE META ELEBO. EBEYO OWO ELEBO.", "REZO: OFUN NALBE AUYETRE YIREO AYERI GUI OFA PEREGUIKI OBA OSHUN LODAFUN OFUN ODAFO OBA NUBA OGBE DONLARA OFUN AIKORDIE META ELEBO. EBEYO OWO ELEBO.", "REZO: OFUN NALBE EYELE EYIRA ESHERO GODA PEREGUN OMOBA OMAYA MAKA OMO OLORUN OFUN NARBE ODE OYE ORISHA ALELE IFA.", "REZO: OSHENARA AYANARA ADIFAFUN ALABO PASHAN META EYELE META LEBO AWO ONARE IGUIBO AÑA ARO IWO PEREGUN ELEGBA OMO ELENU.", "REZO: OGA EMKU EÑON ADIFAFUN OLODE AYA KONFE SHEKETE EGGUN ORI GIDIGIDI MUNDIA PUPAME AWO SILE ITAN IGUI KAN OBI LESE ISHE KOSI ORUN KAN OBO SIMU IGBOLO LOWO ORONAFUN ENIKU ENI MASI SOFUN ONKO SINO OLORUN YI BERE SALU OMO AKOKO LEBERE OSI LUN BERE SI MADI LODAFUN YANZA.", "SUYERE: IYAN EGGUN OTIPE EBA OKO BOMI EBA OWO LENI.", "REZO: OFUN NARBE OKITI BABA NI PEKUN ADIFAFUN OMO LAGA, LABA LABA LORUN ABOFUN ESHU LABA LABA LORUN NIKA ESHISHI TIMBE LE;I TINSHEBO OMI EWEOENIMI EWE EÑIÑI LABA LABA LOTE NINU ESHU KAFEREFUN ORUNMILA.", "REZO: OBONI FATIWA ADIFAFUN ODE AYAYOTA ANITILA ABO NITILA ADIFAFUN OSHOSIS LORUBO OBANI LEBO OWUNKO OFA LEBO."]}]$q$::jsonb),
(243,'eea85ad344a20bde0c9ff24c5a54761f',$q$[{"titulo": "Idea central", "texto": "Òfún Ọ̀yẹ̀kú asegura vida larga, respeto y buenas relaciones de pareja con la ofrenda y la buena conducta. El consultante puede esperar un tiempo de calma. Pide que su trato con la gente sea dulce como la miel y que sea amable con los pobres."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera una etapa de calma después de las dificultades.", "Quiere cuidar el trato con su pareja, su familia o sus visitas.", "Le gusta dar de comer y de beber, y se pregunta cómo hacerlo sin agotarse (relato de Isimibakalẹ).", "Necesita alternar la atención a otros con momentos de descanso o viaje."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vida larga y sin desgracia.", "Respeto y buena pareja.", "Un periodo de calma y tranquilidad."]}, {"titulo": "Ibi y advertencias", "puntos": ["Trato amargo con la gente.", "Olvidar a los pobres."]}, {"titulo": "Enseñanza principal", "texto": "El trato entre las personas debe ser como la miel, que nunca es amarga. Quien dice al hambriento 'ven y come' y al sediento 'ven y bebe' no cae en desgracia."}, {"titulo": "Relatos reunidos", "puntos": ["Ìsimibakalẹ̀, amigo de todos. Ìsimibakalẹ̀, el que da de comer y beber cada día, amigo del dueño de casa y amigo del forastero, que dice al hambriento 'ven y come' y al sediento 'ven y bebe', consultó para no morir ni caer en desgracia. Le pidieron cuatro telas, dinero y miel, y le dijeron que el trato con la gente debe ser como la miel, que nunca es amarga. Después de ofrendar, le aconsejaron alejarse a veces de la gente, viajando de vez en cuando, y ser amable con los pobres. Escuchó y ofreció enseguida."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Cuatro telas, dinero y miel; viajar de vez en cuando y ser bueno con los pobres."]}, {"titulo": "Relaciones espirituales", "texto": "La comunidad, los forasteros y los pobres."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Miel, telas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 243.1 (yorùbá): Amooṣematẹ, / Amuludun awo Isimibakalẹ: / li o difá fún Isimibakalẹ, / Animaṣawun, / Afojoojumo funninijijemimu, / Ọrẹ-onilé, / Orẹ-àlejò, / Ẹni-àlejòkan-ko-gbodoki. / A ni: / Bi ebi ba npa q kioya wa jẹun. / Bi oungbẹ ba ngbẹ ọ kioya wa mu. / Wọ̀n niki ó rúbọ: / E maa kú, E maa te. / Ebọ: Aṣo mẹrin, / okẹ mẹrin owó ati oyin. / Wọ̀n ni: / Iwáyé oyin kiikorò. / Bioba rúbọ tan, / kiomaa yèra fún àwọn omọ aráyé. / Kio maa fi igba kan los'oko, / kiomaa fi igba miran re ajo, / ki o maa ṣe oore rè / f'àwọn Olùpónjú, / Ó gbó ko ja fara rara / kio too rú ẹbọ na.", "REZO: OFUN YEMILO KUNUKU ABERIKULU NINSHAWO INLE OLOFIN AKALA MABO ABIGUI OLORUN NINSHAWO INLE OLOFIN TENTE TERE ABI ABI APOLO.", "MAFEREFUN OBATALA ATI ESHU.", "REZO: OFUN YEKU OBBI DADE AWO MAMULORDO MAYALURE AKUKO MOLATA OGBA OSSI OKO MORBAGDI AWO MORBAZUN AWO TINSHE MOLERI OBBA AFELERBO EWE OZAIN WOARUN KESHE OBBA ISHE OZAIN EWE TOMODE OBBA NI AWALORDE MAFUN ENI LOYIRE UNYEN AKUKO EWE OZAIN ONI OBBIDAGBO AWO OKO ODARA.", "REZO: OFUN YEKU OBBI DADE AWO MAMULORDO MAYALURE AKUKO MOLATA OGBA OSSI OKO MORBAGDI AWO MORBAZUN AWO TINSHE MOLERI OBBA AFELERBO EWE OZAIN WOARUN KESHE OBBA ISHE OZAIN EWE TOMODE OBBA NI AWALORDE MAFUN ENI LOYIRE UNYEN AKUKO EWE OZAIN ONI OBBIDAGBO AWO OKO ODARA.", "REZO: OFUN YEKU OBADIRE AWO MAYANO BADIRE AWA ESHISHI OBINI OBO IBA OKUNI AKOA DORILE BOTIBAYE MEFUN OYEKUN FUN AYAYIGUO AWO KARI BOSHE INTORI ELE ERAN OKOA DISILE SOKU WODE OKUNI AWO ABADIRE IFA KAFEREFUN ORUNMILA OBINI ABUN OBA OBANI SHANGO OKODARA OKO ADASILE.", "REZO: OFUN YEKU BAGDEREFA ONI BABALAWO LERI OBAYE LAYE LADIREO IKU BOLORIFA OFUN YEKU OBARI BASHE OMO NI SHANGO OMO NI ADELE OYO NIBARI OWO AWO LADEO NORI YEYE AFEWO OMO NI YOYE OMO ALU KOLABA ASHEBO ASHETE ASHO LOWO BABAWA ASHOTAN ASHO ARAE NINO AGBA LERI NI ALA KOLABA.", "REZO: OFUN YEKU WAYEKUN FUN IKU MAFUN EGGUN IYA MAWALODE FUN ILUKU MAYEKUN FUN IYA SOKU KOSHENIFA IDI OMO OFUN YEKU OLORUN KAYO DIREO AFERFE AYO UN OZAIN AWATISHE IRE AMAYA ORUN OZAIN AWADO NI LERI ASHEGUN OTA WATISHENI SHANGO OZAIN IFA KAFEREFUN IYA KAFEREFUN OZAIN."]}]$q$::jsonb),
(244,'1208df928c269cc00ab75c9ef82d6a56',$q$[{"titulo": "Idea central", "texto": "Òfún Ìwòrì explica que el buen uso del dinero asegura satisfacción en la vida, y que el dinero puede provocar controversias o problemas emocionales. Quien es bondadoso puede recibir como hijos a los hijos de otros. Promete que el que hoy parece loco en la casa terminará siendo su dueño."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Un pleito por dinero le afecta el ánimo o una relación.", "Quiere que reconozcan sus recursos o teme que lo busquen solo por ellos (relato de Ọlakanmi y Ajé).", "Tiene bienes, pero siente que le falta familia o alguien a quien cuidar (relato del escarabajo sin hijos)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que la riqueza lo busque por todas partes.", "Hijos, propios o adoptados.", "Ser dueño de la casa y de los que viven en ella.", "Que nadie se atreva a enfrentarlo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Que otro se quede con el fruto de su trabajo.", "Muerte repentina de un hijo único.", "Que le den medicina mala en la comida.", "Gastar todo para no morir."]}, {"titulo": "Enseñanza principal", "texto": "Si somos bondadosos, podemos aceptar como propios a los hijos de otros. El machete siembra el ñame y el maíz, y otros se los comen."}, {"titulo": "Relatos reunidos", "puntos": ["Ajé en el fondo del río. Ọlakanmi adivinó para Ajé, la riqueza, y le pidió frijoles blancos, sal, miel y dinero para que todo el mundo la buscara en todas partes. Ofreció. Un día Ajé se metió a propósito en el río, y todo el mundo va a buscarla hasta el fondo.", "El escarabajo que se volvió padre. Ọbọ̀nhùnbọ̀nhùn, el escarabajo, era muy rico pero se sentía pequeño porque no tenía hijos. Le pidieron diez ratas, diez pescados, diez palomas y dinero. Ofreció. Más tarde Èṣù lo encontró en el camino a la finca y le dijo que recogiera cualquier insecto joven, lo llevara a su casa y lo cubriera con tierra, y que Odùduwà los volvería hijos suyos. Así se volvió padre, y eso es lo que hace todavía hoy.", "Ṣàngó, Hojas Ayúdenme. Òfún mata a Ìwòrì enseguida; no me tomes de la mano, no llevo pantalón: así adivinaron para Hojas Ayúdenme, nombre de Ṣàngó, y le dijeron que sería rey de la gente de la tierra y del cielo. Le pidieron un carnero, dinero y doscientas piedras blancas de cuarzo. Ofreció, y desde entonces nadie se atreve a enfrentarlo, ni en la tierra ni en el cielo: nadie oye su trueno sin correr. Ifá dice que hay un hombre que anda por la casa como loco y que con el tiempo será su dueño, y hombres y mujeres se reunirán a servirle.", "Kannike, el machete. Òfún vacío, Ìwòrì muy pesado adivinó para Kannike cuando iba a huir al monte por un caracol que debía. Le pidieron cuatro palomas y dinero para no perder el fruto de su trabajo. No ofreció. Kannike es el machete: desde entonces, cuando siembra ñame o limpia el terreno para el maíz, lo ponen a un lado y otro se lleva lo que produjo.", "La vendedora de buñuelos y su hijo único. Òfún, adivino de Igando, e Ìwòrì, adivino de Igando, con la tela de muchos colores, que es tela de bruja, adivinaron para la vendedora de buñuelos de la ciudad de Ẹ̀rìwọ̀n. Le dijeron que solo su hijo Honor sería aceptado como ofrenda, pero que ofreciera una chiva, dinero y su tela para que el niño no muriera. Ofreció. Quien tiene un solo hijo debe ofrecer para que no muera de repente sin que se sepa la causa.", "El granero, cabeza de las estériles. El granero grande hace reír al campesino: así adivinaron para Ẹ̀fúnṣẹ̀kú, cabeza de las mujeres estériles de Ifẹ̀, y le dijeron que ese año le llegarían bendiciones del cielo y de la tierra, y que ofreciera contra la medicina que se da en la comida. Ese es el granero: cuando se guarda en él ñame, maíz y frijoles, cada uno llega y se lleva lo suyo, hasta dejarlo vacío y caído. Le pidieron una oveja, dinero, una tinaja de aceite de palma y la tela de su cuerpo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para atraer la riqueza: frijoles blancos, sal, miel y dinero.", "Para tener hijos: diez ratas, diez pescados, diez palomas y dinero.", "Para ser respetado: un carnero, dinero y doscientas piedras blancas.", "Para no perder el fruto del trabajo: cuatro palomas y dinero.", "Por el hijo único: una chiva, dinero y la tela de la madre.", "Contra la medicina en la comida: una oveja, dinero, una tinaja de aceite de palma y la tela del cuerpo."]}, {"titulo": "Relaciones espirituales", "texto": "Ajé, la riqueza. Èṣù y Odùduwà dan hijos al escarabajo. Ṣàngó."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Frijoles blancos, sal, miel, piedras de cuarzo blanco, aceite de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 244.1 (yorùbá): Ọlakanmi: / a difá f'Ajé. / Wọ̀n niki Ajé wa rúbo, / ki omo-araye bi wọn ti nwaa l'oke yi / ki wọn lẹ maa waa l'odò. / Eree, iyo, oyin / ati egbèwá owó li ebọ. / Ó gbọ̀ ó rú. / Aje wa moomo binu wọ odò omi / lo nijọ kan, / àwọn qmo-aráyé / lọ waa ninu odò nisalẹ omi.", "Verso 244.2 (yorùbá): Biaba-n'inú're-omọ- / Ọlọ̀mo-a-maa-di-omo-eni: / a difá fQbònhùnbònhun / to Kolek'aasẹ tan tikobimo rara. / Wọn npẹgan rẹ kiri pe: / Ko bimo o kole. / A niki o rubọ: / eku méwà, eja méwà, eyẹlé mẹwà ati egbèwá owó. / Ó gbọ̀ ó ru. / O pẹ ti wọn li npẹgan rẹ, / eniti o ba si rúbo ni. / Èṣú ngbe, / nitorina Eṣú pade Ọbọ̀nhùnbọ̀nhùn / nijọ kan ni ona oko. / O niki iwọ maagbe omo kokoro / tiobawu ọ lọ sinu ilé rẹ̀, / kiomaa fi erupẹ lẹe mọ ibẹ. / Odùduà yoo sọọ di ọmọ fún q. / O gba imoran naa o di Ọlomp, / iwà naa ni obọ̀nhùnbònhùn / nhu titi di oni.", "REZO: OFUN OGUO OGUORI AWO GANDO ADIFAFUN LUCORO LALLU ETU LEBO.", "IFA LODAFUN OLOFIN, ORUNMILA Y ESHU INTORI IKU ARO LERBOANRU EYELE MENI AIKORDIE ACHO TIMBELARA EFUN ORI ITANA EWE FA OWO LA MEFA TONTI EFA.", "REZO ARARA: FUÑI GAGBO WOLI KAÑI GAS AXOSUWE JEBU BOSIFA TAJU.", "OFUN AWO IWORI AWO GANDO ADIFAFUN LUKORO YAYU ETU LEBO.", "IFA LODAFUN OLOFIN, ORUNMILA ATI ESHU.", "OFUN IWORI GANDO ADIFAFUN OLUWO KOSO BAYE.", "REZO: OFUN GANDO OFUN DORO IWARI ADIFAFUN KANIKE TOMA TORI TOWOKAN KUSHE LE NIWON NIKI ARU EYELE ISHE ASHE DANU KANIKE ORUKO ADAYE ADA BAKO ISHU SHAN AWADO ASIKO BAKO ISHU SHAN AWAGDO ASIRO EREYE."]}]$q$::jsonb),
(245,'6ead087d71be81745292b3384ba06d0c',$q$[{"titulo": "Idea central", "texto": "Òfún Ìdí advierte contra la codicia, la avaricia, la glotonería y el egoísmo. El consultante está tan enfocado en los negocios que descuida a su pareja y a su familia. Pide no ser demasiado ambicioso para no perder la oportunidad del destino, y escuchar al adivino que advierte el peligro aunque no guste."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le dedica casi todo su tiempo al negocio y descuida a su pareja, su familia o sus amistades.", "Retiene recursos o decisiones dentro de casa por miedo a que falten (relato de Olorí-Ogá).", "Puede estar juzgando a los demás solo por lo que producen."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que la buena fortuna fluya dentro de la casa.", "Recibir la lámpara del destino.", "Salvarse de los espíritus que vienen a apresar."]}, {"titulo": "Ibi y advertencias", "puntos": ["Cerrar la puerta a la fortuna dentro de casa.", "Ambición desmedida que lo deja colgando.", "Castigar al que dice la verdad."]}, {"titulo": "Enseñanza principal", "texto": "Quien restringe la buena fortuna dentro de su casa nunca recibe el bienestar de afuera. El muro que se derrumba en casa no mata a nadie en la finca."}, {"titulo": "Relatos reunidos", "puntos": ["Olórí Ọgá y la fortuna de la casa. Òfún impide conocer la buena fortuna; hay que actuar rápido para que Òfún no nos mate: así adivinaron para Olórí Ọgá. Quien no deja entrar la buena fortuna en su casa nunca recibirá el bienestar de afuera. Le pidieron una paloma, una carnera, muchas nueces de kola y dinero para que la fortuna fluyera dentro de la casa.", "Ṣakéù y la soga al cielo. Ṣakéù, hijo del rey y muy rico, iba a subir la colina a tomar la piedra del título cuando murió su padre. Le pidieron una oveja, dinero y una tela blanca, y no ofreció. Visitó a todos los jefes con regalos y luego preguntó: ¿a quién más hay en la tierra que pueda visitar? Colgó una soga del cielo y subió. El dios del cielo le dijo: ¿no queda nadie en toda la tierra a quien visitar? Que no lo hiciera nunca más. Al bajar, Èṣù le cortó la parte de abajo de la soga, y al querer volver a subir, le cortó la de arriba. Ṣakéù quedó colgado en el aire bajo el sol, muriéndose de hambre, y gritaba: me muero de hambre, hijo de un jefe de arriba. El dios del cielo quiere darle a alguien la lámpara del destino; que no la eche a perder por ambición excesiva.", "La gente de Ìgbàdé y el adivino atado. Salta de una vez, adivino de Ìgbàdé, les dijo a los de Ìgbàdé que ese año les llegarían bendiciones, y se alegraron. Pero El muro que se cae en casa no mata a nadie en la finca, también adivino de Ìgbàdé, dijo que espíritus del cielo venían a apresarlos y que ofrecieran dinero, un gallo y sogas trenzadas. La gente lo tiró al suelo, le pegó y lo dejó atado. Donde lo dejaron, Èṣù echó polvo al monte y aplaudió: el monte se volvió guerreros, que capturaron a todos. La gente dijo que un adivino les había avisado. Èṣù preguntó dónde estaba, y los guerreros corrieron a él: ¡este sí es un hombre! Le pidieron que adivinara para ellos, y él dijo que no lo haría si no soltaban a la gente de Ìgbàdé. Los soltaron, y cada uno le llevó dinero, una soga trenzada y un gallo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la fortuna en casa: una paloma, una carnera, muchas nueces de kola y dinero.", "Para no perder el destino: una oveja, dinero y una tela blanca.", "Contra los espíritus que apresan: dinero, un gallo y una soga trenzada cada uno."]}, {"titulo": "Relaciones espirituales", "texto": "El dios del cielo y Èṣù castigan la ambición y la soberbia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Obì (kola), sogas trenzadas, tela blanca."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 245.1 (yorùbá): Òfún di'remo / Wàràgbàṣewàrà / ki Òfún ma le pa'ni. / a daa f'Olorí-Ọgá. / A ni: / eniti ó dí ire mọ'lé / kiri t'òde gba. / Wọ̀n niki o wa rúbọ: / eyelé, àgutàn, opo obi ati egbàáwa owó, / ki ire baa le ma san wa ilé.", "REZO: OFUN DI ADIFAFUN ERI ETU KOMOBA . OFUN DI OSO TO AKUKO, EYELE, LERI ETU LEBO.", "REZO: OFUN DI AWONIFA AWO LERI MASHE KUE EBONI BELEKE INLE AÑAÑA YOFUN OGORI NISHAWO EBERI YOYORUN IYARE EGGUN AWO IBASHE ORINI BASHE OFO LERI BOSHE SHAGO ENI BEWA ELINI OYUN ORI INTORI OFO OSUTO ADIFAFUN ETU OSUTO ADIFAFUN LOTI OSUTO ABENI AWA OYU BENU BOSHE INLE TORI ALA ELEGBA IBASHE ORI BASHE AKUA ERIN BOSHE ELERI FIFETU AWA NI AWA ONASHISHI AWA OBANI BOSHE BOBONI ORUMALE OFUNDIAWO MOFUN EWA BENI ORUN LONI LAYE OPKUELE BOSHE AWO.", "REZO: OFUN DI MAMOWO ERI EFUN EMI ALARAN ADIFAFUN LERI OTORI BOSHE NIKO OBESAWA AWO EMIBEDE AWASHA. SHANGO ETU SIWO ONI LEKUN NI ISHE ISHE ENI LEKUN.", "SUYERE: EYELE DUN DUN MAWA. EGGUN DUN DUN MAWA EYELE FUN FUN MAWA EGGUN FUN FUN MAWA.", "REZO: OFUN DI ADIFAFUN OBATALA OFUNDI OWO OTO CURE."]}]$q$::jsonb),
(246,'d4ca243d2e7b17ffc2e5c164bada8275',$q$[{"titulo": "Idea central", "texto": "Òfún Ìrosùn pide ofrendar para borrar penas y aflicciones y lograr una vida larga y feliz. Es buena señal para una relación de pareja nueva. Advierte que el sacerdote o curandero que traiciona a quien atiende arruina su trabajo, y anuncia bienes inesperados para quien hoy no tiene nada."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere aliviar una pena (relato de Ewa-olú).", "Empieza una relación íntima.", "Busca sentido ante una pérdida o un cambio."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un mundo dulce y placentero.", "Una pareja nueva; embarazo.", "Bienes inesperados que llegan solos.", "Volver al camino después de extraviarse."]}, {"titulo": "Ibi y advertencias", "puntos": ["Oscuridad y aflicción en el camino.", "Un curandero que traiciona al enfermo.", "Extraviarse por no ofrendar."]}, {"titulo": "Enseñanza principal", "texto": "Òfún reparte bendiciones sin hacer escándalo. Quien quiera hacer maravillas debe mirar al cielo. El que traiciona a quien cura pierde el poder de curar."}, {"titulo": "Relatos reunidos", "puntos": ["Ẹwà Olú y la miel. Òfún Ìrosùn adivinó para Ẹwà Olú y le dijo que el mundo sería muy dulce para él si ofrecía una botella de miel y dinero. Ofreció.", "Los seres humanos y las maravillas del cielo. Òfún reparte muchas bendiciones y no hace escándalo de ello; personas así son difíciles de encontrar. Quien quiera hacer maravillas debe mirar al cielo, que es el lugar del honor. Así adivinaron para los seres humanos, a quienes se dijo que la muerte les daría a ver las maravillas del cielo, y les pidieron cuatro gallinas, cuatro tortugas, cuatro telas blancas y cuatro paquetes de kola para quitar la oscuridad y la pena de su camino. Oyeron, pero no ofrecieron.", "Òfún se lleva a Ìrosùn. La boca de la escoba está de un lado: así adivinaron para Òfún cuando iba a traer una novia de su barrio. Le pidieron dos gallinas y dinero. Ofreció, se unió a Ìrosùn y ella quedó embarazada.", "Ṣófẹ́, el adivino traidor del Ẹ̀wí. Ṣófẹ́ adivinaba para el Ẹ̀wí de Àdó y se acostaba con su esposa, y todo lo que hacía por el rey dejó de funcionar. El Ẹ̀wí mandó llamar a El que se encuentra caminando, adivino de Ọ̀fà. Ṣófẹ́ supo que el otro lo superaría y le dijo al rey que ese día llegaría un adivino que debía ser ofrecido en sacrificio. Los mensajeros lo apresaron en el camino, y él protestó: ¿se invita a alguien para matarlo? Luego le dijo al rey que el adivino de la casa le estropeaba los asuntos porque se acostaba con una de sus esposas. Ṣófẹ́ lo negó, y el de Ọ̀fà pidió que todas las esposas vaciaran sus bolsas de ropa: en una apareció una faja del Ẹ̀wí que él había entregado como ofrenda y Ṣófẹ́ se había llevado como pago. Ataron a Ṣófẹ́ para enterrarlo en el patio. Ṣófẹ́ rogó al otro, que le recordó cuando lo había señalado para el sacrificio; aun así lo ayudó a saltar la muralla y huir, mató una chiva, la enterró en el hoyo y dijo al rey que había matado a Ṣófẹ́. Para el sacerdote o curandero es tabú acostarse con la esposa de quien atiende: sus medicinas dejan de funcionar. Si un enfermo no mejora, debe tener cuidado con quien lo cura.", "El basurero que se casó con Gbọ̀rọ̀ngàgà. Amontona montón de ñame, adivino de la finca, adivinó para el Basurero cuando vivía solo, sin una calabaza ni un plato. Le dijeron que encontraría mujer y que esclavos e hijos se reunirían a servirle si ofrecía una rata, un pescado, manteca de karité, un chivo y dinero. Ofreció, conoció a una mujer llamada Gbọ̀rọ̀ngàgà y se casó con ella. Desde entonces todos los que barren sus casas y las calles echan lo barrido sobre el Basurero, y lo que se encuentra en la casa y en la calle es suyo. El hongo que brota de noche en el basurero se llama Gbọ̀rọ̀ngàgà.", "Òfún Olósùn y el hijo. Òfún Olósùn lloraba con tiza en la cara porque no tenía hijos. Le pidieron ofrendar para que ese año le llegara la bendición de un hijo, y ofreció. La mujer que busca hijo ofrece una gallina a su cabeza y se marca el ojo derecho con ẹfun y el izquierdo con osùn.", "Òjúrò y las plumas de loro. Òjúrò iba con la diosa del mar a celebrar su fiesta anual. Le pidieron dos palomas y dinero para no extraviarse, y se negó: no era la primera vez que iba. En el camino Èṣù apuntó su bastón al monte y ella se perdió; su familia, al ver que no volvía, hizo la ofrenda. En el monte encontró un montón de plumas rojas de loro donde dormía el rey de los loros, las metió en su tela y salió al camino con ellas en la cabeza. Su gente la encontró cantando y bailando, y la diosa del mar le dio a una de sus hijas. Quien anda como extraviado debe ofrecer a la deidad de las plumas rojas de loro, que lo llevará al buen camino."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la dulzura: una botella de miel y dinero.", "Para quitar la oscuridad: cuatro gallinas, cuatro tortugas, cuatro telas blancas y cuatro paquetes de kola.", "Para la pareja: dos gallinas y dinero.", "Para el enfermo traicionado: una chiva, dinero y la tela del cuerpo; para quien va a curar fuera: una oveja, una tela y dinero.", "Para los bienes inesperados: una rata, un pescado, manteca de karité, un chivo y dinero.", "Para el hijo: una gallina a la cabeza; ẹfun en el ojo derecho y osùn en el izquierdo.", "Para no extraviarse: dos palomas y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "El Ẹ̀wí de Àdó. La diosa del mar (Olókun). La deidad de las plumas rojas de loro (Ifá, Ọ̀ṣun). Èṣù."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Miel, ẹfun, osùn, plumas rojas de loro (ìkóóde), hongos, kola, manteca de karité."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 246.1 (yorùbá): Òfún'Rosù: / a dífá fún Ẹwa-olú. / Wọ̀n ni: / ayé Ewa-olú a dùn titi alẹ. / Ebọ: Igo-oyin ati egbàá méje owó. / Ó gbọ̀ ó rú.", "Verso 246.2 (yorùbá): Òfún nfún ire ka, / Òfún ko pariwo, / Eniyàn bi iru wọnyi sowọn l'ayé. / Eni maa daṣa kow'òrun ṣe, / Ọ̀run ni lé ọlá: / a dífá f'àwọn Eniyàn. / A ni ikú mi a maa mu wọn / lowo iṣe-orun. / A niki wọn rúbo / kioma baa si òkùnkùn / ati ibànújé lọna wọn. / Adiyẹ funfun mẹrin, ljapá mérin, / aṣo funfun mẹrin, ẹgbẹrin obi mérin. / Wọ̀n gbọ̀ sugbọ̀n wọ̀n ko rúbọ. / 414 Ewa-olú: La belleza. / 415 Igo-oyin: botella de miel.", "REZO: ESHU GOGORO EWO ADIFAFUN OLOFIN, ETU LEBO, ORI, AKUKO, EYELE LEBO.", "REZO: OFUN ROSO SOYU ESHU GOGORO ADIFAFUN AKABANA LERI ETU LORUGBO MAFEREFUN OLOFIN.", "REZO: OFUN ROSO IF LODAFUN OBATALA, OSUN, YEMAYA; MAFEREFUN OFUN ROSO SOYU ESHU GOGORO OGUE BARA OLODAFUN OLOFIN, LERI ETU MEYI ELEBO.", "REZO: OSHA GERERE AWO ALAWO BANA ADIFAUN OLOFIN ETU ELE- BOORI AKUKO EYELE LEBO OFUN IROSUN BOYU OSHA GERE ADIFAFUN ALAWO BANA LORI ETU.", "REZO: ORUBO KAFEREFUN ODUDUWA AWO ERUN OKON LODAFUN OBATALA KAFEREFUN OSUN LOYU AWO LENU AWO NI KAFE- REFUN ORUNMILA IKIN ADIFAFUN OLOSUN KORIE YEYE A EFUN SOYU SOKUN IFA NI KAFEREFUN ODUDUWA, IFA NI KAFEREFUN OLOFIN.", "SUYERE PARA DARLE LAS ADIE: EYE ORI KANWA ODUDUWA ETIWA ORI IRE AGBA ADIE OLOFIN.", "REZO: SHOFE LA AWO EWI ARIN ENAKO AWO OFASHOFE INSHE AWO FUN EWI OSIDE AYARE BOGBO ONUN TINSHEFUN KOBAGCHE NI KOJE NIGBARA OSHIFUN PE BABALAWO KAMBO NI ODO RE LENI BABALAWO NANI EBBO NITORINA EWI NISHE.", "REZO: SHOFE BE ARINONAKO WASOFUN PESHE OMO AIGBA TOFIYAN ANNIBE TITI ARINAKO.", "SUYERE: ARINAKO OMASHE JUN ESHENI. VERSICULO 247-2", "REZO: ESHU GOGORO EWE EBONA ADIFAFUN ETU MERI LEBO, OWUNKO EYELE LEBO."]}]$q$::jsonb),
(247,'aeafd70df5905701e63e342708d8e8d3',$q$[{"titulo": "Idea central", "texto": "Òfún Ọ̀wọ́nrín dice que las buenas acciones y el buen carácter traen su propia recompensa, aunque el consultante se sienta menospreciado. Pide ofrendar para que el bien que se da y se desperdicia vuelva a quien lo dio, y para que los enemigos no le quiten sus bienes. Anuncia hijos, una pareja y la muerte de quien maldice."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Ayuda o trabaja por otros y siente que no lo valoran (relato de Odùduà y los bienes desperdiciados).", "Quiere seguir haciendo el bien sin esperar que le reconozcan cada favor.", "Le preocupa perder bienes o que otros desperdicien lo que compartió (relato de Ọlakanmi)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que el bien que hace vuelva a sus manos.", "Bendiciones de Olódùmarè.", "Escapar de la muerte accidental.", "Muchos hijos, como el maíz.", "Una esposa que otros no vieron."]}, {"titulo": "Ibi y advertencias", "puntos": ["Ingratitud de quienes reciben.", "Enemigos que quieren quitarle sus bienes.", "Alguien que lo maldice y no lo deja avanzar."]}, {"titulo": "Enseñanza principal", "texto": "Hacer el bien a todo el mundo es el mejor rasgo del carácter: una parte no lo agradecerá y otra no sabrá usarlo, pero un padre y una madre, aunque no puedan, dan cosas buenas a sus hijos. A quien hace el mal, se le da kola para que nos bendiga con su propia boca."}, {"titulo": "Relatos reunidos", "puntos": ["Odùduwà y el bien desperdiciado. Òfún da a todos para ser preferido y para ser cuidado: así adivinaron para Odùduwà, que iba a hacer el bien en el mundo. Él dijo que hacer el bien a todos es el mejor rasgo del carácter. Le respondieron que una parte del mundo no se lo agradecería y otra no sabría usarlo. Él dijo: un padre, aunque no pueda, da cosas buenas a sus hijos; una madre, aunque no pueda, da cosas buenas a sus hijos. Le pidieron una paloma, una tortuga marina, dinero y medicina de Ifá para que lo que diera y se desperdiciara volviera a sus manos. Ofreció.", "Ọlakanmi y sus bienes. Òfún da a todos para que rían: así adivinaron para Ọlakanmi, y le dijeron que Olódùmarè le daría bendiciones, y que ofreciera tres cuchillos, tres gallos y dinero para que sus enemigos no tuvieran poder sobre él ni le hicieran perder sus propiedades. Oyó y ofreció.", "El buitre y el águila pescadora. Cuando espíritus del cielo venían a apresar a la gente, Ifá adivinó para el buitre y el águila pescadora y les pidió ofrecer contra la muerte accidental. El águila se negó: lo que el dios del cielo hizo, no lo dejó sin terminar. El buitre dijo que su suerte no era buena y ofreció un chivo, dinero, una olla de aceite de palma y la faja de su cintura. Le dijeron que anduviera sin miedo, que no moriría de accidente ni pasaría hambre, porque su doble en el cielo lo recordaría. Desde entonces nadie toca al buitre cuando se posa, y nunca se ve un buitre muerto; al águila pescadora la cazan y se la comen.", "El maíz de muchos hijos. Hoyos y tumbos inesperados adivinó para la gente del pueblo de las colas de vaca, que es el maizal, y les pidió dinero y una paloma cada uno para que les llegara la bendición de los hijos. Ofrecieron, y desde entonces el maíz da muchísimos granos.", "Ọkọ̀lọ̀ y Ṣẹbẹjẹ. Ferefere saca las nalgas tiesas adivinó para el dios del cielo Ọkọ̀lọ̀ cuando iba a casarse con Ṣẹbẹjẹ, esposa del Ojo. Ifá dice que llega la bendición de una esposa: una doncella que los ojos de otros pasaron por alto. Se hace un festín con dos gallinas y dinero.", "Ọ̀rúnmìlà y la maldición de Ọ̀nà Ilédì. Ọ̀rúnmìlà y Ọ̀nà Ilédì eran enemigos, y Ọ̀nà Ilédì conocía una maldición que se toca con los labios. Le pidieron a Ọ̀rúnmìlà una rata, un pescado, un caracol, una gallina y dinero. Un día, cuando Ọ̀nà Ilédì se llevó la maldición a la boca para echarla sobre la cabeza de Ọ̀rúnmìlà, Ọ̀rúnmìlà reunió la rata, el pescado y el caracol para ofrecer a su cabeza y lo llamó a bendecirlo. Ọ̀nà Ilédì no pudo maldecirlo cara a cara y lo bendijo, diciendo que vencería a sus enemigos; dos días después murió. El enemigo que invoca el mal sobre nuestra cabeza cae en lo que dice."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para que el bien vuelva: una paloma, una tortuga marina, dinero y medicina de Ifá.", "Contra los enemigos: tres cuchillos, tres gallos y dinero.", "Contra la muerte accidental: un chivo, dinero, una olla de aceite de palma y la faja de la cintura.", "Para hijos: una paloma y dinero.", "Para la esposa: un festín con dos gallinas.", "Contra la maldición: una rata, un pescado, un caracol, una gallina y dinero; dar kola al que hace el mal."]}, {"titulo": "Relaciones espirituales", "texto": "Odùduwà, el que hace el bien. Olódùmarè. El doble espiritual en el cielo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tortuga marina, maíz, aceite de palma, obì."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 247.1 (yorùbá): Òfún fún wọn kẹ, / Òfún fún wọn ṣọ: / a dífá fún Odùduà. / Oduduà maa ṣoore kari ayé. / O niki a ṣoore kari ayé / li o daraju ni iwà. / Wọ̀n ni: \"apakan ko nii ṣ'opẹ oore lọwọ rẹ̀, / àwọn miran ko tilẹ niimoo tiwọn i lo\" / O ni: \"Baba ọmg koleṣe / kioma fi ohun rere fún pmọ. / İye (Yeye) omọ ko leṣe / kiomafi ohun rere fún omo\" / Wọn niki o wa rúbọ, / ki ohun rere gbogbo / ti o nfi fún wọn, / bii wọn bafiṣ'ofo li ayé, / kiwon le maa tun pada / to Oduduà lowọ. / Ẹbọ: Ẹyẹlé, ẹwi (awun okun), / egbàájo owó ati ewé Ifá. / Ó gbọ̀ ó rú.", "Verso 247.2 (yorùbá): Òfún fún wọn kẹ, / Òfún fún wọ̀n rín: / a dífá fún Ọlakanmi. / Wọ̀n ni: / \"Edùmarè nmuree bowa\" / Ki a rúbọ ki apa ọ̀tá ma'le ka'ni; / Ki ọ̀tá ma le fi ohun ini-ẹni ṣ'ofo. / Ebọ: Ọbẹ méta, akukọ méta ati egbàáta owó. / Ó gbọ̀ ó rú.", "REZO: AWO KEKERE OFA OPEPEÑI AÑAMI DEDE ADIFAFUN OBATALA UMBATIBINI EYELE LEBO, ORI, EYELE, AKUKO LEBO. MAFEREFUN. ESHU.", "REZO: AWO QUEQUERE OAOPEPEÑI AÑEMI DEDO ADIFAFUN OBATALA UMBATI BINI EYELE LEBO ORI EYELE AKUKO LEBO KAFEREFUN ESHU.", "REZO: ARO ABOWO KONKUO ADIFAFUN ORUNMILA, UMBATI ORUN JUNJUN OKU AWO ILEKE AWORUN YANYYA ONIKU OMOLAYE BI ORUN BATIDE ORUNMILA ILAYI OSA OSIFUN ORUN KOTO LOWA EKUN IPIN , ODILE ORUNMILA OBERE SIWATOLENO U NTELE ADOBORUKU OLOMU YADE BOGBO ILE ORUNMILA OSIFUN ARUN OKAUADA SILE ODI ATEGUN UMBATI DELE OFUN OFUN ONI LODAFUN ORUNMILA.", "REZO: ADIFAFUN ORISHA BABASHE BABANI BABA ASHOKOTO ITO LOINO EFE ONIREO LODEO BABA SAMI SAMI ORISHA ORUN WEO ORUN MINI ORUN MINI ORISHA ORUN OWI LAIYE OSUN WERI OYOFUN MI WOYO FIFANERI OBIRIKITI OBUN KUKUA RUSUYA YOKO OSHA MODE NODE.", "SUYERE: YAKARAMO ERE YAKARAMO ERE ERI LO MINA TOKUERILEO OSHA WOO OOO."]}]$q$::jsonb),
(248,'c97688ccb208259d24f9a8aabb23d945',$q$[{"titulo": "Idea central", "texto": "Òfún Ọ̀bàrà pide proteger los bienes de estafadores, embaucadores y ladrones: la prosperidad puede deteriorarse por culpa de alguien indigno de la confianza recibida. Hay una mujer que planea robar y huir, y alguien ingrato que pide sin cesar. A quien tiene muchos enemigos, Ifá le promete gente de su lado que lo protege y lo enriquece."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["El negocio va bien, pero alguien le pide acceso a sus bienes o su dinero.", "Teme un engaño en una relación (relato del hombre advertido sobre una mujer interesada).", "Debe comprobar intenciones y acuerdos antes de entregar recursos (relato de Olú-Ọta)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Mucha gente que se reúne a protegerlo.", "Que el fuego del destino siga ardiendo alto, aun en la vejez.", "Riqueza que llega en el mes."]}, {"titulo": "Ibi y advertencias", "puntos": ["Una mujer que quiere robar y huir.", "Ser generoso con un ingrato.", "Una pareja hermosa de la que no se puede escapar.", "Seducir a la mujer ajena y perder la casa."]}, {"titulo": "Enseñanza principal", "texto": "Òfún es generoso con un ingrato. Quien se pega a lo que lo atrapa, como la mosca a la liga, muere diciendo que lo ama."}, {"titulo": "Relatos reunidos", "puntos": ["Olú Ọ̀tá, el señor de los enemigos. Olú Ọ̀tá era el que más enemigos tenía en el mundo. Le dijeron que ofreciera cuatro palomas, dinero y medicina de Ifá para que mucha gente se reuniera a su lado a protegerlo, y que por eso se haría rico. Escuchó y ofreció.", "La mujer que quería huir con el dinero. Òfún da a Ọ̀bàrà, Òfún es bondadoso con un ingrato: así adivinaron para un hombre al que le gustaba una mujer que planeaba robarle y abandonarlo. Le pidieron un chivo, aceite de palma, kola y medicina de Ifá. A otro que tenía a un ingrato pidiéndole sus bienes, le pidieron lo mismo para que Èṣù no lo tentara a ceder.", "El fuego, Niño en lo Alto. Es blanco y parpadea adivinó para el Fuego cuando iba a tomar el título de Niño en lo Alto y las cosas no le iban bien. Le pidieron tres gallos, una olla de aceite de palma y dinero. Ofreció, y cuando el fuego está por apagarse, si se le echa aceite de palma, se pone a bailar hacia arriba. Al hombre al que el dios del cielo dará su destino, aunque ya sea casi viejo, el fuego de su destino seguirá bailando alto.", "La mosca y la liga. En el monte espeso se arranca el bejuco: así adivinaron para la Mosca cuando iba a casarse con la Liga. Le advirtieron que ella no se divorciaría ni la dejaría en paz, y le pidieron tres gallos y dinero. La mosca dijo que se casaría de todos modos. El día de la boda la tocó con la mano y la liga la agarró; la tocó con el pie y la agarró; giró la cabeza contra ella y quedó pegada del todo. Entonces empezó a decir: te-e-e a-a-amo, hasta morir en la liga. Por eso la mosca zumba así y queda pegada.", "Ọ̀rúnmìlà carga solo su calabaza. La luna nueva aparece clara y no aparece clara: así adivinaron para Ọ̀rúnmìlà cuando era tan pobre que cargaba solo su calabaza de kola y su plato de pimienta. Le pidieron cuatro palomas, dinero, dos caracoles y frijoles blancos cocidos para que el dios del cielo le pusiera en las manos la calabaza del destino ese mes. Ofreció, le llegó el dinero, tuvo sirvientes, y decía: me iban a empeñar este mes; los mayores no se empeñan y aún tienen tiempo de servir a su Ifá.", "El señor del río y la esposa de Kéṣó. El señor del río, padre de los peces, iba a seducir a la esposa de Kéṣó. Le pidieron una chiva, una tinaja de manteca, doscientos caracoles y dinero para que su casa no fuera destruida por ella. No ofreció y se la llevó. A los dos meses Ìgún vino a saludar a Kéṣó, que le pidió pelar el ñame para el mortero. Ìgún preguntó: ¿dónde está tu esposa? Kéṣó dijo que el señor del río se la había quitado. Ìgún fue a llamar a Àìdan y a la pimienta wẹ̀rẹ̀, y atacaron la casa del señor del río: mataron a los peces grandes, a los pequeños y a todos sus hijos. Desde entonces se usan ìgún, àìdan, kéṣó y esa pimienta para envenenar a los peces del río. Quien quiere seducir a una mujer ajena debe cuidarse: la gente que está detrás del marido destruirá su casa."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para tener gente de su lado: cuatro palomas, dinero y medicina de Ifá.", "Contra la estafa: un chivo, aceite de palma, kola y medicina de Ifá.", "Para el fuego del destino: tres gallos, una olla de aceite de palma y dinero.", "Contra la pareja que atrapa: tres gallos y dinero.", "Para el dinero: cuatro palomas, dinero, dos caracoles y frijoles blancos cocidos.", "Contra el castigo por seducir: una chiva, una tinaja de manteca, doscientos caracoles y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù tienta o protege según la ofrenda. Ọ̀rúnmìlà. El señor del río."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ìgún (Tephrosia vogelii), àìdan (Tetrapleura tetraptera), kéṣó, pimienta, aceite de palma, kola, liga."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 248.1 (yorùbá): Òfún'Bàrà: / a dífá f'Olú-Ọta. / A niki Olu-Ọta wa rubọ / nitori àwọn abinú-ẹni, / nitoripe Olú-Ọta a maa r'ẹni / wa ra lowọ òun, / Olú-Ọta a maa ta, / a maa ri owó gba wàrà. / Eyẹlé mérin, ẹgbàá méjilélógún owó ati ewé Ifá. / Ó gbọ̀ ó rú.", "Verso 248.2 (yorùbá): Òfún nfún Ọ̀bàrà, / Òfún nṣoore f'Ẹyejenifol0419; / a difá f'okunrin kan, / wọ̀n ni obirin kan tiowuu / maa ko owó rẹ̀ lọ, / ki ó rúbọ: / Obúko, epo, obi ati ewé Ifá.", "Verso 248.3 (yorùbá): Òfún nfún'Bàrà: / a difá f'okunrin kan / enikan ntọrọ ohun qwọ̀ rẹ̀, / Eyejenifolo ni o. / Kiowa rubo: / Öbúką, epo, obi ati ewé lfa, / ki Èṣú ma ba ti o fún un.", "REZO: OFUN BARA OFUN SUSU OLOREMI OBARA SUN SUN OROSALE ADIFA- FUN ARIBITO. TONLOFE OYA LOBINI EURE LEBO. AKUKO, OWUNKO, EYELE LEBO.", "MAFEREFUN OLOFIN.", "REZO: OFUN BARA IFA OFUN SUN SUN ORERE OBARA SUN SUN OLOSA LEORDE ADIFAFUN ARIBI AUN TUKUTU OFE OYA LOBINI OYA LOTAN LOROLO TARIASHO AWO OBINI KANLOFE KOMAKU SIOLOGU.", "REZO: OFUN BARA IFA OFUN SUN SUN ORERE OBARA SUN SUN OLOS LEOR- DE, ADIFAFUN ARIBI OUN TUKUTU OFE OYA LOBINI OYA LOTAN LORELO TARI ASHO AWO OBINI KANA LOFE KOMAKU SIOLOGU.", "REZO: OFUN BARA TETE UMBALE ALAGOGO OBA KUERUN AIKU BEMINA ORUN AIRE KISHERUN ORORE OPA UN AWO LAKUETUN ADIFAFUN OWO OLODUNYERE EYELE ILOLE IFA ODDUN BABA AGBA AKUKO OSUN AGBA EYE MALE BABA ODEWA ADELEKUTA OFUN BAKE ORUNMILA AMU ISHU ADAFUN ORUNMILA OBARA NALARI OWO OMO ARA ORENIWA ORUNMILA ONIYE ORIYA EWE LORDAFUN OSUN IFANI KAFEREFUN ORUNMILA.", "REZO: OFUN SUSU OLAREMI OBARA SUSU OLASEYE, ADIFAFUN ARBITO ESHISHI BANI OLOLOFO OLOYA LUBINI AWADO NIÑA, ADIFAFUN OLOFIN BAYIN ERUN, ATEBAYI, KOKORIKO", "IFA NI KAFEREFUN ORUNMILA. REZO: OFUN SUSU OLOREMI OBARA SUNSUN OROSAILE, ADIFAFUN ARIBITO TONLOFE OYA LOBINI EURE LEBO, AKUKO LEBO MAFEREFUN.", "REZO: OFUN BARA IFA OFUN SUSU ORERE, OBARA SUSU OLOSA LORDEO ADIFAFUN ARIBINU TOKUTOO OFE AYA LOBINI OYA LOTEN LORO LOTERI ASHO AWO OBINI KANLOFE KOMAKU SIOLOGU.", "REZO: ESHISHI DINDIN ONI AGBE YAGBAIBANSANIN FAKUN, ADIFAFUN ESHISHI OFUN BARA SUSU OYO TOMAAGBE ATENI- YEWO. ATEMOSAIN, ES NI KOMIKO KOSINIKO ONI ALAFIA ESHISHI ONIKO BURO BURO, OYEFE BENI OYO OFE ATEMOSIN UMBATI ONIKIO FO YOKAN ATEMU OZAIN BI OBA ENIKI OBI ESEKANATEMU ESHISHI FORI YI ATE KITIKITI ONIGBA MANI ESHISHI BERE SIWIKUE BAYI NI ESHISHI WITITI OFIKU OSI OYU ATE OBINI ODARA KI BATIMA IKU OSI ORI ATEMU OZAIN.", "REZO: OLILE OSHUKUA OMO ONI DEDERETE ADIFAFUN AWO ORI BALAYE OFUN BARA ONIKAMU IGBA OBI KOLA ONKANMU IGBA ATARE WERE OSHU TOMALE YINI OLORUN IGBA ORI IWA OWO BADESI OLUWO ODDE AIYE YORI OLUWARE OSHA OLUWO.", "SUYERE MATA MATAR LAS EYELE A OSHUKUA: \"ASHO PA AWA NI ASHO PA AWANIYO ASHO PA EDUN AWAO ASHO PA AWA NI OMI UNYEN EYELE EYE EYIWE EYEWESE EDU ENI OMO MI.\" 384", "REZO: OFUN BARA TETE UMBALE ALAGOGO MOBA KUERUN AIKU BEMIÑA ORUN A IREKISERUN ORORE OPAGUN AWO LAKETUN ADIFAFUN OMO OLODUNYERE EYELE ELOLE IFA ODUN BABA AKUKO, OSUN AGBA EYA MALE BABA ODEWA ADELEKUTA OFUN BAKE ORUNMILA WAMU ISHU AKAFUN ORUNMILA WAOBARA NARELI OWO OMO ARA ARENIWA ORUNMILA ENIYE ORIYA EWE LODAFUN OLOFIN LODAFUN OSUN IFA MI KAFEREFUN ORUN- MILA."]}]$q$::jsonb),
(249,'2dca883e152d6063fda5087f397ec8ce',$q$[{"titulo": "Idea central", "texto": "Òfún Ọ̀kànràn advierte contra el abuso de la fuerza y del poder: al consultante se le está subiendo la cabeza. Olódùmarè defiende a los débiles de los poderosos. Promete sobrevivir a quienes hacen hechizos en su contra y salir rico de un pleito."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Alguien con autoridad se está dejando llevar por el orgullo.", "Se siente perjudicado por quienes tienen más poder o dinero (relato del sufrimiento causado por reyes y ricos).", "Un puesto nuevo exige escuchar a quienes sufrirán sus decisiones.", "Puede venir un cambio físico, emocional o espiritual, y hay que confirmar cuál."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que Olódùmarè lo defienda si es débil.", "Sobrevivir a los que le hacen hechizos.", "Un hijo que llega a jefe.", "Salir rico de un caso judicial."]}, {"titulo": "Ibi y advertencias", "puntos": ["Abusar del poder y oprimir al débil.", "Ser tomado por ladrón.", "Perder el título en pocos meses."]}, {"titulo": "Enseñanza principal", "texto": "El que oprime al débil tiene a Olódùmarè en contra. La campana sin badajo no responde al llamado de Òrìṣàálá."}, {"titulo": "Relatos reunidos", "puntos": ["Olódùmarè defiende a los débiles. Cuando Olódùmarè preparaba gente para mandar a la tierra, sufría por el castigo que los poderosos, reyes, jefes y ricos, daban a los pobres, y por los inocentes que morían sin poder defenderse. Quiso protegerlos. Le pidieron una tortuga, un cuchillo, una flecha, un arco, pimienta y dinero, para poder dejarlos libres en la tierra. Ofreció.", "Ọ̀rúnmìlà y el llamado de la muerte. El leopardo que busca pelea sale a caminar al mediodía: así adivinaron para Ọ̀rúnmìlà el día en que mandaron a la muerte a llamarlo al cielo. Él respondió: no me encuentro con el dios del cielo cuando salgo a caminar; el gong que suena no mira al dios blanco; no respondo al llamado del dios del cielo; la campana sin badajo no responde al llamado de Òrìṣàálá. Todos le hacen ofrendas y hechizos en contra, en vano: él vivirá para verlos morir.", "La Corona Monta el Título. Es muy blanco adivinó para La Corona Monta el Título, hijo de Ọ̀ràngún de Ìlá, que es el nombre de la trompeta de marfil. Le dijeron que no perecería en su mundo. Un anciano se casará con una anciana de quien todos creen que ya no puede tener hijos; ella vivirá para ver al hijo hecho jefe, con trompetas y mitra. Todos se burlan del hombre porque no tiene ni calabaza ni plato.", "El que fue a la corte y encontró cuentas. Abierto para que todos vean: Ifá es el que hace las cosas que podemos ver. Así adivinaron para Ven a casa del forastero, y le pidieron cuatro palomas y dinero por un caso que le harían en la corte y por el que se haría rico. Ofreció; lo llamaron a la corte, y cuando se arrodilló a exponer su caso, se hundió en un pozo de cuentas. El rey le dijo que las tomara, porque nadie más las había hallado allí. Decía: no sabía que el Elefante me llamaba para hacerme un regalo.", "El ratón y los frijoles del dios blanco. Ifá adivinó para las ciento sesenta y cinco clases de ratas el día en que el Ratón iba a robarse los frijoles fermentados del dios blanco, y les pidió un gallo y dinero a cada una. Todas ofrecieron menos el Ratón. Faltaron los frijoles, y el dios blanco puso una trampa y mandó a todas las ratas pasar sobre ella cantando: si ayer robé los frijoles, que la trampa me atrape; si no los robé, que no. Pasaron todas y la trampa no atrapó a ninguna, hasta que pasó el Ratón y la trampa lo agarró. Lo soltaron y huyó al monte; desde entonces el ratón no se junta con las ratas y vive en las casas. Hay que ofrendar para no ser tomado por ladrón."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para defender al débil: una tortuga, un cuchillo, una flecha, un arco, pimienta y dinero.", "Para el hijo jefe: dinero y la faja de la cintura.", "Para el pleito: cuatro palomas y dinero.", "Para no ser tomado por ladrón: un gallo y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè, defensor de los débiles. Òrìṣàálá, el dios blanco. Ọ̀ràngún de Ìlá."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tortuga, pimienta, frijoles fermentados (ìrú), trompeta de marfil."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 249.1 (yorùbá): Òfún'Kọ̀nràn!: / a dífá f'Olódùmarè / nigbi Olódùmarè maa ran èniyàn / wa s'ode ayé. / Wọn ni: / Olódùmarè nro ti iya ti àwọn alagbára / maafi maajẹ àwon alailagbára, / iya ti Ọba ati ljoye ati àwọn Olówó / yoo fi maa jẹ àwon olupónjú. / Orí àwọn Koṣẹkoro / ti wòn npa l'aye / ti wọ̀n nfi'ya jẹ: / ki ohun le maajà fún wọn, / àwọn ti aráyé nṣe ni'kà / tikoletikarawon san fún àwọn otá wọn. / A niki Olódumarè rúbọ: / Ọbahun, obẹ, ofà, akatampo, / ata ati egbàásan owó. / A niki o da wọ̀n silẹ l'ode ayé. / Ó gbọ̀ ó rú."]}]$q$::jsonb),
(250,'b2c9fa239bb1cc48decc34dc45b13a55',$q$[{"titulo": "Idea central", "texto": "Òfún Ògúndá habla de las consecuencias de ignorar la ofrenda y de llevar una conducta indigna. El consultante está metido, o quiere estarlo, en una relación que puede destruirlo. Es también el Odù de 'pérdida y luego riqueza': quien ha perdido mucho verá llenarse de nuevo sus manos. Sus versos se recitan con respeto, probando antes aceite de palma."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa en una relación que podría cambiar sus decisiones y afectar a otros.", "Un cargo o un éxito lo hace sentir por encima de las consecuencias (relato del rey Onibara).", "Va a colaborar con alguien que no conoce bien y conviene evaluarlo con cuidado."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que las pérdidas pasadas se vuelvan riqueza.", "Dinero, esposas e hijos.", "Que la palabra se cumpla.", "Sentarse en paz en la propia casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Una relación con alguien que trae la ruina.", "Hábitos ocultos que destruyen.", "Presumir de lo que no se puede mostrar.", "Parientes que minan el asiento propio."]}, {"titulo": "Enseñanza principal", "texto": "El leopardo, a pesar de su crueldad, pide que no se le deje la cara descubierta. Lo que se gana sin sufrir no deja marca: el que se enriquece en el comercio lleva las cicatrices en el cuerpo."}, {"titulo": "Relatos reunidos", "puntos": ["Oníbàrà y la mujer que solo comía carne. Luna Radiante adivinó para Oníbàrà, rey de Ìbàrà, y le pidió un carnero y dinero para evitar problemas con una mujer de la calle. El rey preguntó qué problema podía tener con una mujer así, siendo rey de una nación. Ese año llegó de tierra extraña una mujer muy hermosa para casarse con él; la gente le advirtió quién era, pero él, cautivado por su belleza, no hizo caso. Ella dijo que solo comería carne, y el rey empezó a matar todas las aves, ovejas y chivas del reino, poniendo trampas en el palacio; cuando los dueños las reclamaban, decía que llamaban ladrón a su rey. Cuando se acabaron, consiguió una medicina para volverse leopardo y, despidiendo a los guardias, cazaba de noche los animales del pueblo. Los cazadores le dispararon una flecha, y el leopardo cayó frente a la casa de Oníbàrà bajo la luna radiante. Al amanecer encontraron al rey en la piel del leopardo, con sus cuchillos y el animal de esa noche. Lo enterraron en secreto, mataron a la mujer y la enterraron con él. Desde entonces, cuando se mata un leopardo, se le cubre la cara y se lleva a un lugar secreto antes de quitarle la piel, y al leopardo se le llama rey.", "Los Òrìṣà del tambor ìgbìn y los del patio. Para saber si un niño es valiente para recitar Ifá se usa Òfún Ẹ̀kọ: así adivinaron para los cuatrocientos Òrìṣà de la derecha y los doscientos de la izquierda, y les pidieron una rata, un pescado, un caracol, kola y dinero para que su palabra se cumpliera. Los que ofrecieron son los Òrìṣà a quienes se toca el tambor ìgbìn hasta hoy; los que no, son los Òrìṣà del patio trasero.", "Pérdida y luego riqueza. El barro tiene el pecho blando: así adivinaron para Ọ̀rúnmìlà, que había sufrido pérdidas por todos lados desde siempre. Le pidieron una rata, un pescado, un caracol, una gallina y dinero. Puso las cabezas de la rata, el pescado y la gallina y las antenas del caracol en el suelo; al amanecer las hormigas cubrieron la ofrenda, y al barrerlas se hundió en un pozo de cuentas de la diosa del mar. Cuando vinieron a consolarlo por sus gastos, respondió que lo perdido no igualaba lo ganado. Desde entonces se llama a este Odù Pérdida y luego Riqueza.", "Dinero, esposas e hijos. Òfún prueba el aceite de palma adivinó para el rey de Àrà, que ofreció dos palomas y dinero y recibió la bendición del dinero, con la hoja blanca que parece caracoles. Echar sin probar aceite, adivino de Ajerò, adivinó para Ajerò, que ofreció dos gallinas y dinero y empezó a tener esposas, con la hoja pegajosa. Y para Olóṣòṣà le pidieron un gallinero lleno de gallos para tener hijo tras hijo, como la planta ṣẹ̀ṣẹ̀kí.", "Ọ̀rúnmìlà y la hoja 'déjame sentarme'. Ọ̀rúnmìlà iba a mudarse cerca de la casa de su padre. Un pariente le minaba el asiento y no lo dejaba descansar. Le pidieron un chivo y dinero; se cava un hoyo, se pone la cabeza del chivo, se cubre con hojas de 'déjame sentarme' y luego con tierra.", "La oveja que hablaba. Lọ́gun Ìràngàn, que es Lọ̀wá Ìjarúwà, jefe de los jefes del palacio de Ifẹ̀, tenía una oveja que hablaba como persona. Le pidieron ofrendar para que la presunción no lo deshonrara, y ofreció. El Ọọ̀ni lo mandó llamar: si la oveja hablaba el día del mercado, le daría la mitad de sus bienes; si no, lo colgaría sobre el fuego. Ese día Lọ̀wá le habló y le habló a la oveja, que no respondió; lo ataron y lo pasaron sobre el fuego. A la tercera vez la oveja dijo: ¡ah, ah! ¿lo están quemando? La gente gritó que la oveja hablaba, y el Ọọ̀ni le dio la mitad de todo. De regreso, Lọ̀wá le preguntó por qué había dejado que lo pasaran tres veces por el fuego, y la oveja contestó: si te hubiera respondido a la primera, ¿habrías ganado todo eso sin sufrir? El que se enriquece en el comercio lleva las cicatrices en el cuerpo.", "La tortuga en el granero. Los ciento sesenta y cinco animales pretendían a Ládúntán, hija de la diosa del mar, que dijo que daría a su hija al que hiciera hablar a su granero. La tortuga dijo que lo haría, ofreció dos gallos, aceite de palma, dinero y un pan de ñame, y antes del amanecer se metió en el granero. Cuando la diosa llamó: ¡granero!, la tortuga respondió desde adentro que entregaran la muchacha a Ọ̀rúnmìlà. Así se la dieron. Un amigo guardará el secreto para que uno pueda casarse con la mujer que quiere."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra la mujer que arruina: un carnero y dinero.", "Para que la palabra se cumpla: una rata, un pescado, un caracol, kola y dinero.", "Para recuperar lo perdido: una rata, un pescado, un caracol, una gallina y dinero.", "Para el dinero: dos palomas y dinero; para esposas: dos gallinas y dinero; para hijos: un gallinero de gallos y dinero.", "Para sentarse en paz: un chivo y dinero, con la cabeza enterrada bajo hojas de 'déjame sentarme'.", "Para la pareja deseada: una chiva, dinero y una tela negra; dos gallos, aceite de palma, dinero y un pan de ñame.", "Antes de recitar sus versos: probar aceite de palma."]}, {"titulo": "Relaciones espirituales", "texto": "Los Òrìṣà blancos del tambor ìgbìn y los del patio trasero. La diosa del mar y sus cuentas. El Ọọ̀ni de Ifẹ̀."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hoja 'déjame sentarme' (ìjòkó), ẹ̀fúnlẹ̀ (Evolvulus alsinoides), ṣẹ̀ṣẹ̀kí, aceite de palma, kola, cuentas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 250.1 (yorùbá): Oṣupajerejere awo Onibara: / a difá fún Onibara, / Wọ̀n niki ó rú: / Agbo kan ati ogbokànlá owó / ki àgbéré obirin ma koo s'ọ̀ràn. / Onibara kọ ko rúbọ. / Ó ni: / \"Ọ̀ràn kini obirin kanṣoṣo / le ko òun odidi Oba ilú si?\"", "REZO: OFUN FUNDA IFA TINSHOMO INKIN UNSORO GBOGBO KALENO OSHA (ORISHA) UMPE GBILO TIYE JEBIOSO OKUTA EDUN ARA OKP AFAFA OKOJI AFAFA OLE TOKOSI OKPELE IFA ADIFAFUN AFAFA MAFEREFUN IFA DE.", "REZO: ESHU MODUBELA OYU TODE OLOGUE KORO KUKUTE KUKU MARIWO LORO AKUKO LEBO, ETU, YARAKO, OBE LEBO.", "REZO: OFUN FUNDA MADAME ISISI AYI TODE AYI TOLE ADIFAFUN ASHI KUELU AWO EBANA ORUGBO ETU, ADO, AIKORDIE, ORI, EFUN, EYELE.", "SUYERE: EWE MILERE ALABU. EWE MILERE OMO OSHUN ARIBATANA MOSUN.", "REZO: AYANAKU AGBA LETI FOUNDE, ATI NA FOUNDE KUELU NA AGBA BERUN OMO MI ELESEKAN BOGBO TENUYEN LEBO.", "REZO: ADIFAFUN OGBANUREGUN BABA ONIREGUN KONISHE APA KONISHE LESE OKUNI MODUN MODUN ERI OMA IBIDAUN IJINLE SHUN ENU IFA SHANGO OKUNTAN IYI MEYI ILE GONFA AWO BOGBO ORUMALE OKUTA LODAFUN ORUNMILA.", "REZO: ATI ARARAYAN NI BELEGUN NIKETE BOGBO NO ISHIN, TIMBE", "ATI UNYEN BOGBO IRANLEWI LENI OROKO NI OLUWA.", "REZO : IFA TINSHOMO ABASUKA UNSERE BOGO KALOMU ERISHA UAPO- TIYA HEVIOSO EKUTE EDUN ARAEKPA AFAPA ELO TOKLESI IFA ADIFAFUN ORUNMILA KAFEREFUN IFA ADO."]}]$q$::jsonb),
(251,'aee5848e4e5df807ddeb960df90c12c6',$q$[{"titulo": "Idea central", "texto": "Òfún Ọ̀sá habla de una vida que se pone patas arriba y cuya única salida es la redención espiritual. Aunque todo parezca bien, el desastre está adelante. Es el Odù en que Ifẹ̀, rota como una calabaza, se restaura con la hoja que reforma el carácter. Pide no hacer promesas vacías y ofrendar para que la bendición no se frustre."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su vida parece en orden por fuera, pero tiene problemas sin resolver.", "Su familia o su comunidad está desorganizada (relato de los ancianos de Ifẹ̀).", "Quiere reparar daños del pasado.", "Busca mantener el bienestar que ya logró aunque cambien las condiciones (relato del jardín junto al agua)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Restauración después de la ruina.", "Una vida fácil que también facilita la de los suyos.", "Medicinas que funcionan.", "Una bendición que dura por generaciones."]}, {"titulo": "Ibi y advertencias", "puntos": ["El caos que viene aunque todo parezca en orden.", "Prometer lo que no se puede cumplir.", "Llamar mentirosos a los adivinos."]}, {"titulo": "Enseñanza principal", "texto": "Si el mundo se pudre en nuestro tiempo, es porque ya no sabemos comportarnos. Ni los poderosos ni los sabios restauran lo roto sin la reforma del carácter."}, {"titulo": "Relatos reunidos", "puntos": ["La calabaza rota de Ifẹ̀. La tierra se salió de su eje y se partió en pedazos desde el corazón; si el mundo se pudre en nuestro tiempo, es porque ya no sabemos comportarnos. Así adivinaron para los ancianos de Ifẹ̀ cuando su dominio estaba como una calabaza rota. Llamaron a Ọlọ́ta de Àdó, a Erinmi de Ọ̀wọ̀, a Ògún de Ìrè, a Ọbàlùfọ̀n, a Lábẹ́rinjọ, a Jígúnrẹ̀, a Èṣẹ̀gbà, a Aṣẹ̀dá y a Akódá; todos vinieron y fracasaron. Los hombres se volvieron como árboles secos, la lluvia no caía, llegó el hambre y morían hombres y animales. Llamaron también a Olúmọ, al sacerdote del Alárá, al del monte de Ìjerò y al jefe de Kétu, y fueron impotentes. Entonces les dijeron que buscaran a Ọ̀tọ̀tọ̀ Ènìyàn, el hombre perfecto, para que tocara la trompeta y llamara a Alájogun, capitán de los ejércitos del cielo, y así viniera el Señor Àjàlórun, el niño nacido en la colina de Ìtaṣẹ́, donde nace el alba. Él se negó una y otra vez, hasta que le dijeron: la ardilla anuncia a la boa, el sapo anuncia a la víbora, el àlùkò anuncia a la diosa del río, y tú, desde el amanecer de los días, siempre has llamado a Alájogun. Entonces tocó la trompeta. Bajaron los grandes del cielo; el pánico agarró a todos; los elefantes corrieron a la selva, los búfalos huyeron, los animales del agua al mar, los perros a la tierra de los perros, los humanos a sus casas, y hubo confusión: unos entraron en casas ajenas, otros erraron el camino, las ropas se hicieron trizas. El más anciano dijo: el caos ha tomado posición; hay que remendar; tú estás incompleto, yo estoy incompleto, hasta los días del mes lunar están incompletos. El Señor de la sabiduría dijo que Ifẹ̀ solo se curaría si se encontraba la hoja Aláṣùwàlù, la que reforma el carácter. Le llevaron una hoja y otra, y dijo: no es esta. Por compasión les dijo: confiesen sus maldades y yo cubriré su desnudez. Ellos confesaron, y él metió la mano en el saco de la sabiduría primera y sacó la hoja Aláṣùwàlù. Bailaron y cantaron: hemos recibido la hoja Aláṣùwàlù; el niño de la cabeza coronada nos ha dado el buen carácter. Ese día llovió, Ifẹ̀ se renovó y la calabaza agrietada quedó restaurada.", "Àgànná, el que detenía la lluvia. Es muy blanco, el que sabe barrer no barre el cielo con escoba: así adivinaron para Àgànná, ayudante del que impide la lluvia en Ọ̀yọ́. Le dijeron que el dios del cielo le daría una bendición que duraría para él y sus nietos, y que ofreciera dos palomas, dos pollos y dinero para que la gente de la tierra no la frustrara. Dijo que los adivinos mentían. Cada año, cuando el rey de Ọ̀yọ́ salía a su fiesta, la lluvia no lo dejaba salir. El rey le prometió a Àgànná una joven, una tinaja de cuentas, veinte telas, dinero, veinte túnicas y un corral de vacas si no llovía hasta el mercado de la tarde, y él prometió que no llovería. Cuando el rey se sentó en todo su esplendor sobre sus telas extendidas, empezó a llover, y Àgànná huyó al monte sin poder llevarse nada.", "El huerto junto al agua. Pérdida, el adivino del Día y de la Piedra de moler, y Cuando llueve no se olvida del huerto junto al agua, adivinaron para Madre El que lo tiene fácil siempre lo tiene fácil, que es el huerto junto al agua. Le dijeron que ni la lluvia ni la sequía serían duras para él, y que lo que fuera fácil para él lo sería también para sus compañeros. Ofreció cuatro caracoles, cuatro palomas, una olla de aceite de palma y dinero, y desde entonces nunca se seca. Cantaba: la hierba àìràn es la soga de las coronas, la soga de los reyes.", "Las hojas que sirven de medicina. Òfún aplica medicina y mira si funciona: así adivinaron para las ciento sesenta y cinco clases de hojas, y les pidieron un gallo, una navaja y dinero a cada una para que la presunción no las deshonrara. Las que ofrecieron son las hojas con las que se hace medicina que funciona, de las que se dice: esta hoja sí sirve."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la restauración: confesar las faltas y buscar la reforma del carácter.", "Para que la bendición no se frustre: dos palomas, dos pollos y dinero.", "Para una vida fácil: cuatro caracoles, cuatro palomas, una olla de aceite de palma y dinero.", "Para que la medicina funcione: un gallo, una navaja y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Àjàlórun, el niño de la colina de Ìtaṣẹ́. Alájogun, capitán de los ejércitos del cielo. Ọ̀tọ̀tọ̀ Ènìyàn, el hombre perfecto. Ògún, Ọbàlùfọ̀n, Akódá y Aṣẹ̀dá. El rey de Ọ̀yọ́."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hoja Aláṣùwàlù, hierba àìràn, navaja, aceite de palma, caracoles."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 251.1 (yorùbá): Otooro ayé ja, / Ọgbaara ayé la kan'lẹ. / Bi ayé bati owọ ẹni bajẹ, / Aimowaahu wa ni: / a daa fún wọ̀n ni Agbayi gbo Ifè, / nigba ayé lfẹ sọ bi igbá. / A ranṣẹ pe Ọlota nile Ado, / ko ba'ni tún ayé lfè sọ bi igbá, / O de kole ṣe e. / A niki a ranṣẹ pe Erinmi lode Qwọ, / kowa ba'nitún ayé lfè sọ bi igbá; / O de ko le ṣee. / Beẹni Ado ni'le ltá, / pwọ si ni ilé Etu. / Aranṣẹ pe Ògún lode Ire / kiowa ba'ni tún ayé Ifẹ̀ sọ bi igbá. / O de ṣùgbón ko le ṣee. / Eniyàn gbẹ si iduro, ojo ko rọ; / Ebi de, èniyàn ati eranko nṣofo. / A ni: / tani yoo ba'ni tún ayé lfẹ̀ so bi igbá? / Wọ̀n ni: / o kù Ọbalufon lode lyindẹ, / Lábérinjo lode Ido, / Jigúnrè lode Ọ̀tunmobà, / Eṣegba awo Egbá: / tioko wọn los'igbó Egbá. / Aṣada awo òde ljèṣà / Akoda ni'le lfẹ / Aṣèdá Aràbà baba wọ̀n nile lfẹ̀, / ki wọ̀n wa'ba ni tún ayé Ifẹ̀ sọ bi igbá. / Gbogbowon ṣee wọ̀n ṣee ti, / wọ̀n ko le tún ayé Ifẹ̀ sọ bi igbá.", "Verso 251.2 (yorùbá): Eyelé moro Eselu, / İgbín mọ jọ Apako: / wọ̀n da fún wọ̀n l'agbayigbo Ifẹ̀, / nigba ayé lfe fọ bi igbá, / wọ́n ṣe ti-wọ́n / ko le tún ayé lfẹ̀ sọ bi igbá. / A ranṣe pe Olúmo / Awo Ode Imori ni Ìjèṣà, / Ogún awo òdé Alárá, / Ọgbón Enitaara awo oke ljerò, / Odudugbunudu awo Ẹṣemowe. / Ọboleboggun ba-b won ni Kétu. / àwọn naa ṣee wọ̀n ṣee ti; / wọn ko le tún ayé lfẹ̀ sọ bi igbá. / A tun ranṣẹ pe Akonilogbón, / A bẹ'wẹ pe Afonàhan'ni kiwọn / wa ba ni tún ayé lfẹ̀ sọ bi igba, / Akonilogbọ̀n oun Af'onahan'ni de; / wọn niki a ranṣẹ pe Ọtoto-èniyàn / tiiṣe awo fún wọn lode Arufin: / ki Ọtọto-èniyàn wa fún ipe si Alájogun, / kiolo pe Ọlọ̀fín Olúwa mi Ajàláyé, / kiosipe Olúwa mi Ajàlorun / ati Olúwa mi Agiri-ilógbọ̀n, / Ọmọ tiabi loko Itaṣẹ. / nibi ojú tiimo wa'yé. / Afi oun nikan l'o le tún Ayé Ifẹ̀ / so bi igbá. / Ọtpto-èniyàn de, / o ni kinni a pe oun, si? / A ni a pe iwo Ọtoto-eniyan / kiowa fun ipe Olú fun. / Ọtọto-èniyàn kọ, o ni oun kofun'pe. / Wọ̀n ni: / Ṣe okérẹ̀ niifun'pe f'óká, / O ni: / emi kofunpe Konko niifun'pe fun eere. / O ni: / emi ko gba ipe. / Agbe niifun'pe fun Olókun, / Àlùkò niifun'pe fun Ọlọ̀sà, / Oloburo ni kan niifun'pe fun Eniorun. / A ni iwo Ọtoto-èniyàn / niitii fun'pe si Alájogun.", "Verso 251.3 (yorùbá): Nigbati Ọtọto-Èniyàn wa gba ipe fun, / ni erin ya wọ̀n los'igbó Eselu, / Ffon ya, wọ̀n losi ẹlujü apako. / Eyẹ bekeke yalos'ale. / Eku wẹwẹwẹ yalo si itẹ wọn. / Awọn aro gidigba ẹwẹ, / Wọ̀n yalo silẹ odò-omi. / Ajá yalo silu llajá, / Àgutàn yalo silu llágùtàn. / Gbogbo eranko yalo si'ilü eranką. / Eniyàn yalo si llẹ̀niyàn. / Nijonaa ni a ṣi ilé ya, / a ṣi'na ya. / Odidẹ firifiri si'le egun ya, / Aṣo gbogbo ya karakara, / Baba ni o di ayanu, / Mo ni o di ayanu, / O ni o di Ọràn abulẹ. / Mo ni o di òràn abulẹ. / Emi abulẹ, / iwọ abulẹ ti ko jeki ojo oṣu ko pe.", "Verso 251.4 (yorùbá): A daa fún Ọlófin-Ajàláyé, / A daa fún Ọlófin-Ajàlọ̀run, / Ati Olúwa mi Agiri-ilógbọ̀n, / Ọmọ tiabi loke Taṣẹ / nibi ojú ti mọ wa'ye. / O ni bikosepe a r'ewé Alaṣuwalu, / kialo wa ewé Alaṣuwalu wa. / A mu eyi wa. / O ni kiiṣe oun a mu t'ghun / wa o ni kiiṣe òun. / O niki ẹ jéwọ̀ obùn kỉ'mi da'ṣọ bo yin. / A ni a jéwó ọ̀bùn. / Olúwa dáṣo bo wa. / O ti ọwọ́ bọ apo Egede’, / o mu ewé Alaṣuwalu wa, / gbogbo wa njó a nyo. / A nkorin: / \"Mo gb'ewé Alaṣuwalu, / Alade ṣu'wa lem'owọ̀ rigidi. / A gb'ewé Alaṣuwalu, / Alade ṣu'wa lem'owọ̀ rigidi\". / Ni jọ naa l'ojo rẹ / ti o tún ayé lfẹ̀ sọ bi igbá.", "REZO : OFUN SA ALE NISHE OMO IKU OYIHA OMO ORUNMILA ALE OYINA LOLE OSOWURUN OYINA LORUBO. AWO FUN FUN ILE OZAIN, EKU, EYA, OWO LAMEFA ELEBO.", "REZO: OFUN SA OMO IFA OMOLORUN OMO IRE BARABANIREGUN JEKUA AYEBI OLERE OLORUN OMO ORUNMILA KONI KAYEFUN ODORUN YORE OFUN SA SAYE RENI ADIFAFUN OSHANLA OYE ISHUMIN EBBO ADA TELEBO OYERI SHEWERE KUEKUE.", "SUYERE: OSA OKUYENE OBA WE. OSA OKUYERE OBA WE. OZAIN MOWA ” OKU YAWA”.", "REZO: IKU OLUO OZAIN OBA OBUO OGUNDE DICE MATE ITU ASHE OGGUN KOMUWA MATE ILU OSHA OGGUN OBA OLEBE OLUNI ITU KOFISHE OGGUN LEHSE OGGUN LEFIESHE OGGUN OBA KODA OZAIN KENADE OGGUN OFUN LEWE PUABUELO.", "REZO: OFUN SA ALETE OMA IKU GUIÑA OMA ORUNMILA LORUBO.", "REZO: OFUN SA EYALEKUN AWEMUDA ACHELAYU ASHELETI SOFO FALA OBO OBINI SARE COMO OZAIN KUNA OZAIN IFAMELE KAFERE- FUN ORUNMILA.", "OFUN KA", "REZO: OFUN KAMALA, AINALA, NIFE TANLO KAKOMALA, ONI BABALAWO TOSA TOMALA AINALA ONI OBATALA IFA OBATALA MAFEREFUN INTORI OFO, ADIFAFUN OBITASA ADIFAFUN BABALU AYE.", "REZO ARARA: FUK JOZI MONO KUEGBE EFUSHE KAYEGBO.", "REZO: AWO OLUWO AFEMI SHAWO OLU ODO AKO NIYAN MABA MONSHAWO INU OTA ORUNMILA MONSHAWO META ETU MEYO ELEBO, AKUKO, EYELE LEBO.", "REZO: OFUN KAMALA MAFUN WARAYENI MAFUN IKA NI OFUN KAMALA NIFE SOTINA NI MORO SHANGO JEKUA AZOJUANO LAYERE INLE OWO OBODE OFUN KAMALARAEIFE.", "INSHE AZOJUANO ASHINSHE IKOKOAGBISHE SHANGO AGBISHE ORUN ABASHE AZOJUANO."]}]$q$::jsonb),
(252,'71c565798f8a8db4a37cb957e7c6c53c',$q$[{"titulo": "Idea central", "texto": "Òfún Ìká anuncia el fin de las dificultades de dinero y el comienzo de la abundancia; el trabajo o la carrera del consultante mejorarán mucho. Promete al heredero ocupar el título de su padre."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera una oportunidad de dinero después de las dificultades (relato de Ọ̀rúnmìlà).", "Un ascenso le trae obligaciones nuevas.", "Hay un asunto de sucesión en la familia (relato de Dekasi y el título de su padre)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Dinero después de la pobreza.", "Mejora clara en el trabajo.", "Ocupar el título del padre."]}, {"titulo": "Ibi y advertencias", "puntos": ["Seguir en apuros por no ofrendar."]}, {"titulo": "Enseñanza principal", "texto": "Òfún esparce cosas buenas: quien reparte kola como regalo recibe dinero."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà Aládé en la pobreza. Òfún esparce cosas buenas: así adivinaron para Ọ̀rúnmìlà cuando el príncipe sufría pobreza, y le pidieron una paloma, abundantes nueces de kola para regalar, aceite de palma y dinero para recibir dinero. Escuchó y ofreció. El aceite de palma se derrama sobre la piedra yangi de Èṣù, y la paloma se ofrece a la cabeza después de bañarse y ponerse ropa limpia y buena.", "Dẹ́kàsí y el trono del padre. Dẹ́kàsí, un hombre que nadie conocía como rey, decía que ocuparía el trono de su padre. Le pidieron seis palomas, dinero y medicina de Ifá para quedarse con el título. Ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para el dinero: una paloma, abundantes nueces de kola para regalar, aceite de palma sobre la piedra yangi de Èṣù y dinero; la paloma a la cabeza después del baño.", "Para el título: seis palomas, dinero y medicina de Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù recibe aceite en su piedra yangi. Orí recibe la paloma."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Obì (kola), aceite de palma, piedra yangi, ropa limpia."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 252.1 (yorùbá): Òfún-fún're-ká: / a difá fún Ọ̀rúnmìlà, / Alade mbẹ laarin ipónjú. / Wọ̀n niki Ọ̀rúnmìlà sa wa rúbo, / a r'owó gba. / Ebọ: Eyẹlé, opolopo obi (titore ni), / epo ati egberindilógún owó. / Ó gbọ̀ ó rú.", "Verso 252.2 (yorùbá): Òfún-Ká: / a difa fún Dekasi / (Çni Ọba ko kasi) / ti o nwipe oun kaṣaijoyè baba òun, / wọn niki o rúbo / kiobaale jẹ oyè baba rẹ. / Ebọ: Eyẹlé mẹfà, egbàá mẹfà owó ati ewé Ifá. / Ó rúbọ.", "NA", "REZO: OFUN KANA OKANA BIOFUN AWADO DE IFA OMO NI YARE AWAD IFA OBINI YANYARA ABURE OMO AW BE OBANA YABUN BOFUN KUIW YAKUN OMO BEIF YOROBAFUN OKANA BIOFUN OFUN KANA OBINI OKANA MAYORE AWO OKANA BIOFUN.", "REZO: OFIERA KOYA ABO NILOSO ADIFAFUN OSOKO LAYU OMA ABOYO ABOLEBO MAFEREFUN OBATALA ATI ESHU.", "REZO: OFUN KANA CANABI OFUN AGUADABO IFA AGUARI IYARE AGUADA UFA OBINI AYAYARA ABURE AGUADABO ACUABI OFUN TIWYA YURO AGUO BOIFA ANAYURO AGUO OKANABO OFUN."]}]$q$::jsonb),
(253,'264536c4d7996cfcc7252d8f227f2232',$q$[{"titulo": "Idea central", "texto": "Òfún Òtúrúpọ̀n habla de fertilidad y de ofrendar para evitar peleas en la pareja: los hijos traerán alegría, pero la relación necesita ayuda para no destruirse."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Desea tener hijos (relato de Ọbàtálá).", "Una relación puede incluir agresiones aunque parezca ofrecer familia (relato de la mujer que consulta antes de casarse).", "Debe separar el deseo de tener hijos de su seguridad con la pareja."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Muchos hijos que la elogian.", "Que todos vengan a pedirle hijos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Un marido que golpea.", "Confiar en la apariencia amable de la pareja."]}, {"titulo": "Enseñanza principal", "texto": "Dos caracoles nunca pelean y dos palomas nunca guardan ira en el cuerpo. La persona hermosa no debe pelear o su belleza se destruye."}, {"titulo": "Relatos reunidos", "puntos": ["Ọbàtálá y los hijos. A Ọbàtálá Ọṣẹ̀ẹ̀rẹ̀ Igbó le dijeron que tendría muchos hijos y que todo el mundo vendría a pedirle hijos; debía ofrendar para que esos hijos la elogiaran. Ella dijo que Ọ̀rúnmìlà les enseñaría, y le pidieron ofrecer para que Ọ̀rúnmìlà quedara contento con su trabajo: miel, sal, muchas gallinas, muchas palomas y dinero. Escuchó y ofreció.", "La mujer que buscaba marido. A una mujer que buscaba marido le dijeron que el hombre con quien quería casarse la golpearía siempre si no ofrecía un pangolín, dos caracoles, dos palomas y dinero, porque dos caracoles nunca pelean y dos palomas no guardan ira en el cuerpo. No ofreció: dijo que su futuro esposo era demasiado amable para pegarle a nadie."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para los hijos: miel, sal, muchas gallinas, muchas palomas y dinero.", "Para la paz en la pareja: un pangolín, dos caracoles, dos palomas y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ọbàtálá y Ọ̀rúnmìlà, maestros de los hijos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Miel, sal, caracoles, pangolín."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 253.1 (yorùbá): Òfún-Òtúrúpọ̀n: / a difá fún Ọbàtálá Oṣẹerẹ̀-igbó, / wọ̀n ni ọmọ a pọ lọwọ rẹ̀, / gbogbo ayé ni yoo maa wa torọ. / Wọ̀n niki o rúbọ / kiwọn le maayin ni / nitori àwọn omọ naa. / Ọbatálá I: / Ọ̀rúnmìlà a maakowọn. / Wọ̀n niki o rúbọ / ki inú Ọ̀rúnmìlà le dùn si (iṣé naa) i. / wọ̀n niki o rú: / Oyin, iyo, opplopo adiyẹ, / opolopo eyelẹ̀ ati egbaa mọ̀kanlélógún owó. / Ó gbọ̀ ó rú.", "Verso 253.2 (yorùbá): Òfún-Òtúrúpọ̀n: / a difa fún obirin kan / ti nw'okọ kiri. / Wọ̀n ni: / \"okọ ti o nlọ fe yi, / iyoo maa naa bi ko ba wa rúbo\". / Wọ̀n niki o rú: / Aiká, igbin Méjì / (igbín Méjì ki i bara wọ̀n jà), / ẹyẹlé Méjì / (eyẹlé Méjì kiibinu ara ọn) / ati egbàá mérindilógún owó. / Ó gbọ̀ ko rúbọ. / I: okọ òun dára pupo ko jẹ jà, / Arewà èniyàn ko gbọdọ jà / nitorii k'ẹwà ma bajẹ.", "REZO: OFUN BATRUPON MOYETE TE MOMO TENTE MANA OYUORO UNFO KEKE ADIFAFUN TOYE TINSHOMA ORO LEBO. EYA ORO, EYELE, ETU LEBO.", "IFA NI MAFEREFUN ESHU, SHANGO ATI OGGUN.", "REZO: OFUN BATUTO APROLO IFA MOYAIRE OLOKUN BAFUN ASHALO- DE OKUN BATIRE PON ELEWADE PEPEYE MOSAN KUN INTORI ARUN. ARUN LERI MESAN KUNYE OFO OYAIRE YEMAYA IYANI AWADO BAYO ANUMBAYE ILE OLOKUN AYO UMBO IRE ASHEGUN OTA KOLAMODI.", "REZO: OJIMBO OJOJO LENE TOTO MALA ADIFAFUN OBBA INNU EBBO MEYI LOMI TIMBOLOYU KAFEREFUN ORUNMILA.", "REZO: OFUN BATUTO APARODE IFA MOYAIRO OLOKUN, LODAFUN AGBALODE FOKUN BATRUPON, ELGUADO PEPEYE MOSOKUN, INTORI ORUN LERI MOSOKUN YE, OFO MOBADIRE INTORI ARUN LERI MOSOKUN YE OFO OYAIRE YEMAYA IYAMI, GBEDO BAYOUN OUNBAYE ILE OLOKUN AYO KUMBO, IRE ASHO GUN OTA, KOLE MODI."]}]$q$::jsonb),
(254,'0210b6138c92a6e40e6a3c75b8c7e8eb',$q$[{"titulo": "Idea central", "texto": "Òfún Òtúrá pide ofrendar para que la relación de pareja sea estable y duradera: el matrimonio con la pareja actual le conviene al consultante. Advierte no quedarse viviendo solo en la finca."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa casarse o vivir con su pareja y busca estabilidad (relato de Èṣù-Òdàrà y el aceite de palma).", "Teme que la relación se enfríe o termine.", "Un trabajo aislado le quita contacto con la gente (relato de Olówu y su granja)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una pareja que nunca se separa.", "Un mundo bueno para él."]}, {"titulo": "Ibi y advertencias", "puntos": ["Separación de la pareja.", "Quedarse solo en la finca."]}, {"titulo": "Enseñanza principal", "texto": "Òfún busca cosas dulces para comer: el aceite de palma y Èṣù no se separan."}, {"titulo": "Relatos reunidos", "puntos": ["Èṣù se casa con el aceite de palma. Òfún probó el aceite de palma, dejó caer ọ̀lẹ̀lẹ̀ en la sal y buscó cosas dulces para comer: así adivinaron para Èṣù Ọ̀dàrà cuando iba a casarse con el aceite de palma. Le pidieron tres gallos y dinero para que el cuerpo de su esposa quedara unido al suyo para siempre. Ofreció, y desde entonces Èṣù y el aceite de palma no se separan.", "Olówu y la finca. Àrẹ́rẹ́márẹ́ adivinó para Olówu y le dijo que el mundo sería bueno para él, pero que ofreciera tres carneros, tres azadones, tres machetes y dinero para no terminar viviendo solo en su finca. Ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la pareja: tres gallos y dinero.", "Para no quedarse solo: tres carneros, tres azadones, tres machetes y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù Ọ̀dàrà y su esposa, el aceite de palma."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma, ọ̀lẹ̀lẹ̀ (torta de frijol), sal, azadones, machetes."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 254.1 (yorùbá): Òfún-to'pola, / Òfún-fọlẹlẹbọ-iyẹ, / Òfún nwa ohun-to-dùn-todùn jẹ: / a difá fún Èṣú-Ọ̀dàrà / nlọ gbe Epo ni iyàwó. / A ni: / Wọn koniiya ara wọn titi laelae, / kiwọ̀n rúbọ: / Akuko méta, egbàá méta owó. / Ó gbọ̀ ó rú.", "Verso 254.2 (yorùbá): Areremare, / Areremare: / lo difa fun Olówu. / Wọ̀n ni: / Bi ayé ti nyẹ Olú to yi, / ki Olú wa rúbọ / ki o ma baa di eni oko. / Ebọ: Agbo mẹta, oko (riroko) méta, àdá méta / ati egbàá méta owó. / Ó gbọ̀ ó rú.", "REZO: OFUN TEMPOLA BOYU OBE PONIBIO OKU KIRO NIBIDE ADIFAFUN ALAPANI AKUKO, IGI LANGUI, AKUKO, EYELE LEBO.", "REZO: OFUN TEMPOLA AWO AYE AWO EPO AGUNTAN LEBO. OFUN TAR IFA ADAKOY.", "REZO: OFUN TO KOLA TO OYU BADI LONI ADAKE.", "REZO: OFUN BIRETE OFUN AWARE KABU ADIFAFUN OLOS LORDAFUN ANANAGU INY OBINI TENTE OKOE.", "REZO: AYEREDIYO WO OBE AGUTAN DIYOWO AY LORDAFUN ARI EGGUN LOLA OMO ABERIN KOLOMO TAYI OMO ORDENI ORDE ALAYEGUN OMO ALA YEGUN YELE AHISIN NI BIMARU.", "REZO: BEYU OBA NIBI OKO KIRENI BIDE ADIFAFUN ALPINI GUTANLE INFAN BI EÑA AKUKO INGUI AFEREWEWE ADUFAFUN AYABE IMBATISHE OLOGBO ERU ILE.", "REZO: OFUN TOCOLA AWO AWODEIFA BALLIBARE OFUN BALLEOFUN DE KOLA AWO OMO. OMO NI YANZA AWA NI AWO ABONILLAWO INLE BEILLEKUN INTORI OBIGUI ODE OFUN BALLEOFUN NI SHANGO AWO OMO OBAYE INLE ABEBOFUN INLE ABEBOFUN.", "REZO: MAFERFUN BEYU OBA PANI BI IKU BIDE BELE BELE ABO ALA EGUNGUN ADIFAFUN ALAPINI AWO ABO GUTANLE INFAN BI EÑA IGUI LAGUI SOKUN LAYE ABO AFERE WERE OYU ADIFAFUN AYABE OBA INBANTISHE OLOGBO ERU ILE OBALUAYE ASHE TERENISHO OMA OBIRI YERO MOFEO ABO LONIYE ADIFAFUN OMAKOYE AWO YOBO OLOFIN AWO ODARA AYE MIMO SOKUN EYENIKORO ADIFAFUN SHANGO.", "REZO: OFUN TEMPOLA IFA OWO EYE OWO EPO AGUTAN LEBO AIKOR- DIE MEYI OWO LA MEYO, EKU, EYA, ESHISHI OFUN TURA IFA ADAKOY."]}]$q$::jsonb),
(255,'d007a2a983c517d654ce518505338443',$q$[{"titulo": "Idea central", "texto": "Òfún Ìrẹtẹ̀ pide ofrendar para obtener respeto y protección. El consultante necesita salir de la situación en la que está y tener más seguridad en sí mismo. Promete que nadie podrá conspirar contra él."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere salir de un ambiente o un hábito que lo tiene estancado y recuperar la seguridad en sí mismo.", "Busca que lo respeten por lo que hace y no solo por su puesto (relato de Olúṣẹso).", "Teme que otros bloqueen sus acuerdos o proyectos (relato de Omi)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Respeto de todos.", "Que nadie conspire contra él ni lo boicotee."]}, {"titulo": "Ibi y advertencias", "puntos": ["Inseguridad.", "Conspiraciones y boicot."]}, {"titulo": "Enseñanza principal", "texto": "Me disciplinaron y yo me volví a disciplinar a mí mismo. El que se hace enemigo del agua muere antes de tiempo."}, {"titulo": "Relatos reunidos", "puntos": ["Olúṣẹ̀sọ̀ y lo que agrada al mundo. Me entrenaron y yo me volví a entrenar: así adivinaron para Olúṣẹ̀sọ̀, y le dijeron que siguiera haciendo lo que agrada al mundo, y que ofreciera cuatro palomas, dinero y medicina de Ifá para que todos lo respetaran. Ofreció.", "El agua. Òfún Ìrẹtẹ̀ adivinó para el Agua y le pidió sal, aceite de palma, una paloma, una tortuga, una tela jaspeada y dinero para que nadie pudiera conspirar contra ella ni boicotearla. Escuchó y ofreció, y se dijo: el que se haga enemigo del agua morirá antes de tiempo. La tela jaspeada es para que el consultante se cubra el cuerpo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para el respeto: cuatro palomas, dinero y medicina de Ifá; infusión de hojas de àgbọ̀nyìn y agbayunkun para lavar la cabeza del consultante y su Ifá.", "Contra las conspiraciones: sal, aceite de palma, una paloma, una tortuga, una tela jaspeada para cubrirse y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Omi, el agua."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Àgbọ̀nyìn (Piptadeniastrum africanum), agbayunkun, sal, aceite de palma, tela jaspeada."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 255.1 (yorùbá): Wọ̀n tẹ̀ mi, / Mo tún'ra mi tẹ̀: / a difa fún Olúṣẹso. / Wọ̀n nì: / Eyiti o dára loju ayé ni / yoo maa wu Olúṣẹso lati ṣe. / Wọ̀n niki o wa rúbọ, / ki àwọn omọ aráyé / le maa bu'yin fün un. / Ẹbọ: Ẹyelé mérin, egbàá méwa owó ati ewé Ifá / Ó gbọ̀ ó rú.", "Verso 255.2 (yorùbá): Òfún-Rẹte: / a difa fún Omi. / Wọ̀n niki o wa rúbọ, / wọ̀n nì: / Enikeni ko maa ṣ'ọtẹ̀ rẹ̀ laelae. / Ebọ: lyo, epo, ẹyẹlé, / Ọbahun (ljapá), aṣo-etu, / egberindilógún owó. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"Eniti o nba Omi iṣ'ote / 1 yoo kú ikú ait'ẹjo\".", "REZO: OFUN BILE NENE AHUBO BADEY APOLO ABI ÑAKI ADIFAFUN LAURE UMBATINLO BALE NIFA AKUKO LEBO. ABIYE ADIFAFUN AMISISI, AIKORDIE, EYELE, AKUKO LEBO.", "REZO: OFUN RETE OFUN AGU ETE ABU ARDIFAFUN LLILESE OLORDAFUN ANEGU INLLA OBINI TONTO OSOE.", "REZO: ALLORDILLO GUO ORBO AGUTAN DILLUGO ALLA ORDAFUN ARIEGUN LOLA OMO ABERICOLOMO TELLI OMO ORBENI ORDE ALA LLEGUN OMU ALA LLEGUN ALALLELEHISIN NI VI MARE.", "REZO: MAME CHUGUO BADELLA POLO ABANAKI ADIFAFUN LAURO UMBA TILO BANTI NIFA ACUCO LEBO ABICHE ADIFAFUN AMISISI OMO OLOFIN ADIE IEBO EYELE LEBO.", "REZO: OFUN RETE OFUN AGU ATE A BU ADIFAFUN OLILESO LORDA- FUN ANEGU INLLA OBINI TONTO ESOS.", "REZO: OFUN BILE OFUN AWATE OKANIBU ADIFAFUN AWO OLOSHE ADIFAFUN AMEGUN IYA ODINI TONTIN EKUN AYEBIYO EGGUN EBBO ADAJUN ORUN BEYENI ORI EGGUN LOIA, LODA- FUN ORUNMILA OMO ABARIN OKOLONO OMO OBENI ADE ALAYE EGGUN OMO ALA TEGUN OWALE AHISHI ONI BI OLODUN MARE KFEREFUN OGGUN AMEGUN ERI BABAWA.", "REZO: OFUN BILE OFUN OGUETE KOBU ADIFAFUN OLELESE OLODE OFUN ENEGUN IYA OBINI TONTO OKO.", "REZO: OFUN BILE IRETE RETE ADIFAFUN OLOFIN UMBO ATO INSHE OBOTO ADIFAFUN OMA OFU OSOKUN LODO OMI IRETE AZOJUA- NO ELEGBARA ADIFAFUN ORUNMILA OBOKUN LOLO LOMI OMO OBATALA AKUÑOÑE MINA RORONILE ANLAMUNO AÑICUN LAMIRE ORUNMILA LANTE ELEGBABARA LAMPE AZOWANO."]}]$q$::jsonb),
(256,'98bc5dcebe7dcec97f738f6d13ad171d',$q$[{"titulo": "Idea central", "texto": "Òfún Ọ̀ṣẹ́ habla de venganza y advierte de una posible pérdida: quienes intentan impedir el progreso del consultante sufrirán. Promete que el que no ofendió verá a su vengador cobrar por él, y que el anciano del que todos se burlan será honrado por todos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme perder algo que acaba de conseguir (relato de Enimani).", "Se siente agraviado por acusaciones o conspiraciones.", "Debe decidir cómo responder sin hacer más daño.", "Tiene un malestar que no sabe explicar y además problemas de dinero; conviene revisarse con un médico."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que el vengador cobre a quien le hizo daño.", "Un lugar importante que llega.", "Riqueza en la vejez y el respeto de todos.", "Hijos para quien tiene muchas esposas."]}, {"titulo": "Ibi y advertencias", "puntos": ["Que las cosas se pierdan temprano.", "Un enemigo que le quita el puesto.", "Embarazo que se pierde por las brujas."]}, {"titulo": "Enseñanza principal", "texto": "Ustedes que pensaban que yo estaba acabado, traigan sus platos y vengan a comer. Òfún no ofendió ni planeó mal contra nadie: el vengador cobra por él."}, {"titulo": "Relatos reunidos", "puntos": ["Ẹnímànì en la ciudad de los hechiceros. A Ẹnímànì, que vivía en la ciudad de los hechiceros, le pidieron una tortuga, un caracol, medicina de Ifá y dinero para que sus cosas no se perdieran temprano. Oyó y no ofreció.", "Òfún y el vengador. Òfún no ofendió ni planeó mal contra nadie, pero conspiraron contra él. Le pidieron una tortuga, un cuchillo, cáscaras de nuez de palma de tres ojos y dinero para que el Vengador les hiciera pagar a todos. Ofreció, y el adivino le preparó medicina de Ifá para ponerla bajo su almohada.", "Olóbùtù, el rey de los pájaros. Es blanco de repente adivinó para Olóbùtù, rey de los pájaros de la finca, y le dijo que ese año su cabeza lo llevaría a su destino, pero que ofreciera la túnica roja con que se adornaba, una oveja, dinero y una tinaja de aceite de palma para que un enemigo no lo empujara fuera del puesto. No ofreció. Cuando lo hicieron rey no hizo el bien, y todos los pájaros le quitaron el título; la túnica roja se le ve todavía en el cuello, y pusieron en su lugar a la garza blanca (ọ̀kín), cuyas plumas adornan las coronas.", "Ṣẹ̀rẹ̀kẹ́ y la lluvia blanca. La brisa suave baja a la tierra desde lo alto de la finca, la lluvia de Àpà cae inclinada: así adivinaron para Ṣẹ̀rẹ̀kẹ́. Hay alguien con muchas esposas que no le han dado hijos; Ifá le abrirá ese año el camino de los hijos. Se ofrece una chiva junto a un agua quieta cercana, con toda su gente acompañándolo.", "Àbọ̀nún y la chiva fiada. Àbọ̀nún era un hombre pobre y muy viejo, y sus parientes se burlaban de él. Ifá le pidió una chiva. Fue al mercado, la compró fiada y le dijo a la vendedora que viniera a cobrar pasado mañana. La mató, la repartió entre toda la gente de su casa, y al día siguiente, viendo que no tenía con qué pagar, huyó al monte. Caminando por el monte, se hundió en un pozo de cuentas. La vendedora vino a cobrar y la gente le decía: ¿por qué le vendiste? ¿de dónde va a sacar para pagarte? Ella se sentó a esperarlo. Àbọ̀nún volvió y le dio un paquete de cuentas envuelto en hojas; ella se fue con miedo. Al año siguiente Àbọ̀nún era rico, ofreció una vaca a su Ifá, mandó hacer un guiso y cantó: ustedes que pensaban que yo estaba acabado, traigan sus platos y vengan a comer.", "La tela que no retiene el embarazo. Exprimir la tela, adivino de la Tela, adivinó para la Tela cuando lloraba porque no tenía hijos. Le dijeron que quedaría embarazada, pero que ofreciera contra las brujas una tela de cintura, una chiva y dinero. No ofreció. Cuando quedó embarazada, el embarazo se le fue del cuerpo, y decía: si hubiera sabido, habría hecho la ofrenda. Por eso las burbujas que salen al exprimir la tela nunca duran. La mujer embarazada debe ofrecer para que el embarazo no se le vaya; conviene también llevar control médico."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para que las cosas no se pierdan: una tortuga, un caracol, medicina de Ifá y dinero.", "Para el vengador: una tortuga, un cuchillo, cáscaras de nuez de palma de tres ojos y dinero; medicina bajo la almohada.", "Para conservar el puesto: la túnica roja, una oveja, dinero y una tinaja de aceite de palma.", "Para hijos: una chiva ofrecida junto a un agua quieta.", "Para el anciano: una chiva a Ifá.", "Por el embarazo: una tela de cintura, una chiva y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "El Vengador. El dios del cielo abre caminos de dinero. Las brujas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Cáscaras de nuez de palma de tres ojos, tortuga, caracol, cuentas, aceite de palma, tela."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 256.1 (yorùbá): Òfún-Sé: / a difá f'Enimani ilú Oṣó (il'Oṣó), / wọn niki o wa rúbo / kioma baa fi ohun-ini tiyoo ṣ'ofo / ṣẹ'wọ ni kutukutu owuro (ohun-akoni). / Ebọ: Ọbahun (ljapá),igbín / ati ewé Ifá pẹlu egbètalélógbon / Ó gbọ̀ ko rúbọ.", "Verso 256.2 (yorùbá): Òfún koṣẹ, / Òfún koro, / wọ̀n ndunrunmo Òfún, / Wọ̀n niki Òfún wa rúbọ / ki Çlẹsan le maa baa san ibi / wọn fún wọn. / Ẹbọ: İjapá, obẹ, eesan (ekurẹ) / ati egbèsan owó. / Ó gbọ̀ ó rú. / Wọ̀n ṣe ewé Ifá fún un, / o nfi rọ orí sun.", "REZO: OFUN SHE ADIFAFUN IYA, ADIFAFUN ORUNMILA, ADIFAFUN OBATALA, ADIFAFUN OSHUN AKOSHE LOKO AKEYI ALAKE LORUBO.", "SUREYE: EBBO SHEKE SHEKE AKUKO LEBO. EBBO SHEKE SHEKE EYELE LEBO. EBBO SHEKE SHEKE ADIE LEBO. EBBO SHEKE SHEKE EYA TUTU LEBO.", "REZO: ADIFAFUN OFUN SHEWE AWO IVA LOVI ENIGBO EJOLA MAMO GUARA ARUM SHE NI ABOÑU MOKEKERE ELEGBA ARIKU AWO LODAFUN ORUNMILA.", "REZO: OFUN SHE ADIFAFUN IYA, ADIFAFUN ORUNMILA, ADIFA- FUN OBATALA ADIFAFUN OSHUN AKOSHE LOKO AKEYI ALAKE LORUBO.", "+++ 396"]}]$q$::jsonb))
update estera_sintesis e set secciones=v.sec from nuevas v where e.numero=v.numero and md5(e.secciones::text)=v.viejo returning e.numero;
